(window.GIM_TS=window.GIM_TS||{})["Arakhin.2"]={"from":48,"a":[["\u0003מ\u0004מקדיש ביתו שהוא \u0003קדשי בדק הבית, ואין דנין\u0004 שדה היוצאת לכהנים, שהיא \u0003קדשי בדק הבית, מ\u0004כבשי עצרת, שהם \u0003קדשי מזבח.\u0004","ושואלים: \u0003ור' שמעון נמי\u0004 \u0005[גם כן],\u0006 \u0003נילף\u0004 \u0005[שילמד]\u0006 \u0003מ\u0004\"קודש\" שנאמר ב\u0003מקדיש בית!\u0004 ומשיבים: \u0003דנין\u0004 שדה היוצאת לכהנים, שהיא \u0003דבר ש\u0004הוא \u0003מתנה לכהנים, מ\u0004כבשי עצרת, שהם \u0003דבר שמתנה לכהנים, ואין דנין דבר ש\u0004הוא \u0003מתנה לכהנים,\u0004 שדה היוצאת לכהנים, \u0003מ\u0004מקדיש ביתו, שהוא \u0003דבר שאינו מתנה לכהנים.\u0004","שנינו במשנה כי המקדיש שדהו והגיע היובל ולא נגאלה, \u0003ר' אליעזר אומר:\u0004 הכהנים \u0003לא נכנסין\u0004 לתוכה \u0003ולא נותנין\u0004 את דמיה, ולעולם אין הכהנים נכנסין לתוכה עד שיגאלנה אחר, ותצא מידו.","\u0003אמר רבה: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' אליעזר? אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ואם לא יגאל את השדה, ואם מכר את השדה לאיש אחר לא יגאל עוד. והיה השדה בצאתו ביובל קודש לה' כשדה החרם לכהן תהיה אחוזתו\" (ויקרא כז, כ—כא), ויש לחלק את הכתוב לשני דינים שונים ולדרוש: \u0003\"ואם לא יגאל\u0004 (המקדיש) \u0003את השדה\u0004 — \u0003לא יגאל עוד\"\u0004 להיות שדה אחוזתו, \u0003\"ואם מכר\u0004 (הגזבר) \u0003את השדה\u0004 לאיש אחר\" — \u0003\"והיה השדה בצאתו ביובל...\u0004 לכהן\". ולפי זה, אם לא נמכרה השדה לאדם אחר — אינה יוצאת לכהנים ביובל.","\u0003אמר אביי:\u0004 וכי \u0003סכינא חריפא מפסקא קראי\u0004 \u0005[סכין חדה חותכת\u0006 את \u0005הפסוקים]?\u0006 כיצד ניתן להפריד בין חלקי הכתוב? \u0003אלא אמר אביי, טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' אליעזר\u0004 הוא \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]\u0006 על כתוב זה: \"ואם לא יגאל את השדה ואם מכר (הגזבר) את השדה לאיש אחר \u0003לא יגאל\"\u0004 — \u0003יכול לא תהא נגאלת\u0004 על ידי הבעלים כלל, ואפילו \u0003שתהא לפניו כשדה מקנה\u0004 שנמצאת בידו עד היובל? \u0003תלמוד לומר: \"עוד\",\u0004 לומר: \u0003לכמות שהיתה,\u0004 כשדה אחוזה, \u0003אינה נגאלת, אבל נגאלת שתהא לפניו כשדה מקנה,\u0004 שיוצאת ביובל.","ונברר: \u0003אימת\u0004 \u0005[אימתי]\u0006 מדבר הכתוב הזה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ב\u0004תקופת ה\u0003יובל ראשון,\u0004 כשהקדישה — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינה נגאלת\u0004 לכמות שהיתה? והרי אז \u0003שדה אחוזה נמי הויא\u0004 \u0005[גם כן היא],\u0006 שאם גאלה הבעלים — אינה יוצאת מידו ביובל! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר \u0003ב\u0004תקופת ה\u0003יובל שני,\u0004 שהקדישה ולא גאלה, ועברה שנת היובל.","ונברר: \u0003ולמאן\u0004 \u0005[ול\u0006שיטת \u0005מי]\u0006 מדובר בברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה ור' שמעון,\u0004 הלא \u0003לכהנים נפקא\u0004 \u0005[יוצאת]\u0006 ביובל הראשון, ושוב אין בידו לפדותה מידם! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 לשיטת \u0003ר' אליעזר\u0004 היא, הסבור שאם לא נגאלה ביובל הראשון — אין הכהנים נכנסים לתוכה, אלא הריהי נשארת ביד ההקדש, וכך ניתן לגואלה ביובל השני? \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003טעמא\u0004 \u0005[טעמו]\u0006 של \u0003ר' אליעזר מהכא\u0004 \u0005[מכאן]\u0006 הוא, מייתור המלה \"עוד\", כפי שהסברנו את הברייתא.","ותוהים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שיש הכרח להסביר כך? אם כן, \u0003ר' יהודה ור' שמעון האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"עוד\" מאי דרשי ביה\u0004 \u0005[מה\u0006 הם \u0005דורשים בו]?\u0006 \u0003אלא\u0004 יש לפרש ברייתא זו לשיטתם: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בשדה\u0004 אחוזה שהקדישה בעליה ולא פדאה, \u0003שיצאה לכהנים\u0004 ביובל הראשון, \u0003והקדישה\u0004 ה\u0003כהן\u0004 שקיבלה, ואתו \u0005[ובאים]\u0006 ה\u0003בעלים\u0004 הראשונים \u0003למיפרקה\u0004 \u0005[לפדות אותה]\u0006 מההקדש;","\u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 הואיל ולא גאלה בתקופת היובל הראשון, לכן \u0003לא תיפרוק\u0004 \u0005[לא תיגאל]\u0006 על ידו כעת, ואפילו \u0003שתהא לפניו כשדה מקנה\u0004 — \u0003תלמוד לומר: \"עוד\",\u0004 לומר: \u0003לכמות שהיתה אינה נגאלת,\u0004 כלומר, לחזור להיות כשדה אחוזתו, \u0003אבל נגאלת\u0004 על ידו, \u0003שתהא לפניו כשדה מקנה,\u0004 ותצא לכהנים ביובל.","ומוסיפים: \u0003והתניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא בענין דומה\u0005],\u0006 נאמר במי שקנה שדה והקדישה, ופדאה: \u0003\"בשנת היובל ישוב השדה לאשר קנהו מאתו\"\u0004 (ויקרא כז, כד), \u0003יכול\u0004 שפירושו ש\u0003יחזור\u0004 השדה \u0003לגזבר שלקחו ממנו\u0004 כשפדאו? \u0003תלמוד לומר\u0004 מיד לאחר מכן: \u0003\"לאשר לו אחזת הארץ\"\u0004 (שם) — למי שמכר לו את השדה מתחילה.","אלא שאם כך די ש\u0003יאמר: \"לאשר לו אחזת הארץ\", מה תלמוד לומר \"לאשר קנהו מאתו\"?\u0004 כתוב זה מלמדנו לגבי \u0003שדה\u0004 (אחוזה) שהקדישה בעליה ולא פדאה, \u0003שיצאת לכהנים\u0004 כשהגיעה שנת היובל, \u0003ומכרה\u0004 ה\u0003כהן\u0004 שקיבלה, \u0003והקדישה\u0004 ה\u0003לוקח, וגאלה\u0004 אדם \u0003אחר\u0004 מההקדש, והגיעה שנת היובל הבאה, \u0003יכול תחזור לבעלים הראשונים,\u0004 שהקדישה במהלך תקופת היובל הקודם? \u0003תלמוד לומר:\u0004 \"ישוב השדה \u0003לאשר קנהו\u0004 מאתו\", כלומר, למי שמכר שדה זו, והוא הכהן (אבל הבעלים הראשונים לא מכרה, אלא הקדישה).","ומסכמים: \u0003ואיצטריך\u0004 \u0005[והוצרך\u0006 לומר\u0005]\u0006 \u0003\"לא יגאל\" ואיצטריכא למיכתב\u0004 \u0005[והוצרך לכתוב]:\u0006 \u0003\"לאשר קנהו\u0004 מאתו\", למרות ששניהם מלמדים לכאורה דין זהה, שלאחר שנכנס הכהן לתוכה ביובל — שוב אינה חוזרת לידי הבעלים הראשונים כשדה אחוזה.","\u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"לא יגאל\",\u0004 היינו אומרים כי דווקא במקרה שהכהן הקדישה וגאלה הבעלים הראשונים — אין היא חוזרת לידי הבעלים הראשונים, מפני ששדה שהוקדשה ונגאלה על ידי אחר \u0003לא קא הדרה\u0004 \u0005[אינה חוזרת]\u0006 \u0003כלל,\u0004 אלא מתחלקת בין כל הכהנים. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 בכהן שמכר את השדה שקיבל, ואחר כך הקדישה הקונה, וגאלה אחר, \u0003דקא הדרה\u0004 \u0005[ש\u0006במקרה זה \u0005חוזרת]\u0006 שדה לבעליה ביובל — שמא \u0003תיהדר למרה קמא\u0004 \u0005[תחזור לבעלה הראשון],\u0006 לפיכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"לאשר קנהו\u0004 מאתו\", ללמד שהיא חוזרת לידי הכהן.","ומצד אחר, \u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \u0003\"לאשר קנהו\",\u0004 הייתי אומר שדווקא כאשר מכרה הכהן והקונה הקדישה, אינה חוזרת לבעליה הראשונים ביובל, משום \u0003דלא קא יהבי בעלים דמי\u0004 \u0005[ש\u0006במקרה זה \u0005לא נותנים הבעלים\u0006 הראשונים שום \u0005דמים]\u0006 להקדש, \u0003אבל הכא\u0004 \u0005[כאן],\u0006 כשהקדישה הכהן ובאו בעליה הראשונים ופדוה, \u0003דקא יהבי דמי\u0004 \u0005[שהם נותנים דמים]\u0006 להקדש — שמא \u0003תיקום בידייהו\u0004 \u0005[תעמוד בידם]\u0006 ותחזור להיות שדה אחוזתם, לפיכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"לא יגאל\".\u0004","ומוסיפים: \u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \u0003\"לא יגאל\", ולא כתב\u0004 \u0005[היתה כותבת]\u0006 \u0003\"עוד\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 מכיוון שלא גאלה בעליה הקודם בתקופת היובל הראשון — \u0003לא תיפרוק\u0004 \u0005[לא תיגאל]\u0006 כעת על ידו \u0003כלל,\u0004 לפיכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"עוד\",\u0004 לומר: \u0003לכמות שהיתה אינה נגאלת, אבל נגאלת שתהא לפניו כשדה מקנה,\u0004 שיוצאת ממנו ביובל.","ושואלים: ומאחר ונדחו שתי ההצעות הקודמות, \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה],\u0006 כלומר, מהיכן לומד ר' אליעזר את שיטתו ששדה שלא נגאלה אינה יוצאת לכהנים ביובל? \u0003אמר רבא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והיה השדה בצאתו ביובל\u0004 קדש לה' כשדה החרם לכהן תהיה אחוזתו\" (ויקרא כז, כא), והמילה \"בצאתו\" מלמדת שרק \u0003בצאתו\u0004 ביובל \u0003מיד אחר\u0004 (שקנהו מן ההקדש) יהפוך השדה לאחוזת הכהן."],["ושבים לדון בשיטת ר' אליעזר שאמר במשנתנו, כי המקדיש שדה אחוזתו ולא נגאלה — אין הכהנים נכנסים לתוכה עד שיגאלנה אחר תחילה. וכך \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: לשיטת ר' אליעזר, \u0003בעלים\u0004 שהקדישו את שדה האחוזה בתקופת היובל הראשון, ולא נגאלה, וגאלוה הם \u0003ב\u0004תקופת ה\u0003יובל שני,\u0004 האם \u0003כאחר דמו\u0004 \u0005[נחשבים],\u0006 ותצא לכהנים בהגיע שנת היובל הבאה, \u0003או לא,\u0004 אלא דינה כאילו פדה אותה בתקופת היובל הראשון, ותישאר בידו?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: נאמר בתורה \"ואם לא יגאל את השדה ואם מכר את השדה לאיש אחר \u0003לא יגאל\"\u0004 — \u0003יכול לא תהא נגאלת\u0004 על ידו כלל, ואפילו \u0003שתהא לפניו כשדה מקנה\u0004 עד היובל? \u0003תלמוד לומר: \"עוד\",\u0004 לומר: \u0003לכמות שהיתה,\u0004 כשדה אחוזה, \u0003אינה נגאלת, אבל נגאלת שתהא לפניו כשדה מקנה,\u0004 ויוצאת ביובל.","ונברר: \u0003אימת\u0004 \u0005[אימתי]\u0006 מדבר הכתוב הזה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ב\u0004תקופת ה\u0003יובל ראשון\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינה נגאלת\u0004 לכמות שהיתה? והרי אז שדה \u0003אחוזה נמי הויא\u0004 \u0005[גם כן היא],\u0006 וגואל אדם את שדה אחוזתו! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר \u0003ב\u0004תקופת ה\u0003יובל שני.\u0004","ונברר: \u0003ולמאן\u0004 \u0005[ול\u0006שיטת \u0005מי]\u0006 מדובר בברייתא זו? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה ור' שמעון\u0004 — הלא \u0003לכהנים נפקא\u0004 \u0005[יוצאת]\u0006 כבר בהסתיים תקופת היובל הראשון, ואין בידו לגואלה מידם! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003ל\u0004שיטת \u0003ר' אליעזר\u0004 היא, הסבור שכל עוד לא גאלה אחר אינה עוברת ליד הכהנים ביובל, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שלשיטתו \u0003בעלים\u0004 שפדו את שדה אחוזתם מן ההקדש \u0003ב\u0004תקופת ה\u0003יובל\u0004 ה\u0003שני כאחר דמו\u0004 \u0005[נחשבים],\u0006 ותצא מידם לכהנים בהגיע שנת היובל.","ותוהים: \u0003ותסברא\u0004 \u0005[\u0006וכי \u0005סבור אתה]\u0006 שכך יש להסביר את הברייתא? אם כן, \u0003ר' יהודה ור' שמעון האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"עוד\" מאי דרשי ביה\u0004 \u0005[מה\u0006 הם \u0005דורשים בו]?\u0006 \u0003אלא\u0004 ניתן להסביר ברייתא זו באופן אחר, לשיטת ר' יהודה ור' שמעון: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בשדה\u0004 (אחוזה) שהקדישה בעליה ולא פדאה\u0003, שיצאה לכהנים\u0004 ביובל הראשון, \u0003והקדישה\u0004 ה\u0003כהן\u0004 שקיבלה, \u0003ואתו\u0004 \u0005[ובאים]\u0006 ה\u0003בעלים\u0004 הראשונים \u0003למיפרקה\u0004 \u0005[לפדות אותה]\u0006 מההקדש; \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 הואיל ולא גאלה בתקופת היובל הראשון, לכן \u0003לא תיפרוק\u0004 \u0005[לא תיגאל]\u0006 על ידו כעת, ואפילו \u0003שתהא\u0004 לפניו \u0003כשדה מקנה, תלמוד לומר: \"עוד\"\u0004 — \u0003לכמות שהיתה אינה נגאלת,\u0004 כלומר, לחזור להיות כשדה אחוזתו, \u0003אבל נגאלת שתהא לפניו כשדה מקנה.\u0004","ומוסיפים: \u0003והתניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא בענין דומה\u0005],\u0006 נאמר במקדיש שדה מקנה ופדאה מיד ההקדש: \"בשנת היובל \u0003ישוב השדה לאשר קנהו מאתו\"\u0004 (ויקרא כז, כד), \u0003יכול\u0004 ש\"לאשר קנהו מאתו\" פרושו ש\u0003יחזור\u0004 השדה \u0003לגזבר שלקחה הימנו\u0004 (שפדאה ממנו)? \u0003תלמוד לומר: \"לאשר לו אחזת הארץ\"\u0004 (שם) — לבעלים הראשונים.","אלא שאם כך די שייאמר: \"לאשר לו אחוזת הארץ\", \u0003מה תלמוד לומר \"לאשר קנהו\u0004 מאתו\"? כתוב זה בא ללמד על \u0003שדה\u0004 אחוזה שהקדישה בעליה ולא פדאה, \u0003שיצאה לכהנים\u0004 כשהגיעה שנת היובל, \u0003ומכרה\u0004 ה\u0003כהן\u0004 שקיבלה, \u0003והקדישה\u0004 ה\u0003לוקח, וגאלה אחר\u0004 מההקדש, והגיעה שנת היובל הבאה, \u0003יכול תחזור לבעלים הראשונים,\u0004 שהקדישה במהלך תקופת היובל הקודם? \u0003תלמוד לומר:\u0004 \"ישוב השדה \u0003לאשר קנהו\u0004 מאתו\", כלומר, לכהן שקיבלה ביובל כאחוזתו, ומכרה אחר כך.","ומעירים: \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"לא יגאל\" ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"לאשר קנהו\u0004 מאתו\", למרות ששניהם מלמדים לכאורה דין אחד, שלאחר שנכנס הכהן לשדה ביובל — שוב אינה חוזרת לידי הבעלים הראשונים כשדה אחוזה, \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת\u0006 \u0005התורה]\u0006 רק \u0003\"לא יגאל\",\u0004 היינו אומרים כי דווקא במקרה שהכהן הקדישה, אין היא חוזרת כשדה אחוזה לבעלים הראשונים, מפני ששדה שהוקדשה ונגאלה על ידי אחר \u0003לא קא הדרה\u0004 \u0005[אינה חוזרת]\u0006 \u0005כלל, אלא מתחלקת לכל הכהנים ביובל. אבל כשמכרה הכהן והקדישה הקונה, שאז חוזרת שדה לבעליה ביובל — שמא תחזור לבעליה הראשונים, לפיכך\u0006 \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"לאשר קנהו\u0004 מאתו\", ללמד שתחזור לכהן.","ומצד אחר, \u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק: \u0003\"לאשר קנהו\",\u0004 הייתי אומר שדווקא כאשר מכרה הכהן והקונה הקדישה, אינה חוזרת לבעליה הראשונים ביובל, משום \u0003דלא קיהבי בעלים דמי\u0004 \u0005[ש\u0006במקרה זה \u0005לא נותנים הבעלים\u0006 שום \u0005דמים]\u0006 להקדש, \u0003אבל הכא\u0004 \u0005[כאן],\u0006 כשהקדישה הכהן, ובאו בעליה הראשונים ופדוה, \u0003דיהבי בעלים דמי\u0004 \u0005[שנותנים הבעלים דמים]\u0006 להקדש, הייתי אומר \u0003דתיקום בידיהו\u0004 \u0005[שתעמוד בידם]\u0006 ותחזור להיות שדה אחוזתם, לפיכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"לא יגאל\".\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \u0003\"לא יגאל\", ולא כתב\u0004 \u0005[היתה כותבת]\u0006 \u0003\"עוד\", הוה אמינא\u0004 \u0005[הייתי אומר],\u0006 כי מכיוון שלא גאלה בעליה הקודם בתקופת היובל הראשון, \u0003לא תיפרוק\u0004 \u0005[לא תיגאל]\u0006 כעת על ידו \u0003כלל,\u0004 לפיכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"עוד\",\u0004 לומר: \u0003לכמות שהיתה אינה נגאלת, אבל נגאלת שתהא לפניו כשדה מקנה,\u0004 שיוצאת ממנו ביובל. ונמצא שלא נפתרה השאלה, מה היא דעת ר' אליעזר לגבי מקדיש שדה אחוזתו ולא נפדתה עד שנת היובל, ופדוה הבעלים בתקופת היובל השני, האם דינו כאחר, והיא יוצאת לכהנים ביובל.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה],\u0006 כיצד פתרו את השאלה? ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא, \u0003ר' אליעזר אומר: גאלה בעלים ב\u0004תקופת ה\u0003יובל שני\u0004 — \u0003יוצאה לכהנים ב\u0004הגיע שנת ה\u0003יובל.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: האנן לא תנן הכי\u0004 \u0005[הרי אנו לא שנינו כך]\u0006 במשנה, אלא כך \u0003ר' אליעזר אומר\u0004 ב משנתנו: \u0003אין הכהנים נכנסין לתוכה עד שיגאלנה אחר! אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: ה\u0003בעלים ביובל שני כאחר דמו\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 שכך היתה שנויה הברייתא שהביאו, \u0003ר' אליעזר אומר: גאלה ביובל שני\u0004 — \u0003אינה יוצאה לכהנים ביובל.\u0004 ועל כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 מדוע צריך להוכיח זאת מברייתא? והרי \u0003אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 במשנתנו, ש\u0003ר' אליעזר אומר: אין הכהנים נכנסין לתוכה עד שיגאלנה אחר! אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אי ממתניתין הוה אמינא\u0004 \u0005[אם ממשנתנו הייתי אומר]:\u0006 \u0003בעלים ביובל שני כאחר דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיעה לנו]\u0006 הברייתא שר' אליעזר סבור שאינם כאחר, והשדה חוזרת להיות שדה אחוזתו.","\u0003הלוקח\u0004 (קונה) \u0003שדה\u0004 אחוזה \u0003מאביו, ומת אביו, ואחר כך הקדישה\u0004 הבן — \u0003הרי היא\u0004 לגביו \u0003כשדה אחוזה\u0004 שהקדישה. אבל אם \u0003הקדישה\u0004 הבן אחרי שקנאה \u0003ואחר כך מת אביו\u0004 — \u0003הרי היא כשדה מקנה\u0004 שהקדישה הקונה, אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה ור' שמעון אומרים:\u0004 אף זו \u0003הרי היא כשדה אחוזה, שנאמר\u0004 בדין שדה מקנה: \"ו \u0003אם משדה מקנתו אשר לא משדה אחזתו\u0004 יקדיש\" (ויקרא כז, כב), וההדגשה \"אשר לא משדה אחוזתו\" באה לומר: דין זה הוא ב\u0003שדה שאינה ראויה להיות\u0004 לגביו \u0003שדה אחוזה, יצתה זו ש\u0004בשעה שהקדישה \u0003היא ראויה להיות\u0004 לגביו \u0003שדה אחוזה,\u0004 כשימות אביו.","\u0003שדה מקנה\u0004 שהקדישה הקונה — \u0003אינה יוצאה לכהנים ביובל,\u0004 מפני שלא נמכרה לו אלא עד היובל, שאז חוזרות השדות לבעליהן, ו\u0003אין אדם מקדיש דבר שאינו שלו. הכהנים והלוים מקדישין\u0004 את שדה אחוזתם \u0003לעולם, וגואלין לעולם, בין לפני היובל בין לאחר היובל.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מנין ללוקח שדה מאביו והקדישה ואחר כך מת אביו, מנין שתהא לפניו כשדה אחוזה\u0004 לכל דבר? \u0003תלמוד לומר: \"ואם משדה מקנתו אשר לא משדה אחזתו\u0004 יקדיש\" (ויקרא כז, כב) — \u0003שדה שאינה ראויה להיות שדה אחוזה, יצתה זו,\u0004 שקנאה מאביו, \u0003ש\u0004היא \u0003ראויה להיות שדה אחוזה\u0004 בשעה שהקדישה, שאינה נחשבת כשדה מקנה, אלו \u0003דברי ר' יהודה ור' שמעון.\u0004","ואילו \u0003ר' מאיר אומר,\u0004 כך יש לדרוש כתוב זה: מנין ללוקח שדה מאביו, ומת אביו ואחר כך הקדישה, מנין שתהא לפניו כשדה אחוזה? תלמוד לומר: \"ואם משדה מקנתו אשר לא משדה אחזתו יקדיש\" — \u0003שדה שאינה שדה אחוזה\u0004 בשעה שהקדיש, \u0003יצאת זו שהיא\u0004 כעת \u0003שדה אחוזה.\u0004 אבל שדה שהיא רק ראויה להיות שדה אחוזה בשעה שהקדישה — דינה כשדה מקנה.","ומציעים: \u0003לימא בהא קא מיפלגי\u0004 \u0005[האם נאמר שבזה הם חלוקים],\u0006 ש\u0003ר' מאיר,\u0004 הנצרך ללמוד מכאן ששדה שקנאה מאביו אינה נחשבת לגביו שדה מקנה, גם לאחר מותו, הוא \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003קנין פירות\u0004 שיש לבן בשדה בחיי אביו עד שיגיע היובל — \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 כלומר, כאילו קנה כבר את גוף השדה, ובמות אביו לא נתחדש דבר בקניינו, ולפיכך צריכה התורה ללמדנו שעם מות אביו משתנה מעמדה לגביו משדה מקנה לשדה אחוזה.","ואילו \u0003ר' יהודה ור' שמעון סברי\u0004 \u0005[סבורים]:\u0006 \u0003קנין פירות\u0004 שיש לבן בחיי אביו \u0003לאו כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 ועם מות אביו, שהיא נקנית לו לגמרי — בוודאי משתנה מעמדה לגביו משדה מקנה לשדה אחוזה, ולא הוצרך לכך הכתוב, אלא למעט מקרה שהקדיש את השדה קודם שהיתה בידו כשדה אחוזה?","\u0003אמר רב נחמן בר יצחק: בעלמא\u0004 \u0005[ב\u0006דרך \u0005כלל]\u0006 \u0003ל\u0004דעת \u0003ר' שמעון ור' יהודה קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 ואף הם זקוקים ללמוד מן הכתוב שאם מת אביו ואחר כך הקדישה, שאין לה דין שדה מקנה."],["\u0003והכא\u0004 \u0005[וכאן]\u0006 שאמרו כי גם במקרה שהקדישה ואחר כך מת אביו הדין כן — \u0003קרא אשכח ודרשי\u0004 \u0005[מקרא מצאו ודרשו],\u0006 שאם רק כדי ללמד כדברי ר' מאיר, שאם הקדישה לאחר מות אביו אינה נחשבת שדה מקנה — \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]:\u0006 \"ו \u0003אם משדה מקנתו אשר לא שדה אחזתו\u0004 יקדיש\", \u0003אי נמי\u0004 \u0005[או גם כן]:\u0006 \u0003\"אשר לא שדה אחוזה\u0004 יקדיש\", \u0003מאי\u0004 \u0005[מהו]\u0006 שנאמר \"אשר לא \u0003משדה אחזתו\u0004 יקדיש\" — לומר: \u0003שדה שאינה ראויה להיות\u0004 כלל \u0003שדה אחוזה\u0004 נידונת כשדה מקנה, \u0003יצתה זו,\u0004 שקנאה מאביו והקדישה קודם שמת אביו, \u0003שראויה להיות שדה אחוזה.\u0004","שנינו במשנה: \u0003הכהנים והלוים מקדישין\u0004 \u0003לעולם\u0004 וגואלין לעולם, בין לפני היובל בין לאחר היובל\u0003.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שהדין ש\u0003גואלין\u0004 לעולם \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 להיאמר — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004שדה אחוזה של \u0003ישראל, דלא פרקי\u0004 \u0005[שאינם פודים\u0006 אותה\u0005]\u0006 \u0003אלא עד\u0004 שנת ה\u0003יובל,\u0004 ואם לא נגאלה — הריהי יוצאה לכהנים, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003כהנים ולוים\u0004 שהקדישו שדה אחוזתם \u0003גואלין לעולם. אלא\u0004 הדין שהכהנים והלויים \u0003מקדישין\u0004 לעולם, \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע נאמר דווקא ב\u0003כהנים ולוים? אפילו ישראל נמי\u0004 \u0005[גם כן]\u0006 מקדישין לעולם!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהכוונה היא שהכהנים והלויים מקדישים אפילו \u0003בשנת היובל עצמה,\u0004 שלא כישראל — \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003שמואל\u0004 ש\u0003אמר: בשנת היובל עצמה לא קדשה\u0004 \u0005[אינה מתקדשת]\u0006 שדה אחוזה על ידי ישראל, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003כהנים ולוים מקדישין לעולם,\u0004 ואפילו בשנת היובל. \u0003אלא\u0004 \u0003ל\u0004שיטת \u0003רב, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003כהנים ולוים? אפילו ישראל נמי\u0004 \u0005[גם כן]\u0006 מקדישים בשנת היובל!","ומשיבים: \u0003ולטעמיך\u0004 \u0005[ולשיטתך],\u0006 יש להקשות גם כן: מה שנאמר במשנה שהכהנים והלויים מקדישים \u0003בין לפני היובל בין לאחר היובל, למה לי\u0004 לאומרו? והרי כבר נאמר \"לעולם\"! \u0003אלא איידי דתנא רישא\u0004 \u0005[מתוך ששנה בתחילת\u0006 הפרק\u0005]\u0006 בשדה אחוזה של ישראל: \"אין מקדישין \u0003לפני היובל\u0004 פחות משתי שנים \u0003ו\u0004לא גואלין \u0003אחר היובל\u0004 פחות משנה אחת\" — \u0003תנא סיפא נמי\u0004 \u0005[שנה בסוף\u0006 הפרק \u0005גם כן],\u0006 שכהנים ולויים מקדישים \u0003\"בין לאחר היובל בין לפני היובל\",\u0004 למרות שאין בכך חידוש, \u0003ו\u0004לפי דרך זו יש לפרש גם כי \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בתחילה]\u0006 לגבי ישראל: \u0003\"אין מקדישין ולא גואלין\"\u0004 — תנא נמי סיפא \u0005[שנה גם כן בסוף\u0006 הפרק\u0005],\u0006 לגבי כהנים ולויים: \u0003\"מקדישין וגואלין\",\u0004 למרות שדין \"מקדישין\" (בשנת היובל) שייך בין בכהנים ולויים ובין בישראל. \u0003המקדיש את שדהו\u0004","","","(שדה אחוזתו) \u0003בשעה שאין היובל\u0004 נוהג, ואין פודים את השדה לפי חשבון קצוב של חמישים שקל לבית זרע כור שעורים, אלא בשוויה, כשהגזבר מכריז על מכירת השדה \u0003אומר לו\u0004 למקדיש: \u0003פתח אתה ראשון\u0004 בכמה אתה מציע לפדותה. והוא לטובת ההקדש, משום \u0003שהבעלים נותנין\u0004 (מוסיפים) \u0003חומש\u0004 על פדיונם, \u0003וכל אדם אין נותנין חומש.\u0004","\u0003מעשה באחד שהקדיש שדהו מפני רעתה,\u0004 כלומר, שהיתה גורמת לו הפסדים, \u0003אמרו לו: פתח אתה ראשון, אמר: הרי היא שלי באיסר\u0004 (מטבע קטנה, בשווי שמונה פרוטות). \u0003אמר ר' יוסי: לא אמר זה\u0004 \"הרי היא שלי \u0003באיסר\", אלא:\u0004 \"הרי היא שלי \u0003בביצה\", שהקדש נפדה בכסף\u0004 או \u0003ב\u0004דבר ה\u0003שוה כסף. אמר לו\u0004 הגזבר: \u0003\"הגעתיך\",\u0004 נתתי לך את השדה לפי הצעתך, \u0003נמצא\u0004 אותו אחד \u0003מפסיד איסר\u0004 שנתן להקדש, \u0003ושדהו\u0004 מונחת \u0003לפניו.\u0004","שנינו במשנה: המקדיש שדהו בשעה שאין היובל נוהג, אומר לו: פתח אתה ראשון. ושואלים: מדוע רק \u0003אומרין\u0004 לו? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 ש\u0003כופין\u0004 אותו שיפתח ראשון! ומשיבים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"אומרין\" נמי\u0004 \u0005[גם כן]\u0006 ששנינו במשנה — ש\u0003כופין\u0004 אותו לפתוח ראשון. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כך: \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003אומרין\u0004 לו, \u0003אי צאית\u0004 — \u0003צאית\u0004 \u0005[אם מציית\u0006 — \u0005מציית],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 מציית — \u0003כופין\u0004 אותו.","ובטעם הדבר שאומרים לבעלים לפתוח תחילה, שנינו במשנה: \u0003שהבעלים נותנין חומש,\u0004 וכל אדם אין נותנין חומש. ושואלים: \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 משום \u0003שהבעלים נותנין חומש? תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו מטעם אחר, \u0003דאיידי דחביבה עליה טפי ופריק לה\u0004 \u0005[שמתוך ש\u0006השדה \u0005חביבה עליו, מוסיף ופודה אותה]\u0006 במחיר גבוה! \u0003ועוד,\u0004 כפי ששנינו במקום אחר: מן התורה, \u0003מצות גאולה באדון\u0004 (בבעלים) תחילה!","ומשיבים: חדא ועוד קאמר \u0005[\u0006טעם \u0005אחד ועוד הוא אומר],\u0006 \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]:\u0006 \u0003דאיידי דחביבה עליה טפי ופריק לה\u0004 \u0005[שמתוך שחביבה עליו מוסיף\u0006 על שוויה \u0005ופודה אותה];\u0006 \u0003ועוד, מצות גאולה באדון היא; ועוד, שהבעלים נותנין חומש,\u0004 וכל אדם אין נותנין חומש.","שנינו במשנה: \u0003מעשה באחד שהקדיש שדהו\u0004 מפני רעתה, אמרו לו: פתח אתה ראשון, אמר: הרי היא שלי באיסר. אמר ר' יוסי: לא אמר זה \"באיסר\", אלא \"בביצה\", שהקדש נפדה בכסף ובשווה כסף. ושואלים: \u0003לימא בהא קמיפלגי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005בזה הם חלוקים],\u0006 ש\u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 דבר ה\u0003שוה כסף\u0004 נידון \u0003ככסף,\u0004 ופודים בו, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003שוה כסף אינו ככסף?\u0004 \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 ש\u0003שוה כסף\u0004 דינו \u0003ככסף!\u0004 ומשיבים: אכן, \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003שוה כסף ככסף, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003פודין בדבר שאין בחומשו שוה פרוטה קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003איסר,\u0004 שהוא מטבע השווה שמונה פרוטות, \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003בחומשו שוה פרוטה\u0004 — \u0003פרקינן\u0004 \u0005[פודים אנו]\u0006 בו, \u0003ור' יוסי\u0004 סבור: \u0003כביצה נמי פרקינן\u0004 \u0005[גם כן פודים אנו],\u0006 אף על פי שאין בחומשה פרוטה.","","אחר הבאת המחלוקת שנינו במשנה: \u0003אמר לו\u0004 הגזבר למי שהציע איסר בפדיון השדה: \u0003\"הגעתיך\", נמצא מפסיד איסר ושדהו לפניו.\u0004 ומעירים: \u0003סתמא כרבנן\u0004 \u0005[סתמה\u0006 של משנה זו \u0005כ\u0006דברי \u0005חכמים],\u0006 שפודים באיסר שיש בחומשו שווה פרוטה.","\u0003אמר אחד: הרי היא שלי בעשר סלעים, ואחד אומר בעשרים, ואחד אומר בשלשים, ואחד אומר בארבעים, ואחד אומר בחמשים,\u0004 אם \u0003חזר בו של חמשים\u0004 ואינו רוצה לפדותה — \u0003ממשכנין מנכסיו עד עשר\u0004 כלומר, גובים מנכסיו עשרה סלעים, ויפדה אותה מי שהציע ארבעים, וכך נמצא שאין ההקדש מפסיד במה שחזר בו. \u0003חזר בו של ארבעים\u0004 — \u0003ממשכנין מנכסיו עד עשר,\u0004 ופונים למציע שלושים. \u0003חזר בו של שלשים\u0004 — \u0003ממשכנין מנכסיו עד עשר, חזר בו של עשרים\u0004 — \u0003ממשכנין מנכסיו עד עשר. חזר בו של עשר\u0004 — \u0003מוכרין אותו\u0004 (את השדה) \u0003בשוויו, ונפרעין משל עשר את המותר\u0004 להשלים לעשרה סלעים.","","\u0003הבעלים אומרים בעשרים, וכל אדם אומרים בעשרים\u0004 — \u0003הבעלים קודמין\u0004 לאחר, \u0003מפני שהם מוסיפין חומש.\u0004 אמר הבעלים בעשרים, ו\u0003אמר אחד: הרי היא שלי בעשרים ואחת\u0004 סלעים,"],["— הרי \u0003הבעלים נותנין\u0004 על כרחם \u0003עשרים ושש,\u0004 ונוטלים את השדה; עשרים שהציעו הם, ועוד חמש עבור החומש (כלומר, רבע, חמישית מן הסכום הכולל), ועוד סלע, כדי שלא יפסיד ההקדש מה שהציע השני עבור השדה. אמר הבעלים בעשרים, ואמר אחר \u0003בעשרים ושתים\u0004 — \u0003הבעלים נותנין עשרים ושבע,\u0004 עשרים שהציעו הם, ועוד חומש, ועוד שני סלעים שהוסיף האחר על ערך השדה.","וכיוצא בזה, אמר אחר: \u0003בעשרים ושלש\u0004 — \u0003הבעלים נותנין עשרים ושמונה, בעשרים וארבע\u0004 — \u0003הבעלים נותנין עשרים ותשע, בעשרים וחמש\u0004 — \u0003הבעלים נותנין שלשים,\u0004 אבל לא יותר, \u0003שאין\u0004 הבעלים \u0003מוסיפין חומש\u0004 אלא על מה שהציעו הם, אבל אינם מוסיפים חומש \u0003על עלויו של זה,\u0004 כלומר, על מה שהוסיף האחר.","אם לאחר שהציעו הבעלים עשרים \u0003אמר אחד: הרי\u0004 היא \u0003שלי בעשרים ושש\u0004 סלעים, \u0003אם רצו הבעלים ליתן שלשים ואחד\u0004 סלעים \u0003ודינר\u0004 — \u0003הבעלים קודמין, ואם לאו,\u0004 שלא רצו — \u0003אומר לו\u0004 הגזבר לאותו אדם: \u0003הגעתיך,\u0004 נתתי לך את השדה לפי הצעתך, שהרי הציע עבור השדה יותר ממה שיכול ההקדש לקבל מן הבעלים, עשרים וחמישה סלעים.","שנינו במשנה כי במקרה שאחד הציע עבור שדה חמישים, ואחד ארבעים, ואחד שלושים, ואחד עשרים, ואחד עשר, אם חזר בו של חמישים מהצעתו — ממשכנים (נוטלים מנכסיו) עד עשר סלעים, שיכול היה ההקדש להרויח אם לא היה חוזר בו. \u0003אמר רב חסדא: לא שנו\u0004 במשנתנו שאם חזר בו של חמישים — ממשכנין מנכסיו עד עשר, \u0003אלא\u0004 במקרה \u0003שבן ארבעים\u0004 \u0003עומד במקומו\u0004 ופודה אותה מן ההקדש, ונמצא שההקדש הפסיד עשרה שקלים בלבד.","\u0003אבל\u0004 אם \u0003אין בן ארבעים עומד במקומו,\u0004 אלא גם הוא חוזר בו — \u0003משלשין\u0004 (מחלקים) \u0003ביניהן\u0004 את ההפרש שבין ארבעים לבין שלושים, שהוא הסכום שבו נפדה ההקדש.","ומקשים על כך, והרי מיד אחר כך \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003חזר בו של ארבעים\u0004 — \u0003ממשכנין\u0004 מנכסיו \u0003עד עשר,\u0004 ולפי דברי רב חסדא, \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003ליתן בר חמשין בהדיה\u0004 \u0005[שיתן בן החמישים יחד אתו],\u0006 וכך יתן בן הארבעים רק חמש! ומשיבים: מדובר פה במקרה חדש, \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003בן חמשים,\u0004 כלומר, שלא היה מי שהציע סכום זה.","ומקשים עוד, הרי שנינו במשנתנו: \u0003חזר בו בן שלשים\u0004 — \u0003ממשכנין מנכסיו עד עשר,\u0004 ולשיטת רב חסדא, \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003וליתן דבן ארבעים בהדיה\u0004 \u0005[ושיתן בן הארבעים יחד אתו]!\u0006 ומשיבים: מדובר \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003בן ארבעים.\u0004 וחוזרים ושואלים, ומה ששנינו: \u0003חזר בו בן עשרים\u0004 — \u0003ממשכנין מנכסיו עד עשר, אמאי\u0004 \u0005[מדוע]?\u0006 \u0003ליתן דבן שלשים בהדיה\u0004 \u0005[שיתן בן השלושים יחד אתו]!\u0006 ומשיבים: מדובר \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003בן שלשים.\u0004","ואומרים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך אמור את סופה]\u0006 של הלכה זו: \u0003חזר בו של עשר\u0004 — \u0003מוכרין אותה בשויה ונפרעין משל עשר את המותר,\u0004 ומדוע רק ממנו? \u0003ליתב דבן עשרים בהדיה\u0004 \u0005[שיתן בן העשרים יחד אתו]!\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003הכא נמי דליכא\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005שאין]\u0006 \u0003בן עשרים\u0004 עמו, \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מה ששנינו: \u0003\"נפרעין משל עשרה\"\u0004 אינו מתאים, אלא \u0003\"נפרעין ממנו\" מיבעי ליה\u0004 \u0005[צריך היה\u0006 לומר\u0005],\u0006 שהרי אין כלל מציע אחר!","\u0003אלא אמר רב חסדא, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן,\u0004 שמשתתפים יחד בהפסד שנגרם להקדש, מדובר כשחזרו בהם מהצעותיהם \u0003בבת אחת, כאן,\u0004 ששנינו במשנתנו שאין משתתפים יחד בהפסד ההקדש, מדובר כשחזרו בהם \u0003בזה אחר זה.\u0004 ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003חזרו כולן כאחד\u0004 — \u0003משלשין\u0004 (מחלקים) \u0003ביניהם\u0004 את הפסד ההקדש. ויש להקשות על כך, \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003ממשכנין מנכסיו עד עשר\u0004, ולא הוזכר שמשלשים ביניהם! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]\u0006 \u0003כ\u0004דברי \u0003רב חסדא\u0004, שיש הבדל בין חזרה בבת אחת לבין חזרה בזה אחר זה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומעירים: משנתנו וברייתא זו, \u0003איכא דרמי להו מירמא\u0004 \u0005[יש מי שהשליך אותן זו על זו],\u0006 הראה סתירה ביניהן, שכך \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003חזר בו של עשר\u0004 — \u0003מוכרין אותה בשויה ונפרעין משל עשר את המותר. והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003משלשין ביניהם!\u0004 ועל כך \u0003אמר רב חסדא, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן,\u0004 בברייתא, מדובר כשחזרו \u0003בבת אחת, כאן,\u0004 במשנה, מדובר כשחזרו \u0003בזה אחר זה.\u0004","שנינו במשנה: \u0003הבעלים אומרים בעשרים וכל אדם\u0004 אומרים \u0003בעשרים\u0004 — הבעלים קודמים, מפני שהם מוסיפים חומש. ומעירים: \u0003למימרא\u0004 \u0005[יש לומר,\u0006 ללמוד מכאן\u0005]\u0006 שחישוב התוספת של ה\u0003חומש\u0004 שנותנים הבעלים \u0003עדיף\u0004 על פני הצעה גבוהה יותר של הקרן עצמה. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו לענין פדיון מעשר שני: \u0003בעל הבית אומר בסלע, ואחד אומר בסלע ואיסר\u0004 — \u0003של סלע ואיסר קודם, מפני שמוסיף על הקרן!\u0004","ומשיבים: \u0003הכא דחומשא רווחא\u0004 \u0005[כאן ש\u0006תוספת \u0005החומש רווח]\u0006 של \u0003הקדש הוא\u0004 — חישוב התוספת של \u0003חומש עדיף, התם דחומשא רווחא\u0004 \u0005[שם שהחומש\u0006 הוא \u0005רווח]\u0006 של \u0003בעל הבית,\u0004 כלומר, שאין להקדש רווח בדבר, שהרי מעשר שני (או פדיונו) של הבעלים הוא, אלא שצריך להעלותו לירושלים ולהשתמש בו שם — \u0003קרנא תיפרוק שפיר\u0004 \u0005[הקרן תיפדה יפה,\u0006 כראוי\u0005]\u0006 על ידי מי שהציע יותר, ו\u0003חומשא לא איכפת לן\u0004 \u0005[\u0006ו\u0005החומש לא אכפת לנו\u0006 ממנו\u0005].\u0006","שנינו במשנה שאם לאחר שאמרו הבעלים: הרי היא שלי בעשרים, \u0003אמר אחד: הרי הוא שלי בעשרים וחמש\u0004 — הבעלים \u0003נותנין שלשים.\u0004 ושואלים, \u0003ולימרו\u0004 \u0005[ושיאמרו]\u0006 \u0003הבעלים:\u0004 הרי העשרים שהצענו בתוספת החומש עולים לעשרים וחמש, ואם כן \u0003אתא גברא בחריקין\u0004 \u0005[בא אדם\u0006 אחר \u0005במקומנו],\u0006 שמציע סכום זהה, ומדוע לכפות אותנו לשלם יותר? ומשיבים: מדובר \u0003דאמור\u0004 \u0005[שאמרו]\u0006 ה\u0003בעלים\u0004 מתחילה שהם נותנים עשרים סלעים ו\u0003דינר\u0004 נוסף (רבע סלע), ונמצא שהחומש על הצעה זו יתר על עשרים וחמישה סלעים שהציע האחר.","ושואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 במפורש \u0003דינר\u0004 זה! ומשיבים: \u0003לא דק\u0004 \u0005[דקדק]\u0006 התנא להזכיר סכום קטן כדינר. ושואלים: \u0003ולא? והא קתני\u0004 \u0005[והרי שנינו]\u0006 בהמשך המשנה, שאם אמר אחד: הריהי שלי בעשרים ושש, \u0003אם רצו הבעלים ליתן שלשים ואחד\u0004 סלעים \u0003ודינר\u0004 — \u0003בעלים קודמין! אלא אמר רבא:\u0004 מדובר \u0003דאמור\u0004 \u0005[שאמרו]\u0006 \u0003בעלים\u0004 עשרים סלעים ו\u0003פרוטה, ו\u0004במקרה כזה אומרים אנו ש\u0003לא דק\u0004 \u0005[דקדק]\u0006 התנא להזכיר סכום פעוט כזה.","שנינו במשנה \u0003ש\u0004אף שהבעלים צריכים לתת להקדש מה שהעלה השני בערכה של השדה, \u0003אין\u0004 הם \u0003מוסיפין חומש על עלויו\u0004 של זה, אלא רק על המחיר שהציעו הם עצמם. אמר רב חסדא: לא שנו אלא שלא נישום ה\u0003הקדש בשלשה\u0004 אנשים, \u0003אבל נישום\u0004 ה\u0003הקדש בשלשה,\u0004 והשומה שווה להצעתו של האחר — \u0003מוסיפין\u0004 הבעלים חומש על עילויו של זה. ומעירים: \u0003תניא\u0004","\u0003נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003בית שמאי אומרים: מוסיפין\u0004 חומש על עלויו של זה, \u0003ובית הלל אומרים: אין מוסיפין.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 \u0005מדובר]\u0006 בברייתא זו? \u0003אי\u0004 \u0005[אם]\u0006 במקרה ש\u0003לא נישום\u0004 השדה על ידי שלושה, \u0003מאי טעמא\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי,\u0004 שאמרו שצריכים הבעלים להוסיף חומש? \u0003אלא\u0004 צריך לומר שמדובר כש\u0003נישום,\u0004 ועלתה השומה כהצעתו של זה, ולפיכך צריכים להוסיף חומש על כך.","ואולם \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי \u0003רב חסדא דאמר\u0004 \u0005[שאומר]\u0006 \u0003כ\u0004שיטת \u0003בית שמאי?\u0004 והרי מקובלנו שהלכה כבית הלל! ודוחים: \u0003לעולם\u0004 תפרש שמדובר כש\u0003לא נישום, ובית שמאי מחמירין,\u0004 שאפילו כך צריך להוסיף חומש על עילוי של השני. ואילו לבית הלל יש להוסיף חומש רק כשנישום בסכום זה, וכדברי רב חסדא.","\u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לעולם\u0004 מדובר כש\u0003נישום\u0004 בשלושה כהצעת האחר, \u0003ואיפוך\u0004 \u0005[והפוך]\u0006 את השיטות, ומעתה \u0003בית שמאי אומרים:\u0004 אפילו כך \u0003אין\u0004 הבעלים \u0003מוסיף\u0004 חומש על עילויו של זה. ומקשים: לדבריך, \u0003וליתניה\u0004 \u0005[ושישנה]\u0006 הלכה זו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קולי בית שמאי וחומרי\u0004 \u0003בית הלל,\u0004 רשימת הדברים שבהם בית שמאי מקילים ובית הלל מחמירים (בפרק הרביעי והחמישי של מסכת עדויות)! \u0003אלא לעולם\u0004 תאמר ש\u0003לא נישום, ובית שמאי מחמירין,\u0004 וכפי שהסברנו לפני כן.","\u0003אמר אחד: הרי היא שלי בעשרים ושש,\u0004 אם רצו הבעלים ליתן שלושים ואחד סלע ודינר — הבעלים קודמים. ומסבירים: \u0003רצו\u0004 להוסיף — \u0003אין\u0004 \u0005[כן]\u0006 יפדו, אם \u0003לא רצו\u0004 \u0003לא\u0004 כופים אותם, מפני שהבעלים","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אתא גברא בחריקין\u0004 \u0005[בא אדם במקומנו],\u0006 שנותן מחיר גבוה יותר להקדש, שהרי אנו היינו נותנים יחד עם החומש עשרים וחמישה סלעים, וזה מציע עשרים וששה. ומכל מקום, אם רוצים הם לפדות — עליהם ליתן קרן וחומש שהציעו מתחילה (עשרים וחמש) ועוד ששה סלעים שהוסיף האחר בהצעתו, שהם שלושים ואחד סלעים.","ושואלים: \u0003ו\u0004לפי זה, \u0003דינר\u0004 נוסף שהזכירה המשנה \u0003מאי עבידתיה\u0004 \u0005[מה מעשהו\u0006 פה\u0005]?\u0006 \u0003אמר רב ששת, הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר]\u0006 התנא: \u0003אם רצו בעלים מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003ליתן חשבון המגיע לאחד ושלשים\u0004 סלעים \u0003ודינר;\u0004"],["\u0003היכי דמי\u0004 \u0005[\u0006ו\u0005כיצד בדיוק מדובר]?\u0006 \u0003דאמור\u0004 \u0005[שאמרו]\u0006 הבעלים מתחילה \u0003בעשרים ואחד\u0004 סלעים, שהחומש עליהם הוא חמישה סלעים ודינר, יותר מעשרים וששה שהציע האחר — \u0003הבעלים קודמין,\u0004 וכשמוסיפים אותו חומש על עשרים וששה הסלעים שהציע האחר, מגיעים לשלושים ואחד סלעים ודינר. \u0003ואם לאו\u0004, ולמרות צירוף החומש עדיין נמוכה הצעת הבעלים מהצעת האחר — \u0003אומר לו\u0004 הגיזבר לאחר: \u0003הגעתיך.\u0004","\u0003מחרים אדם מצאנו ומבקרו, ומעבדיו ומשפחותיו הכנענים, ומשדה אחוזתו, ואם החרים את כולם,\u0004 את כל מה שיש לו ממין מסויים — \u0003אינם מוחרמים, דברי ר' אליעזר. אמר ר' אלעזר בן עזריה,\u0004 מכאן יש להסיק בקל וחומר: \u0003מה אם ל\u0004צורך \u0003גבוה אין אדם רשאי להחרים כל נכסיו\u0004 — \u0003על אחת כמה וכמה שיהא אדם חס על נכסיו\u0004, ולא יתן הכל לאחרים.","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלו]\u0006 ששנינו במשנה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בברייתא\u0005],\u0006 נאמר בתורה: \"אך כל חרם אשר יחרים איש לה' מכל אשר לו מאדם ובהמה ומשדה אחוזתו\" (ויקרא כז, כח), ויש לדרוש: \u0003\"מכל אשר לו\"\u0004 — \u0003ולא\u0004 יחרים את \u0003כל אשר לו,\u0004 והוסיפה התורה וכתבה: \u0003\"מאדם\"\u0004 ללמדנו — \u0003ולא\u0004 יחרים \u0003כל אדם\u0004 (עבד) שיש לו, \"מ אדם ו\u0003בהמה\"\u0004 — \u0003ולא כל בהמה\u0004 שלו, \"ו \u0003משדה אחזה\"\u0004 — \u0003ולא כל שדה אחוזה\u0004 שלו.","\u0003יכול לא יחרים\u0004 לכתחילה את כולם, \u0003ו\u0004אולם \u0003אם החרים יהו מוחרמין? תלמוד לומר: \"אך\"\u0004 לעכב, אלו \u0003דברי ר' אליעזר. אמר ר' אלעזר בן עזריה: מה אם לגבוה אין אדם רשאי להחרים כל נכסיו, על אחת כמה וכמה שיהא אדם חס על נכסיו!\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 ללמוד מן הכתובים על כל אחד ואחד מן הפרטים, \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק: \u0003\"מכל אשר לו\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כל דאית ליה לא לחרים\u0004 \u0005[כל\u0006 מה \u0005שיש לו\u0006 ציוותה התורה \u0005שלא יחרים],\u0006 \u0003אבל מין אחד ליחרמיה כוליה\u0004 \u0005[\u0006מותר \u0005שיחרימנו כולו],\u0006 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"מאדם\"\u0004 — \u0003ולא כל אדם.\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 \u0003\"מאדם\",\u0004 הייתי אומר כי דווקא על כך אסרה תורה, משום \u0003דלא סגיא ליה בלא עבודה\u0004 \u0005[שלא אפשר לו בלא עבד],\u0006 \u0003אבל שדה\u0004 — \u0003סגיא ליה בדיסתורן\u0004 \u0005[אפשר לו\u0006 שיתפרנס \u0005באריסות\u0006 בשדה אחרים\u0005].\u0006 \u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואם היה משמיע לנו\u0006 רק \u0005את שני אלה],\u0006 הייתי אומר: טעם הדבר, \u0003משום דהכא חיותא והכא חיותא\u0004 \u0005[שכאן\u0006 זה \u0005חיותו,\u0006 פרנסתו, \u0005וכאן\u0006 זה \u0005חיותו],\u0006 \u0003אבל מטלטלין\u0004 — \u0003ליחרמינהו כולהו\u0004 \u0005[\u0006אפשר \u0005שיחרים\u0006 את \u0005כולם],\u0006 על כן \u0003צריכי\u0004 \u0005[צריכים]\u0006 כל המקראות להיאמר.","ושואלים: \"ו \u0003בהמה\" למה לי?\u0004 ומשיבים: \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003יכול יחרים אדם בנו ובתו, עבדו ושפחתו העבריים, ושדה מקנתו? תלמוד לומר: \"בהמה\", מה בהמה\u0004 היא דבר ש\u0003יש לו רשות למוכרה, אף כל שיש לו רשות למוכרה\u0004 יכול להחרימו, אבל מה שאין לו רשות למוכרו — אינו יכול להחרימו.","ויש לשאול: \u0003והלא בתו קטנה יש לו רשות למוכרה\u0004 לאמה עבריה, \u0003יכול יחרימנה? תלמוד לומר: \"בהמה\", מה בהמה יש לו רשות למוכרה לעולם, אף כל שיש לו רשות למוכרה לעולם,\u0004 אבל את בתו אינו יכול למכור לכשתגדל, אלא רק בקטנותה.","שנינו במשנה, \u0003אמר ר' אלעזר בן עזריה:\u0004 מה \u0003אם לגבוה אין אדם רשאי\u0004 להחרים כל נכסיו, על אחת כמה וכמה שיהא אדם חס על נכסיו, שלא לתיתם לאנשים אחרים. ושואלים: \u0003היינו תנא קמא\u0004 \u0005[\u0006והרי \u0005זו היא\u0006 שיטת \u0005התנא הראשון],\u0006 ר' אליעזר, שאסר על האדם להחרים את כל נכסיו!","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 בענין מה שאמר \u0003ר' אילא,\u0004 ש\u0003אמר ר' אילא:\u0004 בזמן שהיתה הסנהדרין \u0003באושא התקינו\u0004 תקנה, ש\u0003המבזבז\u0004 (המפזר מנכסיו) לצדקה, \u0003אל יבזבז יותר מחומש\u0004 (חמישית) מנכסיו. ר' אליעזר, שלא השתמש בביטוי \"שיהא אדם חס על נכסיו\", סבור כי די שישייר לעצמו מעט מכל דבר, ואילו ר' אלעזר בן עזריה אוסר לבזבז יותר מחומש.","ומביאים: \u0003מעשה באחד שבקש לבזבז יותר מחומש, ולא הניחו לו חבריו, ומנו\u0004 \u0005[ומי הוא]\u0006 איש זה? \u0003ר' ישבב. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהאיש שרצה לעשות זאת היה \u0003ר' ישבב, ולא הניחו לו חביריו, ומנו\u0004 \u0005[ומיהו]\u0006 חביריו אלה? \u0003ר' עקיבא.\u0004","\u0003המחרים בנו ובתו, ועבדו ושפחתו העברים, ושדה מקנתו\u0004 — \u0003אין מוחרמין, שאין אדם מחרים דבר שאינו שלו,\u0004 ואלה אינם שלו. \u0003הכהנים והלוים אין מחרימין, דברי ר' יהודה. ר' שמעון אומר: הכהנים אין מחרימין\u0004 — מפני \u0003שהחרמין שלהן,\u0004 כלומר, ממתנות הכהונה הם, שנאמר: \"כל חרם בישראל לך יהיה\" (במדבר יח, יד). \u0003והלוים מחרימין\u0004 — \u0003ש\u0004הרי \u0003אין החרמין שלהן.\u0004","\u0003אמר רבי: נראין דברי ר' יהודה בקרקעות,\u0004 שאין יכולים הלויים להחרימם, \u0003שנאמר:\u0004 \"ושדה מגרש עריהם לא ימכר \u0003כי אחזת עולם היא להם\"\u0004 (ויקרא כה, לד), ואינם יכולים להפקיע מעצמם את הקרקע. \u0003ו\u0004נראים \u0003דברי ר' שמעון במטלטלין,\u0004 שיכולים הלויים להחרימם, מפני \u0003שאין החרמין שלהן,\u0004 כלומר, ממתנות הלויים, אלא הם ממתנות הכהונה.","ושואלים: \u0003ור' יהודה\u0004 מה סברתו? \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 שה\u0003כהנים אין מחרימין\u0004 — מפני \u0003שחרמין שלהן,\u0004 כלומר, ממתנות הכהונה, \u0003אלא לוים\u0004 מדוע לא יחרימו? \u0003בשלמא מקרקעי לא מחרמי\u0004 \u0005[נניח שקרקעות לא מחרימים]\u0006 — מפני \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי אחזת עולם היא להם\", אלא מטלטלי ליחרמי\u0004 \u0005[מיטלטלין\u0006 ש\u0005יחרימו]\u0006 הלויים! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"אך כל חרם אשר יחרים איש לה' \u0003מכל אשר לו\u0004 מאדם ובהמה \u0003ומשדה אחזתו...\u0004 קדש קדשים הוא לה'\" (ויקרא כז, כח), הרי ש\u0003מקיש\u0004 הכתוב \u0003מטלטלין לקרקעות\u0004 לענין חרמים, ולפיכך אין הלויים יכולים להחרים אף מיטלטלים.","ושואלים: \u0003ור' שמעון\u0004 מה סברתו? \u0003בשלמא\u0004 \u0005[נניח]\u0006 שה\u0003כהנים\u0004 אינם יכולים להחרים אפילו מיטלטלים — \u0003כדאמרן\u0004 \u0005[כמו שאמרנו],\u0006 מפני שהחרמים שלהם, \u0003אלא לוים, בשלמא\u0004 \u0005[נניח]\u0006 \u0003מטלטלים לחרים\u0004 \u0005[יחרימו],\u0006 מפני שר' שמעון \u0003לא מקיש\u0004 מיטלטלין לקרקעות, \u0003אלא מקרקעי אמאי\u0004 \u0005[קרקעות\u0006 שלהם \u0005מדוע]\u0006 יכולים הלויים להחרים? \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"אחזת עולם היא להם\"!\u0004 ומשיבים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"מחרימין\" נמי דקאמר\u0004 \u0005[גם כן שאומר\u0006 ר' שמעון\u0005]?\u0006 הכוונה היא שמחרימים \u0003מטלטלי\u0004 \u0005[מיטלטלין]\u0006 בלבד.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנינו בסוף\u0006 המשנה\u0005]:\u0006 \u0003אמר רבי: נראין דברי ר' יהודה במקרקעי\u0004 \u0005[בקרקעות]\u0006 \u0003ודברי ר' שמעון במטלטלי\u0004 \u0005[במיטלטלין],\u0006 יש להסיק \u0003מכלל\u0004 זה ש\u0003ר' שמעון מקרקעי נמי קאמר\u0004 \u0005[קרקעות גם כן אומר],\u0006 שיכולים הלויים להחרים! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 לכך כוונת המשנה, \u0003אמר רבי: נראין דברי ר' יהודה לר' שמעון בקרקעות\u0004 של הלויים, \u0003שאף ר' שמעון לא נחלק\u0004 עליו, שיכולים הלויים להחרימם, \u0003אלא במטלטלין, אבל בקרקעות מודה ליה\u0004 \u0005[לו]\u0006 ר' שמעון, שאין יכולים הלויים להחרים מאחוזתם.","\u0003אמר ר' חייא בר אבין:\u0004 מי ש\u0003החרים מטלטלין\u0004 — \u0003נותנן לכל כהן שירצה, שנאמר: \"כל חרם בישראל\u0004"],["\u0003לך יהיה\"\u0004 (במדבר יח, יד), כלומר, יהיה לאהרן, והוא הדין לכל אחד מבניו הכהנים. אבל אם \u0003החרים\u0004 אדם את \u0003שדותיו\u0004 — \u0003נותנן לכהן שבאותו משמר\u0004 כהונה העובד במקדש באותה שעה, \u0003שנאמר: \"כשדה החרם לכהן תהיה אחזתו\"\u0004 (ויקרא כז, כא), \u0003וגמר\u0004 \u0005[ולמד]\u0006 בגזירה שווה \u0003\"לכהן\" \"לכהן\"\u0004 \u0003מגזל הגר,\u0004 שהגוזל את הגר ונשבע שלא גזלו, ומת הגר ואין לו יורשים — נותן את הגזילה לכהני המשמר המשרת באותה שעה במקדש.","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם מנין לנו],\u0006 שניתן לכהן שבאותו משמר? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 נאמר: \"ואם אין לאיש גואל להשיב האשם (כלומר, הגזילה) אליו, האשם המושב לה' לכהן\" (במדבר ה, ח). וממה שנאמר \u0003\"לה' לכהן\"\u0004 יש ללמוד כי \u0003קנאו השם\u0004 את הגזל המושב, \u0003ונתנו לכהן שבאותו משמר.\u0004","ויש לשאול: \u0003אתה אומר\u0004 שניתן \u0003לכהן שבאותו משמר? או אינו אלא לכל כהן שירצה\u0004 הגזלן לתת לו! \u0003כשהוא אומר\u0004 בהמשך לכך: \u0003\"מלבד איל הכפרים אשר יכפר בו עליו\"\u0004 — \u0003הרי בכהן שבאותו משמר\u0004 המקריב את הקרבן \u0003הכתוב מדבר.\u0004","ועוד אמר ר' חייא בר אבין בעניינים אלו: \u0003שדה היוצאה לכהנים ביובל,\u0004 שהוקדשה על ידי בעליה ולא נגאלה — \u0003נותנה למשמר שפגע בו יובל\u0004 בזמן שהיה משרת במקדש. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 השאלה: \u0003פגע בו\u0004 היובל \u0003בשבת,\u0004 שהוא זמן חילופי המשמרות, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005],\u0006 כלומר, לאיזה משמר יינתן? \u0003אמר רב חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003חולפנא:\u0004 \u0003נותנה למשמר היוצא,\u0004 שמסיים את משמרתו בשבת זו.","\u0003אמר רב נחמן בר יצחק: תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 המסייעת לו, שכן שנינו: \u0003נמצאת אתה אומר, אחד יובל,\u0004 שמשמט את השדות המכורות מיד הקונים, \u0003ואחד שביעית,\u0004 שמשמטת את החובות — \u0003משמטין כאחד,\u0004 באותה שעה, \u0003אלא שיובל\u0004 משמט \u0003בתחילתו\u0004 \u0003והשמטה\u0004 משמטת \u0003בסופה.\u0004 כלומר, בליל ראש השנה שבו מסתיימת השמיטה (השנה הארבעים ותשע) ונכנס היובל — נשמטים החובות, והשדות שנמכרו נשמטות מיד הקונים. והוא הדין לשדות שהוקדשו על ידי בעליהן, שיוצאות לכהנים. ונמצא שאם היתה זו שבת — זוכה בהן המשמר היוצא, מפני שהמשמרות מתחלפים למחרת, ביום השבת עצמו. ושואלים על לשון הברייתא: מדוע נאמר שם \"אלא\", שמשמעו שהם משמטים כאחד למרות שהיובל משמט בתחילתו?","\u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003משום הכי הואי\u0004 \u0005[משום כך הוא]\u0006 כלומר, טעם הדבר שהם משמטים כאחד הוא מפני שהיובל משמט בתחילתו, והשמיטה משמטת בסופה! ומשיבים, \u0003אימא\u0004 \u0005[אמור]\u0006 בברייתא: \u0003מפני שהיובל\u0004 משמט בתחילתו והשמיטה בסופה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שביעית\u0004 משמטת חובות \u0003בסופה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מקץ שבע שנים תעשה שמטה\"\u0004 (דברים טו, א), ו\"מקץ\" משמעו — בסוף, \u0003אלא יובל\u0004 האם הוא משמט \u0003בתחילתו?\u0004 הלוא \u0003ביום הכיפורים הוא\u0004 משמט, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ביום הכפרים תעבירו שופר בכל ארצכם...\u0004 ושבתם איש אל אחוזתו\" (ויקרא כה, ט—י)! ומשיבים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה היא,\u0004 ש\u0003אמר:\u0004 כבר \u0003מראש השנה הוא דחייל\u0004 \u0005[שחל]\u0006 ה\u0003יובל.\u0004 ושבים לתחילת דבריו של ר' חייא בר אבין, שהמחרים מיטלטליו נותנם לכל כהן שירצה, בניגוד למחרים קרקע, שהוא ניתן לכהני המשמר שבאותה שעה.","מסופר, \u0003שמעה\u0004 \u0003חזקיה בר בילוטו, ואזל אמר קמיה\u0004 \u0005[והלך\u0006 ו\u0005אמר לפני]\u0006 \u0003ר' אבהו: וליקיש מטלטלי\u0004 \u0005[ושיקיש מיטלטלים]\u0006 \u0003לקרקעות,\u0004 כפי שמשמע מן הכתוב \"אשר יחרים איש לה' מכל אשר לו, מאדם ובהמה ומשדה אחוזתו\" (שם כז, כח), ואף המיטלטלים ינתנו לכהן שבאותו המשמר!","אמר לו ר' אבהו: \u0003לאו תנאי\u0004 \u0005[האם לא\u0006 מחלוקת \u0005תנאים]\u0006 \u0003היא? דאיכא דמקיש, ואיכא דלא מקיש\u0004 \u0005[שיש שמקיש, ויש שלא מקיש],\u0006 שכך הסברנו (בעמוד הקודם) את מחלוקת ר' יהודה ור' שמעון האם לויים מחרימים מיטלטלים שלהם או לא, ור' חייא בר אבין סבור \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]:\u0006 \u0003לא מקשינן\u0004 \u0005[אין אנו מקישים].\u0006","\u0003חרמי כהנים,\u0004 שהחרים אדם מנכסיו לטובת הכהנים, \u0003אין להם פדיון,\u0004 כפי שיש לכל דבר שהוקדש (הוחרם) לבדק הבית, \u0003אלא נותנים\u0004 אותם \u0003לכהנים כתרומה,\u0004 שהיא רכושם לכל דבר. \u0003ר' יהודה בן בתירא אומר: סתם חרמים,\u0004 שהחרים איש מנכסיו ולא פירש למי החרימם, ניתנים \u0003לבדק הבית, שנאמר:\u0004 \u0003\"כל חרם קדש קדשים הוא לה' \"\u0004(ויקרא כז, כח).","\u0003וחכמים אומרים: סתם חרמים\u0004 ניתנים \u0003לכהנים, שנאמר\u0004 לגבי המקדיש שדה ולא גאלה: \u0003\"כשדה החרם לכהן תהיה אחזתו\"\u0004 (שם כז, כא), הרי שסתם שדה חרם — של הכהן היא. \u0003אם כן, למה נאמר \"כל חרם קדש קדשים הוא לה' \"?\u0004 ללמד \u0003ש\u0004חרם \u0003חל\u0004 גם \u0003על קדשי קדשים ועל קדשים קלים,\u0004 שאם הקדיש אדם בהמה לקרבן, ולאחר מכן החרימה — החרם חל, ואולם לא על גופה, אלא על השייכות הכספית שיש לו בה.","וכך אמרו חכמים: \u0003מחרים אדם את קדשיו בין קדשי קדשים בין קדשים קלים,\u0004 כיצד? \u0003אם\u0004 היה הקרבן שהחרים \u0003נדר,\u0004 וכגון שאמר \"הרי עלי עולה\", והפריש קרבן, הואיל והוא חייב באחריותו אם מת או אבד — נחשב הקרבן כשלו, ולכן \u0003נותן דמיהן\u0004 (שוויים) לכהנים.","\u0003ואם\u0004 היה הקרבן שהחרים \u0003נדבה,\u0004 שהוא פטור מאחריותה אם אבדה, וכגון שאמר על בהמה \"הרי זו לעולה\" — \u0003נותן את טובתן,\u0004 את הזכות הכספית שיש לו בהם, וכגון אם אמר: \u0003\"שור זה עולה\"\u0004 — \u0003אומדין כמה\u0004 כסף \u0003אדם רוצה ליתן בשור זה\u0004 כדי \u0003להעלותו עולה, אף על פי שאינו רשאי\u0004 (חייב) להקריבה.","\u0003הבכור, בין\u0004 שהיה \u0003תם בין\u0004 שהיה \u0003בעל מום\u0004 — \u0003מחרימין אותו\u0004 בעליו. \u0003וכיצד פודים אותו\u0004 כלומר, כמה צריך ליתן לכהן בשביל החרם? \u0003אומדין כמה אדם\u0004 מישראל \u0003רוצה ליתן ב\u0004עבור \u0003בכור זה\u0004 כדי \u0003ליתנו ל\u0004כהן שהוא \u0003בן בתו או ל\u0004כהן שהוא \u0003בן אחותו.\u0004"],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חרמי כהנים אין להן פדיון ונותנין\u0004 אותם עצמם \u0003לכהן.\u0004 ו\u0003חרמים\u0004 אלו, \u0003כל זמן שהן\u0004 נמצאים עדיין \u0003בבית בעלים\u0004 — \u0003הרי הן כהקדש\u0004 \u0003לכל דבריהן, שנאמר: \"כל חרם קדש קדשים הוא לה' \"\u0004(ויקרא כז, כח), ואחר ש\u0003נתנן לכהן\u0004 — \u0003הרי הן לכל דבריהן כחולין, שנאמר: \"כל חרם בישראל לך יהיה\"\u0004 (במדבר יח, יד), כלומר, כשאר רכוש הכהן, שהוא חולין.","שנינו במשנה, \u0003ר' יהודה בן בתירא אומר: סתם חרמים לבדק הבית,\u0004 שנאמר: \"כל חרם קדש קדשים הוא לה' \" (ויקרא כז, כח). וחכמים אומרים: סתם חרמים לכהנים, שנאמר: \"כשדה החרם לכהן תהיה אחוזתו\" (שם כא), אם כן, למה נאמר \"כל חרם קדש קדשים הוא לה' \" — ללמד שהוא חל על קדשי קדשים ועל קדשים קלים. ושואלים: \u0003בשלמא רבנן\u0004 \u0005[נניח,\u0006 מובנת שיטת \u0005חכמים],\u0006 \u0003כדקא מפרשי טעמייהו וטעמא\u0004 \u0005[כמו שהם מפרשים\u0006 במשנה \u0005את טעמם,\u0006 המקור לדבריהם, \u0005ואת טעמו,\u0006 הפסוק שהביא לשיטתו\u0005]\u0006 \u0003ר' יהודה בן בתירא, אלא ר' יהודה בן בתירא האי\u0004 \u0005[\u0006מקרא \u0005זה]\u0006 \u0003\"כשדה החרם\u0004 לכהן תהיה אחוזתו\", \u0003מאי עביד ליה\u0004 \u0005[מה עושה הוא לו]?\u0006 מה הוא למד ממנו?","ומשיבים: \u0003מיבעיא ליה לכדתניא\u0004 \u0005[נצרכה לו לכמו ששנויה\u0006 ברייתא\u0005]\u0006 על פסוק זה, העוסק במקדיש שדה אחוזתו ולא נגאלה, שהיא יוצאת לכהנים ביובל. מה שהוסיף שם הכתוב: \u0003\"כשדה החרם לכהן תהיה אחזתו\" מה תלמוד לומר?\u0004 מה הוא בא ללמד? \u0003מנין לכהן שהקדיש\u0004 את \u0003שדה חרמו,\u0004 שדה שהחרים ישראל וניתנה לו, והוא מחזיק בה עדיין, והגיעה שנת היובל, מנין \u0003שלא יאמר: הואיל ו\u0004שדה שהקדישוה ולא גאלה הבעלים עד היובל \u0003יוצאה לכהנים,\u0004 \u0003והרי\u0004 שדה זו שהקדשתי \u0003היא תחת ידי,\u0004 אם כן \u0003תהא שלי\u0004 שהרי כהן אני? \u0003ו\u0004לכאורה \u0003דין\u0004 (קל וחומר) \u0003הוא:\u0004 אם \u0003ב\u0004שדה \u0003של אחרים\u0004 \u0003אני זוכה,\u0004 כלומר, בשדה אחוזה של ישראל שהקדישה ולא גאלה, \u0003בשל עצמי לא כל שכן\u0004 שאזכה? \u0003תלמוד לומר: \"כשדה החרם לכהן תהיה אחזתו\",\u0004 ללמד שאינו יכול לומר כן.","","שכך יש לשאול על כתוב זה: \u0003וכי מה למדנו\u0004 על שדה האחוזה \u0003משדה חרם מעתה?\u0004 והרי דין שדה החרם אינו מפורש בתורה במקום אחר! אלא, \u0003הרי זה,\u0004 שדה החרם, \u0003בא ללמד ונמצא למד: מקיש שדה חרמו\u0004 של כהן \u0003לשדה אחוזה של ישראל,\u0004","\u0003מה שדה אחוזה של ישראל\u0004 שפדה אותה כהן מיד ההקדש, \u0003יוצאה מתחת ידו\u0004 בהגיע היובל, \u0003ומתחלקת ל\u0004כל ה\u0003כהנים\u0004 של המשמר שפגע בו היובל, כפי ששנינו לעיל (כה,א) — \u0003אף שדה חרמו\u0004 שהקדישה והיא עדיין בידו, \u0003יוצאה מתחת ידו ומתחלקת לאחיו הכהנים,\u0004 במשמר שפגע בו יובל.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 חכמים\u0005]\u0006 מנין הם למדים דין זה? ומשיבים: \u0003מ\u0004ריבוי הכתוב, שדי היה לכתוב \u0003\"חרם\"\u0004 כדי ללמד את שיטתם שסתם חרמים לכהן, ונכתב בתורה \u0003\"החרם\".\u0004 ומן הצד השני, \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יהודה בן בתירא\u0005],\u0006 הדיוק של \u0003\"חרם\" \"החרם\" לא משמע ליה\u0004 \u0005[לא נשמע לו]\u0006 כמקור ללימוד נוסף, ולכן למד ממנו רק ששדה חרמו של כהן שהוקדשה תצא מידו. ושואלים: \u0003ור' יהודה בן בתירא,\u0004 הדין שחרם \u0003חל על קדשי קדשים ועל קדשים קלים,\u0004 שחכמים למדוהו מהכתוב \"כל חרם קדש קדשים הוא לה' \", \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003סבר ליה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' ישמעאל,\u0004 שלומד דין זה ממקום אחר, כמבואר במשנה הבאה.","","\u0003אמר רב: הלכה כר' יהודה בן בתירא,\u0004 שסתם חרמים מיועדים לבדק הבית ולא לכהנים. ושואלים: \u0003ורב שביק רבנן ועביד\u0004 \u0005[מניח את\u0006 שיטת \u0005חכמים ועושה]\u0006 \u0003כר' יהודה בן בתירא\u0004 שהוא יחיד? ומשיבים: \u0003ברייתא איפכא תניא\u0004 \u0005[\u0006ב\u0005ברייתא שנויה\u0006 המחלוקת \u0005להיפך],\u0006 שזו היא דעת חכמים. ושואלים: \u0003שביק מתניתין ועביד כברייתא\u0004 \u0005[\u0006וכי רב \u0005מניח את משנתנו,\u0006 שהיא עיקר, \u0005ועושה כברייתא]?\u0006 ומשיבים: \u0003רב מתניתין נמי איפכא תני\u0004 \u0005[את משנתנו גם כן\u0006 הוא \u0005שונה להיפך],\u0006 כמו הברייתא.","ושואלים: \u0003מאי חזית דאפכת מתניתין מקמי ברייתא\u0004 \u0005[מה ראית שהפכת את משנתנו מפני הברייתא]?\u0006 \u0003נפיך ברייתא מקמי מתניתין\u0004 \u0005[נהפוך את\u0006 דעות החולקים ב\u0005ברייתא מפני משנתנו]!\u0006 ומשיבים: \u0003רב גמריה גמיר\u0004 \u0005[למד במסורת שלו]\u0006 מרבו, שיש להפוך את השיטות במשנה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 וכי הלכה \u0003כר' יהודה בן בתירא\u0004 צריך היה לומר? הלא הלכה \u0003כרבנן מיבעי ליה\u0004 \u0005[כחכמים היה צריך\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003למאי דאפכיתו ותניתו\u0004 \u0005[ל\u0006פי \u0005מה שאתם הופכים ושונים\u0006 במשנה\u0005],\u0006 \u0003הלכה כר' יהודה בן בתירא.\u0004","מסופר, \u0003ההוא גברא דאחרמינהו לנכסיה\u0004 \u0005[אדם אחד שהחרים את נכסיו]\u0006 \u0003בפומבדיתא, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יהודה\u0004 לשאול מה לעשות, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003שקול ארבעה זוזי ואחיל עלייהו ושדינהו בנהרא\u0004 \u0005[קח ארבעה זוזים,\u0006 דינרים, \u0005וחלל עליהם\u0006 את הנכסים \u0005והשלך\u0006 את המטבעות \u0005בנהר],\u0006 \u0003ולישתרו לך\u0004 \u0005[ויהיו\u0006 הנכסים \u0005מותרים לך],\u0006 שהרי נפדו. ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שרב יהודה \u0005סבור]\u0006 ש\u0003סתם חרמים לבדק הבית\u0004 הם, ולכן ניתן לפדותם, שהרי חרמי כהנים אין להם פדיון, כפי ששנינו במשנתנו.","ומקשים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 סבור רב יהודה שהורה לחלל את ההקדש על פחות משוויו — \u0003כ\u0004דעת \u0003שמואל,\u0004 ש\u0003אמר:\u0004 \u0003הקדש\u0004 אפילו היה \u0003שוה מנה\u0004 (מאה זוזים), \u0003שחיללו על שוה פרוטה\u0004 — \u0003מחולל;\u0004 ואולם, \u0003אימר דאמר\u0004 \u0005[אמור שאומר]\u0006 \u0003שמואל\u0004 שהדין כן במקרה \u0003ש\u0004כבר \u0003חיללו,\u0004 כלומר, בדיעבד, אבל להורות שיחלל \u0003לכתחלה מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שלכתחילה צריך לחלל בשוויו, אמורים \u0003בזמן שבית המקדש קיים, דאיכא פסידא\u0004 \u0005[שיש הפסד]\u0006 להקדש כשמחללים בפחות משוויו, \u0003אבל בזמן הזה,\u0004 שאין המקדש קיים, ואין מה לעשות בהקדש — \u0003אפילו לכתחלה\u0004 יחלל בפחות משוויו. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו\u0004 על \u0003פרוטה נמי\u0004 \u0005[גם כן]\u0006 אפשר לחלל, ומדוע הצריך רב יהודה ארבעה זוזים? ומשיבים: כדי שיהיה \u0003פרסומי מלתא\u0004 \u0005[פרסום\u0006 ל\u0005דבר],\u0006 וידע הציבור שרק משום שהתחלל ההקדש מותר להשתמש בו.","\u0003אמר עולא: אי הואי התם\u0004 \u0005[אם הייתי שם]\u0006 כשבאה השאלה, \u0003הוה יהיבנא כולהו\u0004 \u0005[הייתי נותן את\u0006 הנכסים \u0005כולם]\u0006 \u0003לכהנים.\u0004 ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 \u0003עולא: סתם חרמים לכהנים\u0004 הם, ולא למקדש.","על מה שעולה מסוגיה זו, שדין חרמים נוהג בזמן הזה, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003אין עבד עברי נוהג,\u0004 אינו נמכר, \u0003אלא בזמן שהיובל נוהג, שנאמר:\u0004 \"וכי ימוך אחיך עמך ונמכר לך... \u0003עד שנת היובל יעבד עמך\"\u0004 (ויקרא כה, לט—מ),","\u0003ואין שדה (החרם) [אחוזה] נוהגת אלא בזמן שהיובל נוהג, שנאמר:\u0004 \"והיה ממכרו ביד הקונה אותו... \u0003ויצא ביובל ושב לאחזתו\"\u0004 (ויקרא שם כח). \u0003אין בתי ערי חומה נוהגין אלא בזמן שהיובל נוהג, שנאמר:\u0004 \"וקם הבית אשר בעיר אשר לו חומה לצמיתות לקונה אותו לדורותיו \u0003לא יצא ביובל\"\u0004 (שם ל). \u0003ר' שמעון בן יוחי אומר: אין שדה חרמין נוהגין אלא בזמן שהיובל נוהג, שנאמר: \"והיה השדה בצאתו ביובל קדש לה' כשדה החרם\u0004 לכהן תהיה אחוזתו\" (שם כז, כא), ומכאן ששדה החרם עצמו נוהג ביובל. \u0003ר' שמעון בן אלעזר אומר: אין\u0004 דין \u0003גר תושב נוהג אלא בזמן שהיובל נוהג,\u0004","","\u0003אמר רב ביבי: מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אתיא\u0004 \u0005[נלמד]\u0006 דינו בגזירה שווה \u0003\"טוב\" \"טוב\", כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בעבד עברי שאינו נוהג אלא בזמן היובל: \u0003\"כי טוב לו עמך\"\u0004 (דברים טו, טז), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בדין גר תושב: \u0003\"בטוב לו לא תוננו\"\u0004 (שם כג, יז). הרי מבואר בברייתא זו שדין שדה החרם אינו נוהג בזמן הזה, שלא כפי שעולה מן הדיון בסוגיה זו, שהחרם חל!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שנאמר בברייתא עוסק \u0003במקרקעי\u0004 \u0005[בקרקעות],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שהחרם חל הוא \u0003במטלטלי\u0004 \u0005[במיטלטלים].\u0006 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003מעשה\u0004 שאירע ב\u0003פומבדיתא במקרקעי נמי הוה\u0004 \u0005[בקרקעות גם כן היה],\u0006 והצריכם רב יהודה פדייה! ומשיבים: \u0003מקרקעי\u0004 \u0005[קרקעות]\u0006 של \u0003חוצה לארץ כמטלטלי\u0004 \u0005[כמיטלטלים]\u0006 של \u0003ארץ ישראל דמי\u0004 \u0005[נחשבים].\u0006 \u0003ר' ישמעאל אומר: כתוב אחד אומר\u0004 \"כל הבכור אשר יולד בבקרך ובצאנך הזכר \u0003תקדיש\u0004 לה' \" (שם טו, יט), \u0003וכתוב אחד אומר\u0004 \"אך בכור אשר יבכר לה' בבהמה \u0003לא יקדיש\u0004 איש אותו\" (ויקרא כז, כו), \u0003אי אפשר לומר: \"תקדיש\"\u0004 — \u0003שהרי כבר נאמר: \"לא יקדיש\", אי אפשר לומר: \"לא יקדיש\"\u0004 — \u0003שהרי כבר נאמר: \"תקדיש\",\u0004 \u0003הא\u0004 \u0003כיצד\u0004 יקוימו שני הכתובים? \u0003מקדישו אתה\u0004 את הבכור \u0003הקדש עלוי,\u0004 כלומר, הקדש של שוויו, שצריך לתת להקדש לפי השווי הכספי שיש לו בבכור, כמה יכול לקבל על מנת שיתן אותו לכהן מסויים (כפי ששנינו במשנה בסוף העמוד הקודם), \u0003ואי\u0004 (ואין) \u0003אתה מקדישו הקדש מזבח,\u0004 שיהא שם של זבח אחר חל עליו.","","","ואומרים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלמדו דין זה במשנה הקודמת מן הפסוק \"כל חרם קדש קדשים הוא לה' \", ללמד שהחרם חל גם על קדשי קדשים ועל קדשים קלים (ובכללם בכור), הם סבורים שהכתוב \u0003\"אל תקדיש\" מיבעי ליה\u0004 \u0005[נצרך הוא]\u0006 \u0003ל\u0004למדנו שיש איסור \u0003לאו\u0004 \u0005[לא\u0006 תעשה\u0005]\u0006 מהתורה להקדיש בכור לשם קרבן אחר. והכתוב \u0003\"תקדיש\" מיבעי ליה לכדתניא\u0004 \u0005[נצרך הוא לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003מנין ל\u0004מי ש\u0003נולד בכור בעדרו\u0004 \u0003שמצוה להקדישו\u0004 ולומר \"הרי זה קדוש\"? \u0003שנאמר: \"הזכר תקדיש\". ו\u0004אילו \u0003ר' ישמעאל\u0004 שאינו אומר כן, הוא סבור: \u0003אי לא מקדיש ליה\u0004 \u0005[אם לא מקדיש אותו\u0006 בפיו\u0005]\u0006 האם \u0003לא קדוש\u0004 הוא? והרי \u0003קדושתו מרחם הוה\u0004 \u0005[היתה]!\u0006 \u0003וכיון דכי לא מקדיש ליה\u0004 \u0005[ש\u0006גם \u0005כאשר אינו מקדיש אותו\u0006 בפיו\u0005]\u0006 הוא \u0003קדוש\u0004 מאליו, אם כן \u0003לא צריך לאקדושיה\u0004","",""],["\u0003המוכר את שדהו בשעת היובל\u0004 כלומר, כשהיובל נוהג, \u0003אינו מותר לגאול\u0004 את השדה מן הקונה בתוך \u0003פחות משתי שנים\u0004 מזמן שמכרה, \u0003שנאמר: \"במספר שני תבואת ימכר לך\"\u0004 (ויקרא כה, טו), ומיעוט שנים הוא שתים.","\u0003היתה\u0004 אחת מהשנים האלו \u0003שנת שדפון\u0004 או \u0003ירקון,\u0004 ולקתה התבואה, \u0003או שנת שביעית,\u0004 שאין הקונה נהנה מתבואת השדה — \u0003אינו עולה מן המנין,\u0004 וצריך להמתין שנה אחרת כנגדה, שהרי נאמר \"שני תבואות\". ואולם אם \u0003נרה\u0004 (חרש את השדה בלי לזרוע) \u0003או הובירה\u0004 (עשאה שדה בור, שלא עבד בה כלל) — שנה כזו \u0003עולה לו מן המנין,\u0004 משום שהיתה ראויה לתבואה. \u0003ר' אליעזר אומר:\u0004 אם \u0003מכרה לו לפני ראש השנה והיא מליאה פירות,\u0004 ובא המוכר לגואלה לאחר שנתיים — \u0003הרי\u0004 קונה \u0003זה אוכל ממנה שלש תבואות בשתי שנים,\u0004 ואינו צריך להחזירה מלאה פירות.","שנינו במשנה: \u0003המוכר שדהו בשעת היובל\u0004 אינו מותר לגאול פחות משתי שנים. ומדייקים: \u0003\"אינו גואל\" לא קתני\u0004 \u0005[אינו שונה],\u0006 \u0003אלא: \"אינו מותר לגאול\", אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 התנא של משנתנו כי \u0003איסורא נמי איכא\u0004 \u0005[\u0006\u0005איסור גם כן יש]\u0006 בדבר, \u0003דאפילו קרקושי זוזי\u0004 \u0005[שאפילו לקשקש במטבעות]\u0006 כדי לגרום לקונה שימכור לו את השדה, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור.\u0004","\u0003ולא מיבעיא\u0004 \u0005[ולא נצרכה]\u0006 הלכה זו להיאמר רק ביחס למוכר דקאי \u0005[ש\u0006הוא \u0005עומד]\u0006 ומצווה על כך \u0003ב\u0004מצות \u0003עשה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במספר שני תבואת ימכר לך\"\u0004 (ויקרא כה, טו), ולא פחות, \u0003אלא אפילו לוקח נמי\u0004 \u0005[גם כן]\u0006 \u0003קאי\u0004 \u0005[עומד]\u0006 \u0003ב\u0004מצות \u0003עשה, דבעינן\u0004 \u0005[שצריכים אנו]\u0006 לקיים \"במספר \u0003שנים\u0004 אחר היובל \u0003תקנה\u0004 מאת עמיתך\" (שם), ומיעוט \"שנים\" הוא שתי שנים, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 אם מחזירה לפני כן.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003המוכר שדהו בשנת היובל עצמה, רב אמר: מכורה ויוצאה\u0004 למוכר בחינם, \u0003ושמואל אמר: אינה מכורה כל עיקר.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003שמואל? קל וחומר\u0004 הוא, \u0003ומה\u0004 שדה שהיתה \u0003מכורה כבר, יוצאה\u0004 מיד הקונה בשנת היובל, \u0003שאינה מכורה אינו דין שלא תימכר?\u0004","ושואלים: \u0003ו\u0004כי \u0003ל\u0004שיטת \u0003רב לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003קל וחומר כי האי גוונא\u0004 \u0005[כמו זה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול ימכור אדם את בתו\u0004 לאמה \u0003כשהיא\u0004 כבר \u0003נערה? אמרת\u0004 (אומר אתה) \u0003קל וחומר\u0004 שאין לומר כך: ומה בתו שהיתה \u0003מכורה כבר,\u0004 שרשאי למוכרה בקטנותה — \u0003יוצאה עכשיו\u0004 בהגיעה לימי נערותה, נערה \u0003שאינה מכורה\u0004 עדיין, \u0003אינו דין שלא תימכר?\u0004","ומשיבים: אין להשוות, שכן \u0003התם לא הדרא מיזדבנא\u0004 \u0005[שם,\u0006 בהגיעה לימי נערות, \u0005אינה חוזרת ונמכרת\u0006 עוד לעולם\u0005],\u0006 ואילו \u0003הכא הדרא מיזדבנא\u0004 \u0005[כאן,\u0006 שדה אחוזה, \u0005חוזרת ונמכרת]\u0006 לאחר היובל כרגיל, ולכן אין ללמוד מקל וחומר זה.","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב ממה ששנינו בברייתא: נאמר בתורה \"במספר שנים אחר היובל תקנה\" (ויקרא כה, טו), ויש לדורשו כך: \u0003\"אחר היובל שנים תקנה\"\u0004 — \u0003מלמד שמוכרין\u0004 ב\u0003סמוך ל\u0004אחר ה\u0003יובל, מופלג\u0004 (בריחוק זמן) \u0003מן היובל מנין\u0004 שמוכרים? \u0003תלמוד לומר: \"לפי רב השנים\u0004 תרבה מקנתו \u0003ולפי מעוט השנים\u0004 תמעיט מקנתו\" (שם טז), ומכאן שיש אפשרות מכירה גם מופלג מן היובל.","ועוד מוסיפה הברייתא: \u0003ובשנת היובל עצמה לא ימכור, ואם מכר\u0004 — \u0003אינה מכורה.\u0004 שלא כדברי רב! ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003רב:\u0004 כוונת הברייתא לומר שכשמוכרה ביובל \u0003אינה מכורה למספר שני תבואות,\u0004 לעמוד שנתיים לפחות ביד הקונה, \u0003אבל\u0004 על כל פנים, \u0003מכורה היא ויוצאה.\u0004","ושואלים: \u0003ואי איזדבוני מיזבנה\u0004 \u0005[ואם היא נמכרת],\u0006 \u0003תיקום ברשותיה\u0004 \u0005[שתעמוד ברשותו]\u0006 של הקונה \u0003עד בתר\u0004 \u0005[אחר]\u0006 ה\u0003יובל, ובתר\u0004 \u0005[ואחר]\u0006 ה\u0003יובל ניכליה\u0004 \u0005[יאכל אותה]\u0006 \u0003שני תבואות\u0004 \u0003וניהדרה\u0004 \u0005[ויחזיר אותה]\u0006 אחר כך לבעליה! \u0003מי לא תניא\u0004 \u0005[האם לא שנויה\u0006 ברייתא\u0005]\u0006 במקרה דומה: אם \u0003אכלה\u0004 הקונה \u0003שנה אחת לפני היובל\u0004 — \u0003משלימין לו שנה אחרת אחר היובל?\u0004 ומשיבים: אינו דומה, \u0003התם נחית\u0004 \u0005[שם ירד]\u0006 מתחילה לשדה \u0003לאכילה\u0004 של תבואה, ולכך מקיימים בו את הכתוב \"שני תבואות\", ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 שקנה בשנת היובל עצמה, \u0003לא נחית\u0004 \u0005[ירד]\u0006 מתחילה לשדה \u0003לאכילה\u0004 של תבואה, שהרי היא יוצאה מיד לבעליה.","בענין מחלוקת רב ושמואל \u0003אמר רב ענן: שמעית מיניה דמר שמואל תרתי\u0004 \u0005[שמעתי ממנו מן החכם שמואל שתיים,\u0006 שתי הלכות\u0005],\u0006 \u0003חדא הך\u0004 \u0005[אחת זו],\u0006 שהמוכר שדהו בשנת היובל עצמה אינה מכורה כל עיקר, \u0003ואידך\u0004 \u0005[ואחרת],\u0006 ש\u0003המוכר עבדו\u0004 הכנעני \u0003לגוים,\u0004 וגורם לכך שהעבד מופקע מקיום מצוות, \u0003או\u0004 שמכרו לישראל הדר \u0003בחוצה לארץ,\u0004 ובכך גורם להפקיע את העבד ממצות ישיבת ארץ ישראל — \u0003יצא\u0004 העבד \u0003לחירות.\u0004","ושמעתי ממנו כי ב\u0003חדא\u0004 \u0005[\u0006במקרה \u0005אחד]\u0006 \u0003הדרי זביני\u0004 \u0005[חוזרים דמי המיקח],\u0006 \u0003וחדא לא הדרי זביני\u0004 \u0005[ו\u0006במקרה \u0005אחד לא חוזרים דמי המיקח],\u0006 \u0003ולא ידענא הי מיניה\u0004 \u0005[ואין אני יודע באיזה מהם].\u0006","\u0003אמר רב יוסף: ניחזי אנן\u0004 \u0005[נראה אנחנו],\u0006 \u0003מדתניא\u0004 \u0005[ממה ששנויה]\u0006 \u0003בברייתא: המוכר עבדו\u0004 למי שדר \u0003בחוצה לארץ\u0004 — \u0003יצא\u0004 העבד \u0003לחירות, ו\u0004אולם \u0003צריך\u0004 העבד לקבל \u0003גט\u0004 (שטר) \u0003שיחרור מרבו שני,\u0004 זה שקנה אותו, \u0003שמע מינה\u0004 \u0005[למד מכאן],\u0006 כי \u0003מדקרי ליה\u0004 \u0005[ממה שקורא לו]\u0006 \u0003לשני\u0004 \u0003\"רבו\".\u0004 והוא צריך לכתוב את גט השחרור — \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהמכר חל, ולפיכך \u0003לא הדרי זביני\u0004 \u0005[לא חוזרים דמי המיקח],\u0006 \u0003ו\u0004ממילא \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003שמואל הכא\u0004 \u0005[כאן],\u0006 שהמוכר שדהו בשנת היובל עצמה \u0003אינה מכורה,\u0004 כוונתו — \u0003ומעות חוזרין.\u0004"],["ומעירים: \u0003ורב ענן\u0004 לא פשט את ספקו מן הברייתא בענין עבד עברי, משום ש\u0003ברייתא\u0004 זו \u0003לא שמיעא ליה\u0004 \u0005[לא שמע].\u0006 \u0003ו\u0004אילו מדבריו של \u0003שמואל\u0004 עצמו, ששדה שמכרה ביובל אינה מכורה כל עיקר — לא יכול היה לפשוט את הספק, שכן \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 שכוונתו לומר ש\u0003אינה מכורה ומעות חוזרין\u0004 ללוקח? \u0003דלמא\u0004 \u0005[שמא]\u0006 כוונתו היתה ש\u0003אינה מכורה, ומעות\u0004 לשם \u0003מתנה\u0004 ניתנו למוכר, \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 הדין לדעת שמואל ביחס ל\u0003מקדש אחותו. דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003המקדש\u0004 את \u0003אחותו,\u0004 ואין הקידושין חלים — \u0003רב אמר:\u0004 ה\u0003מעות\u0004 שנתן לה לשם הקידושין \u0003חוזרין\u0004 לאח, מפני שהוא יודע שאין הקידושין חלים, ונתנם כדי שתשמרם עבורו, \u0003ושמואל אמר:\u0004 כוונתו לתת לה את ה\u0003מעות\u0004 למתנה. ושבים לברייתא שהבאנו, שהמוכר עבדו בחוצה לארץ — צריך הקונה לשחרר את העבד, ומכל מקום אינו מקבל את מעותיו בחזרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מאי חזית דקנסינן ליה ללוקח\u0004 \u0005[מה ראית שאנו קונסים את הלוקח]?\u0006 \u0003נקנסיה למוכר\u0004 \u0005[נקנוס את המוכר],\u0006 שיחזיר את המעות ללוקח, ויישאר בלא העבד ובלא המעות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי במשל: \u0003לאו עכברא גנב אלא חורא גנב\u0004 \u0005[לא העכבר הוא הגונב אלא החור גונב],\u0006 כלומר, לולי הקונה — לא היה העבד נמכר לחוצה לארץ. אמר לו אביי לרב יוסף, והרי ניתן לומר גם להיפך: \u0003אי לאו עכברא, חורא מנא ליה\u0004 \u0005[אם לא העכבר, החור מנין לו]?\u0006 כלומר, אם לא המוכר שמכר — לא היה העבד יוצא לחוצה לארץ בידי הקונה! אמר לו רב יוסף לאביי: אמנם שניהם אשמים בחטא, ואולם \u0003מסתברא היכא דאיתיה לאיסורא קנסינן\u0004 \u0005[מסתבר שבמקום שנמצא האיסור קונסים],\u0006 כלומר, שקונסים את הלוקח שהעבד נמצא בידיו.","שנינו במשנה: המוכר שדה בשעת היובל, ומותר לגואלה רק לאחר שתי שנים לפחות, אם \u0003היתה שנת שדפון\u0004 או ירקון, או שנת שביעית — אינה עולה מן המנין, אבל אם נרה (חרש אותה בלא לזורעה) או הובירה (השאירה כשדה בור, בלא לחרוש בה) — עולה לו מן המנין. ושואלים: מדוע צריך להזכיר גם נרה וגם הובירה? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם הובירה, למרות שלא עשה בה דבר — \u0003עולה לו\u0004 השנה בחשבון שתי שנות תבואה, אם \u0003נרה,\u0004 שחרש בה, ועשה בה מעשה — \u0003מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שעולה לו?","ומשיבים: \u0003נרה איצטריך ליה\u0004 \u0005[הוצרכה לו],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]\u0006 לבעל השדה: \u0003הב ליה דמיה וליסק\u0004 \u0005[תן לו\u0006 על כל פנים \u0005את דמיו,\u0006 מה שהשביח את השדה בחרישתו, \u0005ויצא\u0006 ממנה\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאינו צריך לתת לו דבר עבור שנה זו.","שנינו במשנה, \u0003ר' אליעזר אומר: מכרה לו\u0004 לפני ראש השנה והיא מליאה פירות — הרי זה אוכל ממנה שלש תבואות בשתי שנים. ומביאים: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: מנין שאם מכרה לו לפני ראש השנה מליאה פירות,\u0004 ובא לגואלה כעבור שנתיים, \u0003שלא יאמר לו\u0004 הגואל לקונה: \u0003\"הנח לפני\u0004 את השדה מליאה פירות \u0003כדרך שהנחתי לפניך\"? תלמוד לומר: \"במספר שני תבואת ימכר לך\"\u0004 (ויקרא כה, טו), כלומר, לפי מספר השנים, ולא לפי מספר התבואות, ולכן \u0003פעמים שאדם אוכל שלש תבואות בשתי שנים.\u0004","המוכר שדה בשעת היובל, כשהוא גואלה מיד הקונה, מחשב כמה קיבל עבור השדה לכל שנה עד היובל, ומשלם לו לפי השנים הנותרות. אם \u0003מכרה לראשון במנה, ומכר\u0004 הקונה ה\u0003ראשון ל\u0004אדם \u0003שני במאתים,\u0004 כאשר בא הגואל לגואלה מיד השני — \u0003אינו מחשב\u0004 את התשלום \u0003אלא\u0004 ביחס למחיר שקבע \u0003עם הראשון, שנאמר:\u0004 \"וחשב את שני ממכרו והשיב את העודף לאיש \u0003אשר מכר לו\"\u0004 (ויקרא כה, כז).","ואולם אם \u0003מכרה לראשון במאתים ומכר הראשון לשני במנה\u0004 — \u0003אינו מחשב\u0004 את התשלום \u0003אלא\u0004 \u0003עם\u0004 הקונה \u0003האחרון,\u0004 לפי מה ששילם עבור השדה, מפני שבמקרה זה אנו דורשים את מה \u0003שנאמר\u0004 שם: \u0003\"וחשב את שני ממכרו והשיב את העדף לאיש אשר מכר לו\",\u0004 שהכוונה היא \u0003לאיש אשר בתוכו\u0004 כעת.","לא ימכור אדם שדה אחוזתו ש\u0003ב\u0004מקום \u0003רחוק ו\u0004כדי ש\u0003יגאל\u0004 בכסף שיקבל שדה שמכר \u0003בקרוב,\u0004 וכן לא ימכור \u0003ב\u0004שדה \u0003רעה\u0004 שלו \u0003ויגאל ביפה, ולא ילוה\u0004 כסף \u0003ויגאל, ולא יגאל לחצאין,\u0004 כלומר חצי השדה כעת, וחציה בפעם אחרת. \u0003ו\u0004אילו \u0003ב\u0004פודה שדהו מן ה\u0003הקדש\u0004 — \u0003מותר\u0004 לפדות \u0003בכולן,\u0004 בכל האופנים שנאסרו בגאולת שדה מיד הקונה. \u0003זה חומר ב\u0004גואל שדה שנמכרה ל\u0003הדיוט מב\u0004 גואל שדה שהוקדשה מה \u0003הקדש.\u0004","בענין ששנינו במשנה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003מכרה לראשון במנה, ומכרה\u0004 הקונה ה\u0003ראשון לשני במאתים, מנין שאינו מחשב\u0004 את התשלום לפי מה ששילם השני לראשון, \u0003אלא\u0004 ביחס למחיר שקבע \u0003עם הראשון? תלמוד לומר:\u0004 \"והשיב את העודף לאיש \u0003אשר מכר לו\"\u0004 (ויקרא כה, כז).","ואם \u0003מכרה לראשון במאתים, ומכר\u0004 הקונה \u0003הראשון לשני במנה, מנין שאין מחשבין אלא עם השני,\u0004 לפי המחיר ששילם עבור השדה? \u0003תלמוד לומר:\u0004 \"והשיב את העודף \u0003לאיש\"\u0004 (שם) — לאיש \u0003אשר בתוכו\u0004 כעת, לפי מה שנתן עבור השדה, אלו \u0003דברי רבי.\u0004","ואילו \u0003ר' דוסתאי בן יהודה אומר,\u0004 כך יש לדרוש מן הכתוב: אם \u0003מכרה לו במנה, והשביחה\u0004 השדה ביד הקונה \u0003ועמדה על מאתים, מנין שאינו מחשב\u0004 את התשלום על השנים הנותרות \u0003אלא ב\u0004יחס ל\u0003מנה\u0004 שקיבל ממנו? \u0003שנאמר: \"והשיב את העדף\"\u0004 (שם) — \u0003העודף ש\u0004נשאר \u0003בידו\u0004 ממה שקיבל עבור השדה.","ואם \u0003מכרה לו במאתים והכסיפה\u0004 (התקלקלה) ביד הקונה, ופחת שוויה \u0003ועמדה על מנה, מנין שאין מחשבין\u0004 את התשלום על השנים הנותרות \u0003אלא ב\u0004יחס ל\u0003מנה? שנאמר: \"והשיב את העדף\"\u0004 — \u0003העודף ש\u0004נשאר \u0003בקרקע\u0004 כעת.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 הבדל הדין \u0005ביניהם],\u0006 בין שתי הדרשות? ומשיבים: במקרה \u0003דאייקר\u0004 \u0005[שהיתה\u0006 השדה \u0005יקרה]\u0006 כשמכרה לראשון, כגון שהיתה שווה מאתיים, \u0003וזל\u0004 \u0005[ונעשתה זולה],\u0006 כלומר, פחת ערכה לכדי מנה בזמן שמכרה הראשון לשני, \u0003ואייקר\u0004 \u0005[ו\u0006שוב \u0005נעשתה\u0006 \u0005יקרה]\u0006 כשבא הבעלים לפדותה מהשני. לפי דרשת רבי, שיש חשיבות למחיר שנתן השני עבורה — יכול הבעלים לפדותה בשיעור הזול שנתן השני עבורה. ואילו לדרשת ר' דוסתאי, שהולכים לפי העודף, הרי בין אם מדובר בעודף ממה שקיבלו הבעלים, ובין אם הולכים אחר העודף לפי מצב השדה כעת — מדובר בשווי היקר יותר.","ולעצם העיקרון המוסכם גם על רבי וגם על ר' דוסתאי, שדורשים את הכתוב להקל על המוכר, שואלים: \u0003וממאי דלקולא\u0004 \u0005[וממה,\u0006 ומנין \u0005ש\u0006בכל מקרה הולכים אחר דרשות הכתוב, \u0005להקל\u0006 על המוכר\u0005]?\u0006 \u0003דלמא לחומרא\u0004 \u0005[שמא להחמיר]!\u0006","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 להחמיר, \u0003דגמר\u0004 \u0005[ש\u0006הרי \u0005הוא לומד]\u0006 שצריך להקל על הגואל בגזירה שווה \u0003\"גאולה\" \"גאולה\" מעבד עברי,\u0004 שנאמר בגאולת שדה אחוזה: \"והשיגה ידו ומצא כדי גאולתו\" (ויקרא כה, כו), ונאמר בעבד עברי הנמכר לגוי: \"אחרי נמכר גאולה תהיה לו\" (שם מח).","ושואלים: \u0003והתם\u0004 \u0005[ושם]\u0006 בעבד עברי, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שמקילים בגאולתו? ומשיבים: \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003נמכר\u0004 העבד העברי \u0003במנה, והשביח\u0004 שוויו \u0003ועמד על מאתים, מנין שאין מחשבין\u0004 את כסף גאולתו לפי השנים הנותרות עד היובל, \u0003אלא ממנה,\u0004 כלומר, לפי המנה שהיה שווה בשעת המכירה? \u0003שנאמר:\u0004 \"אם עוד רבות בשנים לפיהן ישיב גאולתו \u0003מכסף מקנתו\"\u0004 (שם נא) — מן הכסף שנמכר בו.","ואם \u0003נמכר במאתים, ו\u0004כשבא להיגאל \u0003הכסיף\u0004 (פחת שוויו) \u0003ועמד על מנה, מנין שאין מחשבין\u0004 את כסף גאולתו לפי השנים הנותרות, \u0003אלא ממנה,\u0004 כלומר לפי המנה שהוא שווה עתה? \u0003שנאמר: \"כפי שניו\u0004 ישיב את גאולתו\" (שם נב), כלומר, כפי מה שהוא שווה כעת.","\u0003ואין לי אלא עבד עברי הנמכר לגוי ש\u0004הוא \u0003נגאל וידו על העליונה,\u0004 עבד עברי ה\u0003נמכר לישראל מנין\u0004 שנוהגים בו דין זה, כשהוא נפדה קודם שיעברו שש שנים מלאות? \u0003תלמוד לומר: \"שכיר\" \"שכיר\" לגזירה שוה,\u0004 נאמר בנמכר לגוי: \"כימי שכיר יהיה עמו\" (שם נ), ונאמר בנמכר לישראל: \"כי משנה שכר שכיר עבדך\" (דברים טו, יח), ולמדים מכך שגם בעבד עברי הנגאל מישראל צריך להקל בפדייתו.","ובענין זה מסופר, \u0003אמר אביי:\u0004"],["\u0003הריני\u0004 מוכן לענות על כל שאלה שישאלוני, \u0003כ\u0004פי שהיה \u0003בן עזאי בשוקי טבריא,\u0004 שהיה חריף ובקי. \u0003אמר ליה ההוא מרבנן\u0004 \u0005[אמר לו אחד מהחכמים]\u0006 \u0003לאביי:\u0004 המקראות של גאולת עבד, הרי \u0003איכא למידרשינהו לקולא, ואיכא למידרשינהו לחומרא\u0004 \u0005[יש,\u0006 ניתן \u0005לדורשם להקל\u0006 עליו בגאולתו, \u0005ויש לדורשם להחמיר],\u0006 \u0003ממאי דלקולא? אימא לחומרא\u0004 \u0005[מנין שלהקל? אמור שלהחמיר]!\u0006","השיב אביי לשואל: \u0003לא סלקא דעתיך\u0004 \u0005[לא יעלה על דעתך]\u0006 להחמיר, ויש ללמוד זאת \u0003מדאקיל רחמנא גביה\u0004 \u0005[מ\u0006מה \u0005שהקלה התורה לגביו],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 נאמר בתורה בענין עבד עברי: \"והיה כי יאמר אליך לא אצא מעמך... \u0003כי טוב לו עמך\"\u0004 (דברים טו, טז), ומן המלה \"עמך\" מדייקים: \u0003עמך במאכל, עמך במשתה, שלא תהא\u0004 אתה \u0003אוכל פת נקיה והוא אוכל פת קיבר\u0004 (מקמח גס, מעורב בסובין), \u0003אתה שותה יין ישן והוא שותה יין חדש, אתה ישן על גבי מוכין\u0004 (מצע רך) \u0003והוא ישן על גבי קרקע; מיכן אמרו\u0004 חכמים: \u0003הקונה עבד עברי, כקונה אדון לעצמו.\u0004","ענה לו אותו חכם לאביי: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005]\u0006 \u0003נחמיר עליה\u0004 \u0005[עליו]\u0006 \u0003מ\u0004דבריו של \u0003ר' יוסי בר' חנינא!\u0004 ש\u0003אמר ר' יוסי בר' חנינא\u0004 כאשר בא להסביר את רצף הפרשיות שבפרשת בהר: \u0003בא וראה כמה קשה אבקה,\u0004 האיסור הפחות חמור \u0003של שביעית,\u0004","\u0003אדם נושא ונותן בפירות שביעית\u0004 ויובל, שאסור לסחור בהם — \u0003לסוף מוכר את מטלטליו\u0004 מחמת שיורד מנכסיו, \u0003שנאמר\u0004 בסוף פרשת השמיטה והיובל: \"בשנת היובל הזאת תשבו איש אל אחזתו\" (ויקרא כה, יג), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד לאחר מכן: \u0003\"וכי תמכרו ממכר לעמיתך או קנה מיד עמיתך\"\u0004 (שם יד), ו\"מיד עמיתך\" הם מיטלטלים, \u0003דבר הנקנה מיד ליד,\u0004 ללמד שעבירה על איסורי השביעית והיובל מביאה לכך.","\u0003לא הרגיש\u0004 (הזדעזע) מכך ולא תיקן את דרכיו — \u0003לסוף מוכר את שדותיו, שנאמר\u0004 לאחר מכן: \u0003\"וכי ימוך אחיך ומכר מאחזתו\"\u0004 (שם כה);","\u0003לא באת לידו,\u0004 כלומר, אינו שם לב לכך, עד ש\u0003לסוף מוכר את ביתו, שנאמר\u0004 שם: \u0003\"ואיש כי ימכר בית מושב עיר חומה\"\u0004 (שם כט). לפני שממשיכים בציטוט דברי ר' יוסי בר' חנינא שואלים: \u0003מאי שנא התם\u0004 \u0005[מה שונה שם]\u0006 במכירת מיטלטליו, \u0003דקאמר\u0004 \u0005[שהוא אומר]\u0006 \u0003\"לא הרגיש\", ומאי שנא הכא\u0004 \u0005[ומה שונה כאן]\u0006 במכירת שדה ובית, \u0003דקאמר\u0004 \u0005[שהוא אומר]\u0006 \u0003\"לא באת לידו\"?\u0004 ומשיבים: טעם הדבר הוא \u0003כ\u0004פי שאמר \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: כיון שעבר אדם עבירה ושנה בה\u0004 — \u0003הותרה לו.\u0004","ויש לתמוה: \u0003הותרה לו סלקא דעתך\u0004 \u0005[יעלה על דעתך]?\u0006 וכי יש היתר לעבור עבירה? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003נעשית לו כהיתר,\u0004 שאינו חש שהוא עובר עבירה. והוא מה שנאמר כאן, שבתחילה מזדעזע סוחר השביעית מהחטא ועונשו, ואחר כך כבר \"לא באת לידו\", שאינו שם לב שהוא חוטא.","וממשיכים בעיקר הדברים: \u0003לא באת לידו\u0004 — \u0003לסוף שלוה ברבית\u0004 מתוך דוחקו, \u0003שנאמר\u0004 שם: \u0003\"וכי ימוך אחיך\u0004 ומטה ידו עמך\" (שם לה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בכתוב הסמוך: \u0003\"אל תקח מאתו נשך ותרבית\"\u0004 (שם לו).","\u0003לא באת לידו\u0004 דבר זה \u0003עד שמוכר את בתו\u0004 תחילה, \u0003שנאמר: \"וכי ימכר איש\u0004 את \u0003בתו לאמה\u0004 (שמות כא, ז). ומעירים: \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 שמכירת \u0003בתו בהאי ענינא ליתא\u0004 \u0005[באותו ענין,\u0006 פרשה, \u0005איננה\u0006 מוזכרת\u0005],\u0006 הוזכר דבר זה כאן, מפני שמן הסתם אדם מוכר את בתו קודם שלווה בריבית, שכן \u0003ניחא לאיניש דליזבין ברתיה ולא ליזיף בריביתא\u0004 \u0005[נוח לאדם שימכור בתו ולא ילווה בריבית],\u0006 ש\u0003אילו התם\u0004 \u0005[שם]\u0006 במכירת בתו, מחיר פדייתה \u0003מיגרעא ואזלא\u0004 \u0005[פוחת והולך]\u0006 במשך הזמן, \u0003ואילו הכא\u0004 \u0005[כאן]\u0006 הריבית \u0003קא מוספא ואזלא\u0004 \u0005[מתווספת והולכת]\u0006 במשך הזמן.","וממשיך ר' יוסי בר' חנינא: \u0003לא באת לידו\u0004 — \u0003לסוף שמוכר את עצמו, שנאמר\u0004 בהמשך הפרשה: \u0003\"כי ימוך אחיך עמך ונמכר לך\"\u0004 (ויקרא כה, לט); ו\u0003לא\u0004 רק \u0003לך,\u0004 לישראל הוא נמכר, \u0003אלא לגר, שנאמר\u0004 בהמשך: \"ונמכר \u0003לגר\"\u0004 (שם מז), \u0003ולא\u0004 רק \u0003לגר צדק\u0004 הוא נמכר, \u0003אלא לגר תושב\u0004 (גוי שקיבל עליו שבע מצוות בני נח, והותר לו לשבת עמנו), \u0003שנאמר\u0004 במקרא זה: \"ונמכר \u0003לגר תושב\u0004 עמך או לעקר משפחת גר\".","ומה שנאמר \u0003\"משפחת גר\"\u0004 — \u0003זה הגוי,\u0004 בן משפחתו של גר תושב. \u0003כשהוא אומר\u0004 שם: \u0003\"או לעקר משפחת גר\"\u0004 — זה הנמכר ונעשה משרת לעבודה זרה עצמה. הרי שאין אדם נמכר לעבד אלא כתוצאה מחטאיו, ואם כן מדוע לא נדרוש את הכתובים להחמיר עליו בפדיונו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לאותו חכם ששאלו: \u0003הא אהדריה קרא\u0004 \u0005[הרי החזירו הכתוב],\u0006 כלומר, ציווה לפדותו, \u0003ו\u0004כפי ש\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: הואיל והלך ומכר עצמו לעבודה זרה,\u0004 שמא תאמר \u0003אידחה\u0004 (אדחה) \u0003אבן אחר הנופל,\u0004 כלומר, אשאיר אותו שם כעבד, ולא יקום מנפילתו? \u0003תלמוד לומר\u0004 בכתוב הסמוך: \u0003\"גאלת עולם תהיה לו וביובל יצא\"\u0004 (ויקרא כה, לא. וראה שם מח), ואם כן יש מקום להקל עליו בפדיונו. ומקשים על כך, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003גאולה תהיה לו\u0004 לעולם — כדי ש\u0003לא ליטמע\u0004 \u0005[ייטמע]\u0006 \u0003בגוים, ולעולם לענין פדיונו נחמיר,\u0004 מכיוון שהעבדות היא תוצאה של חטאיו!","\u0003אמר רב נחמן בר יצחק, כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אם עוד רבות בשנים\u0004 לפיהן ישיב גאולתו מכסף מקנתו\" (שם נא), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \"ו אם מעט נשאר בשנים עד שנת היובל וחישב לו כפי שניו ישיב את גאולתו\" (שם נב). ויש לשאול:","\u0003וכי יש שנים\u0004 שהן \u0003מרובות ויש שנים\u0004 שהן \u0003מועטות?\u0004 והלא כל השנים שוות הן בגודלן! \u0003אלא\u0004 כך יש לפרש כתובים אלו: \u0003נתרבה כספו\u0004 (עלה ערכו, שוויו) במהלך השנים — מחשבים את פדיונו \u0003מכסף מקנתו,\u0004 כפי שהיה בזמן שנמכר, ואם \u0003נתמעט כספו,\u0004 ירד ערכו במשך השנים — פודים אותו \u0003כפי שניו,\u0004 לפי מה שהוא שווה כעת, ולא לפי זמן מקנתו. ונמצא שהתורה מגלה שיש להקל בכסף פדיונו.","ושואלים, \u0003ואימא\u0004 \u0005[ואמור]\u0006 שכוונת הכתוב היא: \u0003היכא דעבד תרתי ופיישי ארבעי\u0004 \u0005[היכן שעבד\u0006 רק \u0005שתי\u0006 שנים \u0005ונותרו ארבע\u0006 שנים\u0005]\u0006 שהוא חייב לעבוד בהם (\"רבות בשנים\") — \u0003ליתב ליה\u0004 \u0005[שישיב לו\u0006 לאדונו\u0005]\u0006 \u0003ארבע\u0004 חלקי שש \u0003מכסף מקנתו, והיכא דעבד ארבע ופיישי תרתי\u0004 \u0005[והיכן ש\u0006כבר \u0005עבד ארבע\u0006 שנים \u0005ונותרו\u0006 רק \u0005שתי\u0006 שנים\u0005]\u0006 שחייב לעבוד בהם, \u0003ליתב ליה\u0004 \u0005[שישיב לו\u0006 לאדונו\u0005]\u0006 \u0003תרתי\u0004 \u0005[שתים]\u0006 חלקי שש מכספו, כפי שניו! ומשיבים:","\u0003אם כן, נכתוב\u0004 \u0005[שיכתוב]\u0006 \u0003\"אם עוד רבות שנים\", מאי\u0004 \u0005[מהו]\u0006 שנאמר \u0003\"בשנים\"?\u0004 אלא כפי שנאמר: \u0003נתרבה כספו ב\u0004משך ה\u0003שנים\u0004 — החישוב לפדיונו נעשה \u0003מכסף מקנתו,\u0004 ואם \u0003נתמעט כספו ב\u0004משך ה\u0003שנים\u0004 — החישוב נעשה \u0003כפי שניו. אמר רב יוסף: דרשינהו\u0004 \u0005[דרש]\u0006 \u0003רב נחמן\u0004 בר יצחק \u0003להני קראי כסיני\u0004 \u0005[את אותם המקראות כ\u0006אילו ניתנו כך ב\u0005סיני].\u0006","שנינו במשנה: \u0003לא ימכור\u0004 אדם משדה אחוזתו שנמצאת \u0003ב\u0004מקום \u0003רחוק\u0004 ויגאל במקום קרוב, ולכן לא ימכור ברעה ויגאל ביפה, ולא ילוה ויגאל, ולא יגאל לחצאין. ואומרים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בברייתא\u0005],\u0006 נאמר בתורה: \"והשיגה ידו ומצא כדי גאולתו\" (שם כה, כו), ויש לדרוש: \u0003\"והשיגה ידו\"\u0004 — \u0003יד עצמו, שלא ילוה ויגאל;\u0004","\u0003\"ומצא\u0004 כדי גאולתו\" — \u0003פרט ל\u0004דבר שכבר היה \u0003מצוי\u0004 בידו לפני כן, ללמדנו \u0003שלא ימכור ב\u0004נכסים שהיו לו בשעה שמכר שדה זו, וכגון שלא ימכור בנכסים שיש לו המצויים במקום \u0003רחוק ויגאול בקרוב, ברע ויגאול ביפה; \"כדי גאלתו\"\u0004 — \u0003כדי גאולה\u0004 של כל השדה שמכר \u0003הוא גואל, ואינו גואל לחצאין.\u0004","ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003\"ומצא\"\u0004 שבתורה, דבר שנמצא \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003משמע? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא, נאמר בתורה לגבי רוצח בשוגג שחייב גלות: \"ונשל הברזל מן העץ ומצא את רעהו ומת הוא ינוס...\" (דברים יט, ה), ודורשים: \u0003\"ומצא\"\u0004 — \u0003פרט לממציא עצמו, מיכן אמר ר' אליעזר: אם משיצאה אבן מתחת ידו\u0004 של המשליך, \u0003הוציא\u0004 אחר כך \u0003הלה\u0004 (הנרצח) \u0003את ראשו וקיבלה\u0004 ונהרג — \u0003פטור\u0004 המשליך מגלות; \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"מצא\"\u0004 שבכתוב \u0003מידי דאיתיה מעיקרא\u0004 \u0005[דבר שישנו מתחילה]\u0006 \u0003משמע!\u0004","\u0003אמר רבא:\u0004 אין כאן סתירה, אלא \u0003הכא מענינא דקרא והכא מענינא דקרא\u0004 \u0005[כאן\u0006 נלמד הדבר \u0005מעניינו של המקרא וכאן מעניינו של המקרא],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 בגאולת שדה, יש לפרש \"ומצא\" \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"השיגה ידו\", מה \"השיגה ידו\"\u0004 מובנו ממון \u0003דהשתא\u0004 \u0005[ש\u0006השיגה ידו \u0005עכשיו],\u0006 \u0003אף \"מצא\" נמי\u0004 \u0005[גם כן]\u0006 עניינו נכסים \u0003דהשתא\u0004 \u0005[של עכשיו],\u0006 שלא היו בידו מתחילה. \u0003והכא\u0004 \u0005[ו\u0006אילו \u0005כאן]\u0006 ברוצח בשוגג, יש לפרש \"ומצא\" \u0003דומיא\u0004 \u0005[בדומה\u0006 לעניינו\u0005]\u0006 של \u0003יער\u0004 האמור שם (\"ואשר יבוא את רעהו ביער... ונשל הברזל מן העץ ומצא את רעהו\"), \u0003מה יער\u0004 — \u0003מילתא דאיתיה מעיקרא\u0004 \u0005[דבר שהיה מתחילה],\u0006 \u0003אף \"מצא\"\u0004 — \u0003מילתא דאיתיה מעיקרא\u0004 \u0005[דבר שהיה מתחילה],\u0006 ולכן אם המציא הנרצח את עצמו, שהוציא את ראשו אחר שנשל הברזל מן העץ — פטור מגלות.","שנינו במשנה: לא ימכור ברחוק ויגאל בקרוב וכו', \u0003ובהקדש\u0004 מותר בכולן, זה חומר בהדיוט מבהקדש. ואומרים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בברייתא\u0005],\u0006 נאמר בתורה בענין מקדיש שדהו: \u0003\"ואם גאל יגאל\u0004 את השדה המקדיש אותו\" (ויקרא כז, יט), ובלשון הכפולה הכתוב מוסיף בגאולה זו, יתר על גאולה מיד ההדיוט — \u0003מלמד שלוה וגואל, וגואל לחצאין.\u0004","\u0003אמר ר' שמעון: מה טעם\u0004 יש בדבר? \u0003לפי שמצינו במוכר שדה אחוזה שיפה כחו, שאם הגיע יובל ולא נגאלה חוזרת לבעלים ביובל\u0004 — לפיכך \u0003הורע כחו\u0004 מצד אחר, \u0003שאינו לוה וגואל, ואינו גואל לחצאין.\u0004","\u0003אבל מקדיש שדה אחוזה, הואיל שהורע כחו, שאם הגיע יובל ולא נגאלה יוצא\u0004 השדה \u0003לכהנים\u0004 — לפיכך \u0003יפה כחו, שלוה וגואל וגואל לחצאין.\u0004"],["ומתקשים: סתירה יש בענין גאולה מן ההקדש, \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003לוה וגואל וגואל לחצאין, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אינו לוה וגואל ואינו גואל לחצאין!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו],\u0006 שאינו לווה וגואל — כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003והא\u0004 \u0005[ו\u0006ברייתא \u0005זו]\u0006 שלווה וגואל — כשיטת \u0003ר' שמעון,\u0004 שמיקל בגאולה מן ההקדש.","\u0003המוכר בית בבתי ערי חומה\u0004 — \u0003הרי זה גואל מיד,\u0004 בעל כורחו של הקונה, \u0003וגואל כל שנים עשר חדש,\u0004 ולא מעבר לכך. וכשגואל בתוך שנה ומחזיר המוכר את דמי המכירה לקונה, \u0003הרי זה,\u0004 לכאורה, כמין רבית, שבשכר שהיו מעותיו של הקונה ביד המוכר — דר הקונה בביתו בחינם כל אותו זמן, \u0003ו\u0004אולם \u0003אינו רבית,\u0004 שהרי כשדר בבית היה הבית שלו.","אם \u0003מת המוכר\u0004 בתוך שנה — \u0003יגאל בנו\u0004 של המוכר מיד הקונה, וכן אם \u0003מת הלוקח\u0004 — \u0003יגאל\u0004 המוכר \u0003מיד בנו\u0004 של הלוקח. אם בתוך שנה למכירת הבית מכרו הקונה לאדם אחר, \u0003אין מונין שנה\u0004 לאפשרות הגאולה \u0003אלא משעה שמכר\u0004 הבעלים לקונה הראשון, \u0003שנאמר:\u0004 \"ואם לא יגאל \u0003עד מלאת לו שנה\u0004 תמימה\" (ויקרא כה, ל), \"לו\" — לבעלים.","\u0003כשהוא אומר \"תמימה\"\u0004 הרי זה \u0003להביא\u0004 (להוסיף) \u0003את חדש העיבור,\u0004 שאם מכרה בשנה מעוברת יכול לגאול עד מלאת שלושה עשר חודש. רבי אומר: מה שנאמר \"תמימה\" בא \u0003ליתן לו שנה ועיבורה,\u0004 כלומר, שלוש מאות ששים וחמישה יום, כמנין ימות שנת החמה, אחד עשר יום יותר ממנין ימי שנת הלבנה. \u0003הגיע\u0004 ה\u0003יום\u0004 האחרון של \u0003שנים עשר חדש ו\u0004עדיין \u0003לא נגאלה\u0004 — \u0003היתה חלוטה לו,\u0004 כלומר, שייכת לגמרי לקונה. \u0003אחד הלוקח\u0004 (הקונה) \u0003ואחד הניתן לו במתנה\u0004 שווים בדין זה, \u0003שנאמר:\u0004 \"וקם הבית אשר בעיר אשר לו חומה \u0003לצמיתות\u0004 לקונה אותו\" (שם).","ומעירים: \u0003מתניתין\u0004 \u0005[\u0006\u0005משנתנו]\u0006 שאמרה שהמוכר בית בבתי ערי חומה הרי זה גואל מיד, ש\u0003לא כ\u0004שיטת \u0003רבי\u0004 היא. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר,\u0004 נאמר בתורה: \u0003\"ימים\u0004 תהיה גאולתו\" (ויקרא כה, כט), ו\u0003אין ימים פחות משנים.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"ימים\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך הוא]\u0006 ללמדנו שמחשבים את השנה \u0003מיום ליום,\u0004 עד לאותו יום ואותו חודש בשנה הבאה, ואין אומרים שנגמרה השנה בהגיע אחד בתשרי. ושואלים: \u0003ורבי,\u0004 הצורך לחשב את השנה \u0003מיום ליום, מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שנאמר \u0003\"עד תום שנת ממכרו\"\u0004 (שם), ללמד שהשנה מחושבת מזמן המכר.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם דורשים מכתוב זה? ומשיבים: הכתוב \u0003ההוא\u0004 באמת \u0003מיבעי ליה\u0004 \u0005[נצרך הוא]\u0006 ללמדנו ל\u0003שנת ממכרו\u0004 — \u0003שלו,\u0004 \u0003ולא שנת של מנין עולם,\u0004 וכדברי רבי. \u0003ו\u0004הכתוב \u0003\"ימים\u0004 תהיה גאולתו\" \u0003מיבעי להו\u0004 \u0005[נצרך להם\u0006\u0005]\u0006 \u0003ל\u0004למד שהשנה נמנית לא רק מיום ליום, אלא גם \u0003מעת לעת,\u0004 משעה לשעה, ואין השנה נגמרת כבר בתחילת אותו יום בשנה הבאה. \u0003דאי\u0004 \u0005[שאם]\u0006 היו צריכים ללמוד רק \u0003מ\"עד תום שנת ממכרו\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מיום ליום\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003מעת לעת\u0004 — \u0003לא\u0004 יכול לגאול, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"ימים\".\u0004","ושואלים: \u0003ורבי,\u0004 שמונים שנה \u0003מעת לעת מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 \u0003מ\u0004הכתוב \"ואם לא יגאל עד מלאת לו שנה \u0003תמימה\".\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה למדים הם מ\"תמימה\"? ומשיבים: הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך הוא]\u0006 \u0003לעיבורה,\u0004 כלומר להוסיף בשנה מעוברת את חודש העיבור, כפי ששנינו במשנה.","ושואלים: \u0003ורבי נמי\u0004 \u0005[גם כן].\u0006 \u0003הא מיבעי ליה\u0004 \u0005[הרי\u0006 הוא \u0005צריך אותו],\u0006 את \"תמימה\", \u0003לעיבורה!\u0004 ומשיבים: באמת, \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006 הדבר\u0005],\u0006 שהוא לומד מ\"תמימה\" להוסיף את עיבורה של השנה, ומה שמונים שנה גם \u0003מיום ליום ו\u0004גם \u0003מעת לעת,\u0004 שניהם דין אחד הם, ו\u0003מ\"עד תום שנת ממכרו\" נפקא\u0004 \u0005[\u0006הוא \u0005יוצא,\u0006 נלמד\u0005].\u0006","שנינו במשנה לגבי המוכר בית חומה וגואלו: \u0003הרי זו כמין רבית,\u0004 שהמוכר מחזיר לקונה את הדמים שנתן לו, ואינו מנכה לו מן הסכום את מה שנשתמש בביתו במשך זמן זה, ואולם אינו ריבית. ושואלים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הרי זו רבית גמורה, אלא שהתורה התירתו\u0004 כאן!","\u0003אמר ר' יוחנן, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[\u0006משנתנו \u0005זו]\u0006 כשיטת \u0003ר' יהודה, והא רבנן\u0004 \u0005[ו\u0006ברייתא \u0005זו\u0006 כשיטת \u0005חכמים]\u0006 היא. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הרי שהיה\u0004 אדם \u0003נושה בחבירו מנה\u0004 (שהיה חבירו חייב לו מאה דינרים), \u0003ועשה לו\u0004 הלווה את \u0003שדהו מכר,\u0004 שאם לא יפרענו במועד הרי שדהו מכורה לו מעכשיו, \u0003בזמן שהמוכר\u0004 (הלווה) \u0003אוכל\u0004 את \u0003פירות\u0004 השדה עד מועד הפרעון — הרי זה \u0003מותר,\u0004 ואם ה\u0003לוקח\u0004 (המלוה) \u0003אוכל פירות\u0004 עד שיפרע לו — \u0003אסור,\u0004 משום ריבית, שאם יחזיר הלווה את המעות ולא יחול המכר, נמצא שהמלוה אכל את הפירות בשכר המתנת מעותיו שהיו ביד הלווה באותה שעה.","\u0003ר' יהודה אומר: אף בזמן שהלוקח אוכל פירות\u0004 — \u0003מותר. אמר ר' יהודה:\u0004 ראיה לדברי, שהרי \u0003מעשה בביתוס בן זונין שעשה שדהו מכר על פי רבי אלעזר בן עזריה, ו\u0004ה\u0003לוקח אוכל פירות היה\u0004 באותו המעשה. \u0003אמרו לו: משם\u0004 מביא אתה \u0003ראייה?\u0004 הפוך היה המעשה, ה\u0003מוכר אוכל פירות היה, ולא\u0004 ה\u0003לוקח.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל לדין \u0005ביניהם]?\u0006 ומסבירים: \u0003צד אחד ברבית איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 כלומר, הסכם שיש בו ריבית אם תתממש רק אחת משתי האפשרויות. וכגון כאן, שאם יפרע הלווה את חובו — נמצא שהיתה כאן הלואה שיש עמה ריבית, ואם לא יפרע הלווה את חובו ונשארת השדה ביד המלוה — נמצא שלא היתה כאן ריבית, \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003צד אחד ברבית\u0004 — גם הוא \u0003אסור, ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003צד אחד ברבית\u0004 — \u0003מותר.\u0004"],["\u0003רבא אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 גם \u0003צד אחד ברבית אסור,\u0004 אם אכן יש אפשרות שיבואו לידי ריבית, \u0003והכא\u0004 \u0005[וכאן]\u0006 שנחלקו ר' יהודה וחכמים — \u0003ברבית על מנת להחזיר איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 כלומר, במקרה שהתנו שאם יפרע הלווה את החוב — יחזיר לו המלוה את הפירות שאכל בינתיים מן השדה, \u0003מר סבר\u0004 \u0005[חכם\u0006 זה, התנא הראשון \u0005סבור]:\u0006 למרות שיחזיר את הפירות שיאכל בינתיים — \u0003אסור\u0004 לעשות כן, \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה, ר' יהודה \u0005סבור]:\u0006 \u0003מותר\u0004 לעשות כן.","שנינו במשנה: המוכר לחבירו בית בעיר חומה, אם \u0003מת המוכר יגאל בנו.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, שהרי הוא יורש את נחלתו! ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003\"ואיש כי ימכר בית מושב\u0004 עיר חומה והיתה גאולתו עד תום שנת ממכרו\" (ויקרא כה, כט) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומשמע כי האיש שמכר הוא הגואל, \u0003והאי\u0004 \u0005[וזה]\u0006 הבן, הרי \u0003לאו\u0004 \u0005[לא]\u0006 הוא \u0003מכר,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]:\u0006 הכתוב: \u0003\"והיתה גאלתו\" מכל מקום,\u0004 בכל אופן תהיה לו גאולה, אם לא על ידי הבעלים — על ידי בנו.","עוד שנינו במשנה: \u0003מת הלוקח\u0004 — \u0003יגאל\u0004 המוכר \u0003מיד בנו וכו'.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \"וקם הבית אשר בעיר אשר לו חומה לצמיתות \u0003לקנה אתו\"\u0004 (שם ל) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 הבן הרי \u0003לא\u0004 הוא \u0003קנה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב: \u0003\"והיתה גאלתו\" מכל מקום,\u0004 גם מיד הבן.","שנינו במשנה: \u0003אין מונין לו שנה אלא משעה שמכר,\u0004 שנאמר: \"ואם לא יגאל עד מלאת לו שנה\" (ויקרא כה, ל). ומביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 כשהכתוב אומר: \"עד מלאת לו \u0003שנה\",\u0004 אם הקונה מכרה לאדם אחר, \u0003איני יודע אם\u0004 מונים \u0003שנה\u0004 מזמן שמכרו הבעלים \u0003לראשון,\u0004 או \u0003אם שנה\u0004 מזמן שמכרו הקונה הראשון \u0003ל\u0004קונה ה\u0003שני, כשהוא אומר: \"עד מלאת לו שנה תמימה\"\u0004 — \u0003הוי\u0004 אומר \u0003שנה\u0004 מזמן שמכרו הבעלים \u0003לראשון.\u0004","ויש לשאול: אם לא גאלו הבעלים את הבית בתוך שנה למכירה הראשונה, \u0003למי חלוט\u0004 הבית? \u0003ר' אלעזר אומר: ל\u0004קונה ה\u0003ראשון חלוט, ר' יוחנן אמר: לשני חלוט.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' אלעזר\u0004 מובן מדוע הבית חלוט לראשון — \u0003דלדידיה קא מנינן\u0004 \u0005[ש\u0006הרי \u0005ל\u0006קנין \u0005שלו אנו מונים\u0006 שנה\u0005],\u0006 לפיכך ראוי שייחלט לו הבית. \u0003אלא לר' יוחנן מאי טעמא\u0004 \u0005[מה טעם]\u0006 חלוט לשני כבר באותה שעה? \u0003אמר ר' אבא בר ממל:\u0004 שהרי \u0003מה מכר לו\u0004 הקונה ה\u0003ראשון ל\u0004קונה ה\u0003שני\u0004 — \u0003כל זכות שתבא\u0004 (שבאה) \u0003לידו,\u0004 ובכללה הזכות שהבית ייחלט בידו כעבור שנה מזמן שהוא קנה אותו.","\u0003אמר ר' אבא בר ממל: מכר שני בתי ערי חומה, אחד\u0004 מכר \u0003בחמשה עשר באדר הראשון ואחד באחד באדר השני; זה שמכר לו\u0004 באחד באדר השני, כיון שהגיע יום אחד באדר של שנה הבאה — \u0003עלתה לו שנה\u0004 ונחלט לו הבית, ו\u0003זה שמכר לו בחמשה עשר של אדר הראשון\u0004 — \u0003לא עלתה לו שנה עד חמשה עשר באדר של שנה הבאה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא, ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 הראשון לשני: כיצד ייתכן הדבר? והלוא \u0003אנא קדים שחין נורא מקמא דידך\u0004 \u0005[אני הקדמתי והדלקתי אש לפניך],\u0006 כלומר, קניתי את הבית שבידי לפניך! ומשיבים: \u0003משום דאמר ליה\u0004 \u0005[שאומר לו\u0006 השני\u0005]:\u0006 \u0003את נחית לעיבורא\u0004 \u0005[אתה ירדת ל\u0006בית בחודש ה\u0005עיבור],\u0006 והרי שנינו במשנתנו שנותנים למוכר גם את חודש העיבור.","\u0003ו\u0004כיוצא בזה \u0003אמר ר' אבא בר ממל: נולדו לו שני טלאים, אחד\u0004 נולד \u0003בחמשה עשר של אדר הראשון ואחד באחד באדר השני, זה שנולד באדר השני, כיון שהגיע יום אחד באדר השני של שנה הבאה\u0004 — \u0003עלתה לו שנה,\u0004 ואם היה בכור צריך להקריבו לכתחילה עד אז, \u0003זה שנולד לו בחמשה עשר באדר הראשון\u0004 — \u0003לא עלתה לו שנה עד חמשה עשר באדר של שנה הבאה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא, ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 הטלה שנולד ראשון: \u0003אנא קדים אכיל ירוקא מקמא דידך\u0004 \u0005[אני קדמתי\u0006 להיוולד \u0005ואכלתי ירק לפניך]! ומשיבים:\u0006 \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 השני: \u0003את נחיתת לעיבורא\u0004 \u0005[אתה ירדת ל\u0006חודש ה\u0005עיבור]\u0006 שהוא מתווסף לחשבון השנה, \u0003אנא לא נחיתנא לעיבורא\u0004 \u0005[אני לא ירדתי ל\u0006חודש ה\u0005עיבור].\u0006","ושואלים: \u0003הא תו\u0004 \u0005[\u0006הלכה \u0005זו\u0006 בענין טלאים \u0005עוד]\u0006 \u0003למה לי\u0004 לאומרה? והרי היינו הך \u0005[הרי זה אותו דבר]!\u0006 ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בבתי ערי חומה הדין כן, משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתורה \u0003\"תמימה\"\u0004 (ויקרא כה, ל) כפי שלמדנו במשנה, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בטלאים \u0003דלא כתיב\u0004 \u0005[שלא נאמר]\u0006 \u0003\"תמימה\"\u0004 — \u0003לא\u0004 שייך דין זה, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003\"שנה\" \"שנה\" מהדדי גמרי\u0004 \u0005[זה מזה הם למדים]\u0006 בגזירה שווה, שנאמר בבית עיר חומה: \"ואם לא יגאל עד מלאת לו שנה תמימה\" (ויקרא כה, ל), ונאמר בטלאים: \"שה תמים זכר בן שנה יהיה לכם\" (שמות יב, ה).","שנינו במשנה: \u0003כשהוא אומר \"תמימה\"\u0004 — להביא את חודש העיבור, \u0003רבי אומר: ליתן\u0004 לו \u0003שנת עיבורה.\u0004 ומביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 מה פרוש הכתוב \u0003\"שנה תמימה\"? רבי אומר: מונה\u0004 תמיד \u0003שלש מאות וששים וחמשה ימים כמנין ימות החמה,\u0004 והם אחד עשר יום יותר משנת הלבנה. \u0003וחכמים אומרים:\u0004 בשנה רגילה \u0003מונה שנים עשר חודש מיום ליום, ואם נתעברה\u0004 השנה — \u0003נתעברה לו\u0004 (למוכר) ויכול לגאול במשך חודש נוסף.","שנינו במשנה: \u0003הגיע יום שנים עשר חודש ולא נגאל\u0004 היה חלוט לו, אחד הלוקח ואחד שניתן לו בית במתנה, שנאמר: \"לצמיתות\" (ויקרא כה, ל). ומביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 מה שנאמר \"וקם הבית... \u0003לצמיתות\",\u0004 כוונתו \u0003לחלוטין,\u0004 באופן סופי, שהמוכר אינו יכול לגואלו בעל כרחו, ואינו חוזר אליו ביובל. \u0003דבר אחר: \"לצמיתות\"\u0004 — \u0003לרבות את ה\u0004בית שניתן ב\u0003מתנה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם],\u0006 כיצד נלמד דין מתנה — שיכול היה להיכתב \u0003\"צמית\"\u0004 ונכתב \u0003\"צמיתות\".\u0004","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו אותה,\u0006 ברייתא זו, \u0005חכמים לפני]\u0006 \u0003רב פפא,\u0004 ואמרו: \u0003כמאן\u0004 \u0005[כשיטת מי\u0006 הברייתא\u0005]?\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' מאיר, דאי\u0004 \u0005[שאם]\u0006 \u0003כר' מאיר\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 לגבי חזרת שדה אחוזה ביובל, שה\u0003מתנה אינה כמכר.\u0004 ואם כן, בית עיר חומה שניתן כמתנה — אינו נחלט לאחר שנים עשר חודש! \u0003אמר רב פפא: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהברייתא היא כשיטת \u0003ר' מאיר, שאני הכא\u0004 \u0005[שונה כאן]\u0006 הדין, \u0003דרבי רחמנא\u0004 \u0005[שריבתה התורה]\u0006 בלשון \u0003\"לצמיתות\",\u0004 ללמד שהמתנה נידונה כמכר.","\u0003אמרו רבנן\u0004 \u0005[אמרו חכמים]\u0006 \u0003לרב פפא, ואמר לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: והא גבי\u0004 \u0005[והרי אצל]\u0006 שדה אחוזה שחוזרת ב\u0003יובל,\u0004 שיש ריבוי מיוחד של הכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"בשנת היובל הזאת \u0003תשבו\u0004 איש אל אחוזתו\" (שם יג) וחכמים למדים משם \u0003לרבות את המתנה, ו\u0004אף על פי כן \u0003ר' מאיר לא קא מרבי\u0004 \u0005[לא מרבה]\u0006 את המתנה! \u0003אלא\u0004 צריך לומר ש\u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו] ודאי\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' מאיר.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003המקדיש בית בבתי ערי חומה\u0004 — \u0003הרי זה גואל\u0004 אותו מיד ההקדש בתוך שנתו, \u0003ו\u0004גם \u0003גואל לעולם,\u0004 ואפילו כעבור שנה (שלא כדין המוכר). אם \u0003גאלו\u0004 איש \u0003אחר מיד הקדש,\u0004 ו\u0003הגיע יום שנים עשר חודש\u0004 מאז שגאלו מההקדש \u0003ולא נגאל\u0004 הבית על ידי בעליו — \u0003היה\u0004 הבית \u0003חלוט לו\u0004 לאיש האחר.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר שמואל, דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \"ואם לא יגאל עד מלאת לו שנה תמימה וקם הבית... \u0003לקנה אותו\u0004 לדורותיו לא יצא ביובל\" (ויקרא כה, ל) — לכל הקונה בית כזה, \u0003ואפילו\u0004 זה שקנאו \u0003מיד הקדש.\u0004 ושואלים: אם כן, מדוע יכול המקדישו לגואלו לעולם? \u0003ולחלטיה\u0004 \u0005[ושיחלטנו]\u0006 ה\u0003הקדש,\u0004 אם לא גאלו המקדיש בתוך שנה! ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 שם: \u0003\"לדרתיו\",\u0004 ולפיכך, \u0003יצא הקדש ש\u0004אינו אדם ו\u0003אין לו דורות.\u0004","ושואלים: מה שנאמר בדין מוכר בית עיר חומה \u0003\"לא יצא ביובל\" למה לי?\u0004 והרי כבר נאמר \"לצמיתות\"! \u0003אמר רב ספרא: לא נצרכא\u0004 \u0005[לא נצרכה]\u0006 \u0003אלא\u0004 ללמד \u0003ל\u0004גבי \u0003מוכר בית בבתי ערי חומה, ופגע בו יובל בתוך שנתו\u0004 של המכר, \u0003סלקא דעתך אמינא ליפוק\u0004 \u0005[יעלה על דעתך לומר שיצא]\u0006 הבית לבעליו \u0003ביובל,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003\"לא יצא ביובל\",\u0004 שאין היובל שייך בדין בית עיר חומה.","\u0003בראשונה היה\u0004 הקונה בית עיר חומה \u0003נטמן\u0004 (מסתתר) ב\u0003יום\u0004 האחרון שב\u0003שנים עשר חודש, כדי ש\u0004לא יחזיר לו המוכר את הכסף, וממילא \u0003יהא\u0004 הבית \u0003חלוט לו\u0004 לקונה. \u0003התקין הלל שיהא\u0004 המוכר \u0003חולש\u0004 (מטיל) \u0003מעותיו ללשכה\u0004 של בית הדין, \u0003ויהא שובר את הדלת ונכנס\u0004 לבית, ו\u0003אימתי שירצה הלז\u0004 (הקונה) \u0003יבא\u0004 ללשכה \u0003ויטול את מעותיו.\u0004","\u0003אמר רבא: מתקנתו של הלל\u0004 במשנתנו יש ללמוד שהאומר לאישה: \u0003\"הרי זה גיטיך על מנת שתתני לי מאתים זוז\", ונתנה לו\u0004 אותם, אם היה זה \u0003מדעתו\u0004 — הרי שנתקיים התנאי והיא \u0003מגורשת,\u0004 אך אם נתנה לו אותם \u0003בעל כרחו\u0004 — \u0003אינה מגורשת.\u0004 ומסבירים:"],["ומה הראיה לדבר? \u0003מדאיצטריך ליה\u0004 \u0005[מ\u0006מה \u0005שהוצרך לו]\u0006 \u0003להלל לתקוני\u0004 \u0005[לתקן]\u0006 כאן תקנה מיוחדת ש\u0003נתינה בעל כרחו הויא\u0004 \u0005[נחשבת]\u0006 \u0003נתינה, הא בעלמא\u0004 \u0005[הרי\u0006 ש\u0005בסתם]\u0006 \u0003נתינה בעל כרחו לא הויא\u0004 \u0005[אינה נחשבת]\u0006 \u0003נתינה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003רב אשי: ודילמא כי איצטריכא ליה להלל לתקוני\u0004 \u0005[ושמא כאשר הוצרכה לו להלל לתקן]\u0006 תקנה זו, הרי זה בנתינה \u0003שלא בפניו,\u0004 שהרי כאן הסתתר הקונה, \u0003אבל\u0004 כשנותן למקבל \u0003בפניו\u0004 — \u0003בין מדעתו בין בעל כרחו הויא\u0004 \u0005[הרי זו]\u0006 \u0003מתנה!\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שמועה זו באופן אחר, \u0003אמר רבא: מתקנתו של הלל\u0004 יש ללמוד שהאומר לאשה: \u0003\"הרי זה גיטיך על מנת שתתני לי מאתים זוז\", ונתנה לו\u0004 אותם, \u0003בין מדעתו בין בעל כרחו\u0004 — \u0003הויא\u0004 \u0005[הרי זו]\u0006 \u0003נתינה,\u0004 והיא מגורשת. \u0003וכי איצטריך ליה\u0004 \u0005[וכאשר הוצרך לו]\u0006 \u0003להלל לתקוני\u0004 \u0005[לתקן]\u0006 — היה זה מפני שהקונה הסתתר, והנתינה היתה \u0003שלא בפניו, אבל\u0004 נתינה \u0003בפניו\u0004 — \u0003בין מדעתו בין בעל כרחו הויא\u0004 \u0005[הרי היא]\u0006 \u0003נתינה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב שימי בר אשי: ודילמא\u0004 \u0005[ושמא]\u0006 \u0003בין בפניו בין שלא בפניו,\u0004 נתינה \u0003מדעתו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נחשבת לנתינה, \u0003בעל כרחו\u0004 — \u0003לא\u0004 נחשבת נתינה, \u0003והלל מאי דאיצטריך ליה תקין\u0004 \u0005[מה שהוצרך לו תיקן],\u0006 מפני שהקונים היו מסתתרים, אך אם היו נמצאים ומסרבים לקבל את המעות — גם אז היה צריך לתקנתו!","\u0003כל\u0004 מה \u0003שהוא\u0004 נמצא \u0003לפנים מן החומה\u0004 — \u0003הרי הוא כבתי ערי חומה\u0004 לדין גאולתו, \u0003חוץ מן השדות\u0004 שבתוכה. \u0003ר' מאיר אומר: אף השדות\u0004 בכלל זה. \u0003בית הבנוי בחומה\u0004 עצמה, \u0003ר' יהודה אומר: אינו כבתי ערי חומה, ר' שמעון אומר: כותל החיצון היא חומתו,\u0004 ונידון כבית בעיר חומה.","בענין מה ששנינו במשנה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 נאמר בתורה: \"וקם ה\u0003בית\u0004 אשר בעיר אשר לו חומה לצמיתות לקונה אותו\" (ויקרא כה, ל) — \u0003אין לי אלא בית, מנין לרבות\u0004 גם \u0003בתי בדים\u0004 (שמייצרים בהם שמן) \u0003ובתי מרחצאות, ומגדלות, ושובכין, ובורות ושיחין\u0004 (שוחות, חפירות בקרקע) \u0003ומערות? תלמוד לומר: \"אשר בעיר\",\u0004 ללמדנו שכל מה שבעיר נכלל בכך. \u0003יכול שאני מרבה אף השדות\u0004 שבעיר? \u0003תלמוד לומר: \"בית\",\u0004 למעט שדה, שאינו מבנה המכיל דבר_מה. אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' מאיר אומר:\u0004 נאמר \u0003\"בית\"\u0004 — \u0003אין לי אלא בית, מנין לרבות\u0004 \u0003בתי בדים ובתי מרחצאות, ומגדלות ושובכין, ובורות שיחין ומערות, ואפילו שדות? תלמוד לומר: \"אשר בעיר\",\u0004 ללמדנו שכל מה שבעיר בכלל.","ושואלים על דעת ר' מאיר: \u0003ואלא הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"בית\"! אמר רב חסדא אמר רב קטינא: חולסית,\u0004 שטח מסולע, שנוטלים משם אבנים לבנין, \u0003ומצולה,\u0004 שנוטלים ממנה חול לבנין, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 בין ר' יהודה ור' מאיר, ודווקא באלה סבור ר' מאיר שדינם כבית. אבל שדה ממש — גם לדעתו אינו בכלל דין זה. ומוסיפים: \u0003והתניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003חולסית ומצולה\u0004 שבעיר חומה, \u0003ר' מאיר אומר:\u0004 דינם \u0003כבתים, ר' יהודה אומר:\u0004 דינם \u0003כשדות.\u0004","שנינו במשנה: \u0003בית הבנוי בחומה\u0004 — \u0003ר' יהודה אומר: אינו כבתי ערי חומה,\u0004 ר' שמעון אומר: כותל החיצון הוא חומתו. \u0003אמר ר' יוחנן, ושניהם מקרא אחד דרשו,\u0004 שנאמר ברחב: \u0003\"ותורדם בחבל בעד החלון כי ביתה בקיר החומה ובחומה היא יושבת\"\u0004 (יהושע ב, טו), כיצד להבין \"ובחומה היא יושבת\", \u0003ר' (מאיר) [שמעון] סבר כפשטיה דקרא\u0004 \u0005[סבור כפשוטו של המקרא],\u0006 \u0003ור' יהודה סבר\u0004 \u0005[סבור]\u0006 כי יש לדייק מן הכתוב: \u0003\"בחומה היא יושבת\",\u0004 כלומר, נחשבת כתושבת החומה עצמה, \u0003ולא\u0004 נחשבת כיושבת \u0003בעיר חומה.\u0004","\u0003עיר שגגותיה חומתה,\u0004 שבתיה בנויים ברצף אחד כחומה, והגגות הם ראש החומה, \u0003ו\u0004כן עיר \u0003שאינה מוקפת חומה מימות יהושע בן נון,\u0004 אלא הוקפה רק לאחר מכן — \u0003אינה כבתי ערי חומה. ואלו הן בתי ערי חומה:\u0004 כל שיש בעיר לפחות \u0003שלש חצרות של\u0004 \u0003שני בתים\u0004 בכל אחת מהן, ושהיא \u0003מוקפת חומה מימות יהושע בן נון, כגון קצרה\u0004 (המצודה) \u0003הישנה של ציפורי,\u0004 \u0003וחקרה\u0004 (מצודה) \u0003של גוש חלב, ויודפת הישנה, וגמלא, וגדוד, וחדיד, ואונה, וירושלים, וכן\u0004 ערים \u0003כיוצא בהן.\u0004","בענין ששנינו במשנה, שעיר שגגותיה חומתה אינה נידונת כעיר חומה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 מה שנאמר בתורה: \"בית אשר בעיר אשר לו \u0003חומה\"\u0004 (ויקרא כה, ל), בא להדגיש — אשר יש לו חומה, \u0003ולא שור איגר\u0004 \u0005[חומת גגות],\u0006 שהבית עצמו הוא החומה. ומה שנאמר בתורה: \"ובתי החצרים אשר אין להם חומה \u0003סביב\u0004 על שדה הארץ יחשב\" (שם לא) ואינם כדין בתי ערי חומה, בא הדבר להדגיש — \u0003פרט לטבריה,\u0004 שאין לה חומה מסביב, אלא \u0003ש\u0004מצידה האחד \u0003ימה\u0004 (ים הכנרת) הוא \u0003חומתה.\u0004","\u0003ר' אליעזר בר יוסי אומר,\u0004 נכתב בתורה: \u0003\"אשר לוא חומה\",\u0004 כאילו נכתב גם \"אשר לו חומה\", אך גם \"אשר לא חומה\" — לומר: \u0003אף על פי שאין לו עכשיו והיה לו קודם לכן\u0004 בימות יהושע, עדיין נחשב לעיר חומה.","שנינו במשנה: \u0003ואלו הן בתי ערי חומה...\u0004 כגון קצרה הישנה של ציפורי, וחקרה של גוש חלב, ויודפת הישנה, וגמלא, וגדוד, וחדיד, ואונה, וירושלים, וכן כיוצא בהן. ומביאים, \u0003תנא\u0004 \u0005[שנה\u0006 על כך \u0005החכם\u0006 בברייתא\u0005]:\u0006 \u0003גמלא בגליל, וגדוד בעבר הירדן, וחדיד ואונה וירושלים ביהודה.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 וכי אלו הערים היחידות מוקפות החומה בגליל, בעבר הירדן וביהודה?"],["\u0003אמר אביי, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003עד גמלא בגליל,\u0004 כלומר, כל העיירות שבגליל מגמלא ולדרום היו מוקפות חומה מימות יהושע, וכן כל העיירות \u0003עד גדוד בעבר הירדן,\u0004 שהיא המזרחית לכולן, \u0003ו\u0004כן \u0003חדיד ואונו וירושלים ב\u0004ארץ \u0003יהודה\u0004 הריהן מוקפות חומה מימות יהושע.","\u0003רבא אמר:\u0004 כוונת הברייתא לפרש את משנתנו ולומר כי \u0003גמלא\u0004 שנזכרה במשנה כמוקפת חומה מימות יהושע, היא זו ש\u0003בגליל, לאפוקי\u0004 \u0005[להוציא]\u0006 כל עיר אחרת בשם \u0003גמלא\u0004 שנמצאת ב\u0003שאר ארצות\u0004 (יהודה ועבר הירדן), וכן \u0003גדוד\u0004 היא זו ש\u0003בעבר הירדן, לאפוקי\u0004 \u0005[להוציא]\u0006 כל עיר אחרת בשם \u0003גדוד\u0004 שנמצאת ב\u0003שאר ארצות\u0004 (יהודה וגליל), וכן חדיד ואונו וירושלים הן אלו שביהודה — להוציא ערים בשם דומה שנמצאות בגליל ובעבר הירדן. ואילו \u0003אינך דלא איכא דכותייהו לא איצטריך ליה\u0004 \u0005[\u0006הערים \u0005האחרות\u0006 שנזכרו במשנה, כגון יודפת, \u0005שאין\u0006 עיר \u0005כמותן\u0006 בשאר ארצות באותו שם, \u0005לא הוצרך לו\u0006 לתנא לומר\u0005].\u0006","ושואלים: \u0003וירושלים\u0004 שמוזכרת במשנה \u0003מי מיחלט\u0004 \u0005[האם חלוט]\u0006 בה הבית לקונה לאחר שנה כדין עיר חומה? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003עשרה דברים נאמרו בירושלים,\u0004 ואחד מהם ש\u0003אין הבית חלוט בה!\u0004","\u0003אמר ר' יוחנן:\u0004 כוונת התנא לומר שהבית חלוט בכל עיר שהיא \u0003כ\u0004גון \u0003ירושלים,\u0004 שהיא \u0003מוקפת חומה מימות יהושע בן נון, ו\u0004אולם \u0003לא\u0004 שדינה \u0003כירושלים\u0004 עצמה, ש\u0003אילו\u0004 \u0003ירושלים\u0004 עצמה \u0003אין הבית חלוט בה, ואילו הכא\u0004 \u0005[כאן],\u0006 בערים שדומות לה, \u0003הבית חלוט בהן. רב אשי אמר\u0004 תירוץ אחר: \u0003לאו\u0004 \u0005[\u0006וכי \u0005לא]\u0006 \u0003אמר רב יוסף\u0004 בתירוץ קושיה אחרת: \u0003תרי\u0004 \u0005[שתי]\u0006 ערים בשם \u0003קדש הוו\u0004 \u0005[היו]?\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 צריך לומר ש\u0003תרי\u0004 \u0005[שתי]\u0006 ערים בשם \u0003ירושלים הוו\u0004 \u0005[היו]\u0006 ביהודה, ומשנתנו עוסקת בירושלים האחרת, שבה הבית נחלט.","בענין הערים ששנינו במשנתנו \u0003תניא\u0004 \u0005[שנה\u0006 בברייתא\u0005],\u0006 \u0003ר' ישמעאל בר' יוסי: למה מנו חכמים את אלו\u0004 שבמשנה, מכל שאר הערים מוקפות החומה שהיו בארץ בזמן יהושע בן נון? \u0003שכשעלו בני הגולה\u0004 מבבל לאחר חורבן הבית הראשון \u0003מצאו\u0004 את \u0003אלו\u0004 \u0003וקידשום, אבל\u0004 הערים ה\u0003ראשונות בטלו\u0004 מקדושתן \u0003משבטלה קדושת הארץ\u0004 כשחרב המקדש הראשון. ומבארים, \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003קדושה ראשונה\u0004 שנתקדשה הארץ בימי יהושע — \u0003קידשה לשעתה,\u0004 עד שגלו מן הארץ, \u0003ולא קידשה לעתיד לבא.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ש\u0003אמר ר' ישמעאל בר' יוסי: וכי אלו בלבד\u0004 שנמנו במשנתנו \u0003היו\u0004 מוקפות חומה מימי יהושע? \u0003והלא כבר נאמר:\u0004 \"לא היתה קריה אשר לא לקחנו מאתם \u0003ששים עיר כל חבל ארגב... כל אלה ערים בצורות\u0004 חומה גבוהה דלתים ובריח\" (דברים ג, ד—ה)! \u0003אלא למה מנו חכמים את אלו? שכשעלו בני הגולה מצאו\u0004 את \u0003אלו\u0004 שהיו בנויות \u0003וקידשום.\u0004 ותוהים: האם ייתכן שכוונת הברייתא ש\u0003קידשום? הא אמרינן\u0004 \u0005[הרי אומרים אנו]\u0006 בהמשך הברייתא ש\u0003לא צריך לקדושינהו\u0004 \u0005[לקדשם]!\u0006 \u0003אלא\u0004 כוונתה ש\u0003מנאום\u0004 במשנה זו.","וממשיכה הברייתא: \u0003ולא אלו בלבד, אלא כל\u0004 עיר \u0003שתעלה לך מסורת בידך מאבותיך ש\u0004היא \u0003מוקפת חומה מימות יהושע בן נון\u0004 — \u0003כל מצות הללו\u0004 של ערי חומה \u0003נוהגות בה, מפני שקדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא.\u0004 הרי יש סתירה בין הברייתות בדברי ר' ישמעאל בר' יוסי, האם קדושה ראשונה קידשה לעתיד לבוא או לא!","ומשיבים, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003תרי תנאי\u0004 \u0005[\u0006מחלוקת \u0005שני תנאים]\u0006 יש כאן \u0003ואליבא\u0004 \u0005[ולפי\u0006 שיטתו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 בר' יוסי. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003חד מינייהו\u0004 \u0005[אחת מהן,\u0006 מהברייתות\u0005],\u0006 זו האומרת כי קדושה ראשונה קידשה לעתיד לבוא, \u0003ר' אלעזר בר יוסי\u0004 אחיו הוא ש\u0003אמרה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר בר יוסי אומר:\u0004 נאמר בתורה \u0003\"אשר לוא חומה\"\u0004 (ויקרא כה, ל), כאילו נכתב \"לו חומה\" ו\"לא חומה\", ללמד שלא רק שיש לו עכשיו חומה, אלא \u0003אף על פי שאין לו עכשיו\u0004 חומה \u0003והיה לו קודם לכן,\u0004 בימות יהושע בן נון, נידון המקום כבית עיר חומה.","ושואלים: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם,\u0006 המקור בכתוב \u0005של מי שאומר]:\u0006 \u0003קדושה ראשונה קידשה לשעתה ולא קידשה לעתיד\u0004 \u0003לבא? ומשיבים:\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בזמן שיבת ציון: \u0003\"ויעשו בני הגולה השבים מן השבי סכות וישבו בסכות, כי לא עשו מימי יהושע בן נון כן בני ישראל\u0004 עד היום ההוא \u0003ותהי שמחה גדולה מאד\"\u0004 (נחמיה ח, יז). ולכאורה, תמוה הדבר: \u0003אפשר בא דוד\u0004 ומלך על ישראל, וכן שלמה אחריו, \u0003ולא עשו סוכות עד שבא עזרא?\u0004","\u0003אלא מקיש\u0004 (משווה) \u0003ביאתם בימי עזרא לביאתם בימי יהושע,\u0004 לא לענין הישיבה בסוכות, אלא: \u0003מה ביאתם בימי יהושע מנו שמיטין ויובלות וקדשו\u0004 אז \u0003ערי חומה, אף ביאתן בימי עזרא מנו שמיטין ויובלות וקדשו ערי חומה,\u0004","\u0003ו\u0004כן \u0003אומר\u0004 הכתוב בשיבת ישראל מן הגלות: \u0003\"והביאך ה' אלהיך אל הארץ אשר ירשו אבתיך וירשתה\"\u0004 (דברים ל, ה), \u0003מקיש ירושתך\u0004 (\"וירשתה\") \u0003לירושת אבותיך, מה ירושת אבותיך\u0004 היתה מלווה \u0003בחידוש כל דברים הללו,\u0004 שמיטה ויובל, תרומות ומעשרות, \u0003אף ירושתך\u0004 — \u0003בחידוש כל דברים הללו,\u0004 מפני שבטלו הראשונות.","ושואלים: \u0003ואידך\u0004 \u0005[ו\u0006החכם \u0005האחר],\u0006 שלדעתו לא הוצרכו לחזור ולקדש בימי עזרא, כיצד הוא מפרש כתוב זה? ומשיבים: מה שנאמר שעולי הגולה עשו סוכות, ולא נעשה כן מימות יהושע, כוונתו \u0003דבעי רחמי\u0004 \u0005[שביקש\u0006 עזרא \u0005רחמים,\u0006 התפלל\u0005]\u0006 \u0003על יצר\u0004 של \u0003עבודה זרה, ובטליה\u0004 \u0005[וביטל אותו],\u0006 \u0003ואגין זכותא עלייהו כי סוכה\u0004 \u0005[והגנה זכות\u0006 התפילה \u0005עליהם כמו סוכה].\u0006","ומוסיפים: \u0003והיינו דקא קפיד קרא עילויה\u0004 \u0005[וזהו שמקפיד הכתוב\u0006 שם \u0005על]\u0006 \u0003יהושע,\u0004 על שלא עשה כן בימיו, ומנין? \u0003דבכל דוכתא כתיב\u0004 \u0005[ש\u0006הרי \u0005בכל מקום\u0006 במקרא \u0005נאמר]:\u0006 \u0003\"יהושע\", והכא כתיב\u0004 \u0005[וכאן נאמר]:\u0006 \"כי לא עשו כן מימי \u0003ישוע\u0004 בן נון\", הרי שחיסר הכתוב אות משמו. שכן \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003משה,\u0004 מנהיגם הראשון של ישראל, \u0003לא בעא רחמי\u0004 \u0005[לא ביקש רחמים]\u0006 שיתבטל יצר זה, מפני \u0003דלא הוה זכותא\u0004 \u0005[שלא היתה\u0006 אז \u0005זכות]\u0006 של \u0003ארץ ישראל,\u0004 שהרי עדיין לא נכנסו אליה, \u0003אלא יהושע דהוה ליה זכותא\u0004 \u0005[שהיתה לו זכות]\u0006 של \u0003ארץ ישראל,\u0004 \u0003אמאי לא ליבעי רחמי\u0004 \u0005[מדוע לא ביקש רחמים\u0006 שיתבטל\u0005]?\u0006","ושואלים: ולשיטת הסבור שלא הוצרכו לחזור ולקדש בימי עזרא, \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אשר ירשו אבתיך וירשתה\",\u0004 ומכאן משמע שצריך לקדש ערי חומה בשנית, כפי שנאמר לעיל! ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אומר]\u0006 הכתוב: \u0003כיון\u0004 ש\u0003ירשו אבותיך\u0004 — \u0003ירשת את\u0004 \u0005[יורש אתה],\u0006 ואינך צריך לחזור ולקדש.","ושואלים על הברייתא: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003מנו\u0004 בימי עזרא \u0003שמיטין ו\u0004אפילו \u0003יובלות? השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003משגלו שבט ראובן ושבט גד וחצי שבט מנשה\u0004 (ראה דברי הימים א ה, כו) כבר \u0003בטלו\u0004 ה\u0003יובלות,\u0004 למרות שרוב ישראל עדיין ישבו במקומם, \u0003עזרא דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"כל הקהל כאחד ארבע רבוא אלפים ושש מאות וששים\"\u0004 (עזרא ב, סד) כלומר, כארבעים אלף איש, \u0003הוה מני\u0004 \u0005[היה מונה\u0006 יובלות\u0005]?\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003משגלו שבט ראובן ושבט גד וחצי שבט המנשה בטלו יובלות, שנאמר: \"וקראתם דרור בארץ לכל יושביה\u0004 יובל היא תהיה לכם\" (ויקרא כה, י), ולמדים משם ש\u0003בזמן שכל יושביה עליה\u0004 נוהגים דיני היובל, \u0003ולא בזמן שגלו מקצתן.\u0004","\u0003יכול\u0004 אם \u0003היו\u0004 יושבים \u0003עליה\u0004 כל ישראל, \u0003והן מעורבין, שבט בנימין ביהודה, ושבט יהודה בבנימין,\u0004 ולא כל שבט בנחלתו, \u0003יהא יובל נוהג? תלמוד לומר: \"לכל ישביה\"\u0004 — \u0003בזמן שיושביה כתיקונן, ולא בזמן שהן מעורבין.\u0004 ואם כן, כיצד ייתכן ששבי הגולה המועטים מנו יובלות?","\u0003אמר רב נחמן בר יצחק:\u0004 אמנם לא נהגו דיני היובל, אלא ש\u0003מנו יובלות\u0004 כדי \u0003לקדש שמיטין,\u0004 כלומר, בסוף כל ארבעים ותשע שנים של שבעה מחזורי שמיטה מנו את שנת החמישים כיובל, כדי ששנת השמיטה הבאה תחול בזמנה, בשנה החמישים ואחת."],["ושואלים: \u0003הניחא לרבנן דאמרי\u0004 \u0005[זה נוח ל\u0006דעת \u0005חכמים שאומרים]\u0006 כי \u0003שנת חמשים\u0004 (היובל) \u0003אינה\u0004 חלק \u0003מן המנין\u0004 של מנין שנות השמיטה, \u0003אלא ל\u0004דעת \u0003רבי יהודה\u0004 שאמר: שנת חמשים עולה לכאן ולכאן, כלומר, שהיא נמנית כשנה הראשונה לשמיטה הראשונה של היובל הבא, \u0003למה לי\u0004 למנות את היובלות? והלא אם אין היובל נוהג — \u0003ב\u0004מניית \u0003שמיטין סגיא\u0004 \u0005[די]!\u0006 ומשיבים: \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 \u0003ודאי\u0004 ש\u0003לא כ\u0004שיטת \u0003רבי יהודה\u0004 היא.","ושואלים: \u0003ו\u0004האם \u0003לא מנו שמיטין ויובלות\u0004 לאחר גלות שבט ראובן גד וחצי שבט המנשה? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בספר ירמיה, שחי שנים לאחר מכן: \u0003\"מקץ שבע שנים תשלחו איש את אחיו העברי אשר ימכר לך\u0004 ועבדך שש שנים ושלחתו חפשי מעמך, ולא שמעו אבותיכם אלי ולא הטו את אזנם\" (ירמיה לד, יד),","\u0003והוינן בהו\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים \u0005בהם]:\u0006 האם \u0003\"מקץ שבע שנים\"? והכתיב\u0004 \u0005[והרי נאמר\u0006 שם\u0005]:\u0006 \u0003\"ועבדך שש שנים\",\u0004 ולא שבע! \u0003ואמר רב נחמן בר יצחק: שש\u0004 שנים הוזכרו ביחס \u0003לנמכר\u0004 רגיל, שיוצא בסיום שש שנות עבדות (שמות כא, ב), \u0003ו\u0004אילו \u0003שבע\u0004 שנים הוזכרו ביחס \u0003ל\u0004עבד \u0003נרצע,\u0004 הנשאר כעבד בבית אדונו, שיוצא ביובל אפילו אם הגיע היובל כעבור שנה מרציעתו. ומכאן עולה שהיובל נהג בימי ירמיה, למרות שלא היו כל השבטים במקומם!","ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 לא כציווי נאמר על ידי ירמיה, אלא \u0003ב\u0004תוך \u0003תוכחה כתיב\u0004 \u0005[נאמר],\u0006 שכך ציוה ה' את ישראל בצאתם ממצרים, \u0003וקאמר\u0004 \u0005[ו\u0006על כך \u0005אומר]\u0006 ה\u0003נביא: השלחתם\u0004 את העבדים הנרצעים בזמן שהיה היובל נוהג? ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 שם: \u0003\"וישמעו וישלחו\"\u0004 (ירמיה לד, י), כלומר, דברים אלו שדיבר עליהם ירמיה נתרחשו באותה שעה!","\u0003אלא\u0004 יש להסביר דבר זה לפי מה ש\u0003אמר ר' יוחנן:\u0004 למרות שהיובלות בטלו בגלות ראובן גד וחצי שבט מנשה, \u0003ירמיה החזירן\u0004 לעשרת השבטים שגלו, \u0003ויאשיה בן אמון מלך עליהן\u0004 על כל ישראל, ובאותה שעה חזר היובל לנהוג. \u0003ומנא לן דהדור\u0004 \u0005[ומנין לנו שחזרו\u0006 השבטים\u0005]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי יחזקאל, שחי בדורו של ירמיה, והתנבא על העתיד: \u0003\"כי המוכר אל הממכר לא ישוב\"\u0004 (יחזקאל ז, יג), כלומר, מי שמכר את שדהו — לא ישוב אליו השדה ביובל. ויש לתמוה: \u0003אפשר יובל\u0004 כבר \u0003בטל,\u0004 שהרי כבר גלו השבטים, \u0003ו\u0004ה\u0003נביא\u0004 יחזקאל \u0003מתנבא עליו\u0004 שעתיד \u0003שיבטל? אלא מלמד שהחזירן ירמיה\u0004 אחר גלותם, וחזרו ישראל למנות יובלות, ובאותו זמן התנבא יחזקאל שהיובל יתבטל.","ושואלים: \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003יאשיה מלך עליהן?\u0004 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ויפן יאשיהו וירא את הקברים... \u0003ויאמר מה הציון הלז אשר אני ראה. ויאמרו אליו אנשי העיר הקבר איש האלהים אשר בא מיהודה ויקרא את הדברים\u0004 האלה אשר עשית \u0003על המזבח בית אל\"\u0004 (מלכים ב כג, טז—יז), וקשה,","\u0003וכי מה טיבו של יאשיהו\u0004 מלך יהודה \u0003בבית אל,\u0004 שהיתה בתחומי ממלכת ישראל, ולא ביהודה? \u0003אלא כשהחזירן ירמיהו, יאשיהו מלך עליהם,\u0004 על כל השבטים, שחזרו למקומם. \u0003רב נחמן בר יצחק אמר, מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה, מדברי הושע לישראל: \u0003\"גם יהודה שת קציר לך בשובי שבות עמי\"\u0004 (הושע ו, יא), כלומר, כאשר ישובו ישראל — יעמוד בראשם מלך יהודה.","\u0003בתי החצרים,\u0004 שנזכרו בתורה (ויקרא כה, לא), שאינם בתי ערי חומה, אם מכרום בעליהם — \u0003נותנין להם כח יפה ש\u0004יש \u0003בבתי ערי חומה וכח יפה שבשדות, ו\u0004כיצד? \u0003נגאלין מיד וכל שנים עשר חדש כ\u0004דין \u0003בתים\u0004 של ערי חומה, ולא רק לאחר שנתיים כשדות, \u0003ויוצאין ביובל\u0004 לבעלים, \u0003ו\u0004קודם היובל — \u0003בגרעון כסף, כ\u0004מו ה\u0003שדות,\u0004 שמחשב המוכר כמה קיבל בעד השדה לכל שנה עד היובל, ולפי מספר השנים שחלפו גורע מן הסכום שקיבל מן הקונה. אבל בית ערי חומה נחלט לאחר שנה, ואינו יוצא ביובל. וכשנגאל בתוך שנה — נותן את הסכום המלא שקיבל עבורו.","במקור הדין של משנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 נאמר בתורה: \"ובתי החצרים אשר אין להם חומה סביב \u0003על שדה הארץ יחשב\u0004 גאולה תהיה לו וביובל יצא\" (ויקרא כה, לא) — \u0003הקישו הכתוב\u0004 את בתי החצרים \u0003לשדה אחוזה, מה שדה אחוזה יוצא ביובל\u0004 או \u0003בגרעון כסף\u0004 — \u0003אף בתי החצרים יוצאין ביובל ובגרעון כסף.\u0004","ויש לשאול, \u0003אי\u0004 (אם כן) שמא נאמר גם: \u0003מה שדה אחוזה אינה נגאלת בפחות משתי שנים\u0004 מזמן שנמכרה — \u0003אף בתי החצרים אינם נגאלים\u0004 ב\u0003פחות משתי שנים? תלמוד לומר: \"גאלה תהיה לו\",\u0004 ומשמעות הכתוב היא — \u0003מיד.\u0004 ויש לשאול: \u0003הואיל ונתת להם כח יפה שבשדות וכח (שדה) [יפה] שבבתים, יכול לא יצאו ביובל? תלמוד לומר: \"וביבל יצא\".\u0004","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אומר\u0006 החכם שבברייתא\u0005],\u0006 כלומר, מדוע הוצרך ללימוד זה? והרי אמר מתחילה שנותנים לו כח היפה שבשדות, שיוצאים ביובל! \u0003אמר רב הונא:\u0004 באמת \u0003לא נצרכא\u0004 \u0005[לא נצרך]\u0006 הכתוב למוכר, \u0003אלא למקדיש בית בבתי החצרים, וגאלו\u0004 אדם \u0003אחר מיד הקדש, ופגע בו יובל ב\u0004תוך ה\u0003שנה\u0004 ה\u0003שניה\u0004 לגאולת הבית מיד ההקדש, ללמד שהוא חוזר לבעליו הראשונים.","שכן \u0003למאי מדמית ליה\u0004 \u0005[למה אתה מדמה אותו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לבתי ערי חומה\u0004 שהוקדשו וגאלם אחר \u0003מדמית ליה\u0004 \u0005[אתה מדמה אותו]\u0006 — \u0003איחליט ליה\u0004 \u0005[הוחלט לו\u0006 הבית\u0005]\u0006 \u0003ללוקח\u0004 כבר בתום השנה הראשונה, כפי ששנינו בברייתא לעיל (לא,ב), \u0003אי\u0004 \u0005[אם]\u0006 \u0003לשדה אחוזה\u0004 שהוקדשה וגאלה אחר \u0003מדמית\u0004 \u0005[אתה מדמה\u0006 אותו\u0005]\u0006 — \u0003לכהנים נפקא\u0004 \u0005[יוצאת]\u0006 ביובל, כפי ששנינו במשנה לעיל (כה,א)! \u0003להכי אצטריך\u0004 \u0005[לכך הוצרך\u0006 הכתוב לומר\u0005]\u0006 \u0003\"וביבל יצא\"\u0004 — ללמדנו שבתי החצרים חוזרים במקרה זה לבעליהם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב זעירא: מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע לפרש כתוב זה דווקא במקרה ש\u0003גאלו אחר\u0004 מיד ההקדש? \u0003אפילו לא גאלו\u0004 אחר \u0003נמי\u0004 \u0005[גם כן]\u0006 יצא מיד ההקדש לבעליו, שהרי אמר הכתוב בסתם: \"וביובל יצא\"! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אין לומר כן, כדי \u0003שלא יאמרו\u0004 האנשים: \u0003הקדש\u0004 \u0003יוצא\u0004 לבעליו מיד ההקדש \u0003בלא פדיון.\u0004","ומוסיפים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שאכן בית שהוקדש אינו יוצא מן ההקדש בלא פדיון? \u0003מבן לוי, מה בן לוי שיפה כחו בממכרו\u0004 יותר מישראל, שגואל לעולם שדה או בית שמכר (ראה משנה להלן עמוד ב) — \u0003הורע כחו בהקדשו,\u0004 שצריך לפדות את הקדשו, ואינו חוזר אליו ביובל בחינם, כפי שיתבאר, \u0003ישראל שהורע כחו בממכרו,\u0004 שאם מכר שדה אחוזה אינו יכול לגואלה בשנתיים הסמוכות למכירתה, וכן אם מכר בית בעיר חומה יכול לגואלו רק בתוך שנה — \u0003אין דין שהורע כחו בהקדשו,\u0004 שאם הקדיש בית בבתי החצרים והגיע היובל, שצריך לפדותו מיד ההקדש?","ומוסיפים: \u0003והתם מנלן\u0004 \u0005[ושם מנין לנו]\u0006 שאין הקדשו של בן לוי חוזר אליו בחינם ביובל? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 נאמר בתורה: \"ואשר יגאל מן הלוים, ויצא ממכר בית ועיר אחוזתו ביובל\" (ויקרא כה, לג), ומהכתוב \u0003\"ויצא ממכר\" שומע אני\u0004 לכאורה, כי כל מה שמכר הלוי חוזר אליו ביובל, \u0003אפילו\u0004 מכר הלוי \u0003עבדיו מטלטליו ושטריו\u0004 — על כן \u0003תלמוד לומר: \"בית ועיר אחזתו\",\u0004 ולא דברים אחרים.","ויש לשאול: אם כך \u0003מה תלמוד לומר \"ממכר\"?\u0004 לדייק ממנו: דוקא \u0003ממכריו,\u0004 אם מכר בית ועיר אחוזתו — \u0003יוצא\u0004 ביובל \u0003בחנם, ואין הקדש\u0004 של הלוי \u0003יוצא בחנם\u0004 ביובל, \u0003אלא בפדיון.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעת רב הונא, שאם הקדיש בית חצרים וגאלה אחר מיד ההקדש, שחוזרת לבעלים ביובל, על דעת \u0003ר' אושעיא,\u0004 ש\u0003אמר ר' אושעיא: הכל היו בכלל \"ונתן הכסף וקם לו\"\u0004 (ראה שם כז, יט), שהגואל דבר מיד ההקדש נחשב מעתה לבעליו לגמרי, ו","\u0003כשפרט הכתוב בשדה אחוזה \"והיה השדה בצאתו ביבל קדש לה'\u0004 וכו' לכהן תהיה\" (שם כא), ללמד שאם הקדישה הבעלים וגאלה אחר מן ההקדש, יוצאת השדה ביובל לכהנים — למדנו מכאן כי דווקא ב\u0003שדה הוא\u0004 \u0003דפרק ליה\u0004 \u0005[שפודה אותו]\u0006 \u0003ונפקא\u0004 \u0005[ו\u0006למרות זאת \u0005יוצא]\u0006 מידיו \u0003לכהנים\u0004 ביובל, \u0003אבל הנך\u0004 \u0005[אלה],\u0006 בתי החצרים שהוקדשו, וגאלם אחר מיד ההקדש — \u0003כדקיימי קיימי\u0004 \u0005[כמו שהם עומדים עומדים],\u0006 ברשות מי שפדה אותם, ואינם יוצאים להקדש, וגם לא לבעלים הראשונים כפי שסבור רב הונא.","ושואלים: אם כן, הכתוב \u0003\"וביבל יצא\"\u0004 ממנו למד רב הונא, לשיטת רב אושעיא \u0003למה לי? אמר רב פפא: לא נצרכא\u0004 \u0005[לא נצרך]\u0006 כתוב זה \u0003אלא למוכר בית בבתי החצרים ופגע בו יובל בשנה שניה,\u0004 ללמד שהוא חוזר למוכר.","שכן יש לשאול: \u0003למאי מדמית ליה\u0004 \u0005[למה אתה מדמה אותו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004מוכר \u0003בתי ערי חומה מדמית ליה\u0004 \u0005[אתה מדמה אותו]\u0006 — הרי בית חומה כבר \u0003איחלט ליה\u0004 \u0005[הוחלט לו]\u0006 הבית \u0003ללוקח\u0004 בתום השנה ראשונה, ואינו יוצא ביובל. \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004מוכר \u0003שדה אחוזה מדמית ליה\u0004 \u0005[אתה מדמה אותו],\u0006 הרי הקונה שדה אחוזה פחות משנתיים לפני היובל — \u0003השלמה בעי\u0004 \u0005[צריך],\u0006 שהיא נשארת בידו שנה נוספת לאחר היובל, עד שיאכל ממנה שתי שנות תבואה (לעיל כט,ב), \u0003להכי אצטריך\u0004 \u0005[לכך הוצרך]\u0006 לומר הכתוב בבתי החצרים: \u0003\"וביבל יצא\"\u0004 — ללמד שהבית חוזר לבעליו, ואינו נשאר שנה נוספת ביד הקונה לאחר היובל.","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב הונא ותיובתא\u0004 \u0005[ו\u0006היא \u0005קושיה]\u0006 על דברי \u0003רבי אושעיא: המקדיש בית בבתי החצרים\u0004 — \u0003הרי זה גואל מיד וגואלו לעולם;\u0004 ואם \u0003גאלו אחר מיד הקדש,\u0004 ו\u0003הגיע יובל ולא נגאל\u0004 — אין הבית נשאר ביד הפודה, אלא \u0003חוזר לבעלים ביובל.\u0004"],["\u0003ואלו הן בתי החצרים\u0004 ששנינו דינם במשנה הקודמת: \u0003שני חצרים של שני בתים\u0004 בכל חצר, \u0003אף על פי שמוקפת\u0004 (מוקפים) \u0003חומה מימות יהושע בן נון\u0004 — \u0003הרי הן כבתי חצרים.\u0004","במקורה של ההלכה ששנינו במשנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003ממשמע שנאמר\u0004 \"ו \u0003בתי החצרים\"\u0004 (ויקרא כה, לא) \u0003איני יודע שאין להם חומה?\u0004 אם כן \u0003מה תלמוד לומר\u0004 בהמשך הכתוב שם: \u0003\"אשר אין להם חומה\"?\u0004 לומר: יש בתי חצרים ש\u0003אף על פי שיש להם חומה\u0004 נחשבים הם \u0003כמי שאין להם חומה. וכמה?\u0004 מיעוט לשון \u0003\"בתים\"\u0004 הוא \u0003שנים,\u0004 ומיעוט \u0003\"חצירות\"\u0004 (חצרים) הוא \u0003שנים,\u0004 ולפיכך אם יש בעיר רק \u0003שתי חצירות של שני בתים\u0004 בכל חצר — נחשבת העיר לבתי חצרים.","ומקשים, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי \"בתי החצרים\" הם \u0003בית וחצר,\u0004 בית וחצר. אבל כשבכל חצר יש שני בתים — נחשבת העיר המוקפת כשאר המוקפות! ומשיבים: \u0003אם כן, ליכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003\"חצרים\",\u0004 ודי בכך, שהרי אין חצר בלא בית. \u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 רק \u0003\"חצרים\",\u0004 הייתי טועה לומר ש\u0003חצר בלא בית\u0004 בתוכה \u0003משמע,\u0004 ואם יש בהן בתים דינן כבית עיר חומה — לא הייתי טועה בכך, שהרי \u0003ההוא קרפף איקרי\u0004 \u0005[נקרא]\u0006 ולא \"חצר\".","\u0003ישראל שירש\u0004 בית בעיר חומה מ\u0003אבי אמו\u0004 ה\u0003לוי,\u0004 שהיה לו בית באחת מערי הלויים — אינו גואל כסדר הזה ששנינו בפרקנו לגבי בית עיר חומה, שיכול לגאול רק בתוך שנה, ולאחר מכן הריהו של הקונה לצמיתות. אלא יכול לגאול מיד, ובכל מקרה הריהו חוזר אליו ביובל. \u0003וכן לוי שירש את אבי אמו ישראל אינו גואל כסדר הזה.\u0004","\u0003שנאמר:\u0004 \"ואשר יגאל מן הלוים ויצא ממכר בית ועיר אחוזתו ביובל \u0003כי בתי ערי הלוים הוא אחזתם\u0004 בתוך בני ישראל\" (ויקרא כה, לג), לומר שדין גאולת בתי ערי הלויים אינו חל \u0003עד שיהא\u0004 הגואל (המוכר) \u0003לוי ו\u0004הבית ב\u0003ערי הלוים,\u0004 אלו \u0003דברי רבי. וחכמים אומרים: אין דברים הללו אמורים אלא בערי הלוים,\u0004 ואין צריך שיהיה הגואל לוי.","על מה ששנינו במשנתנו: ישראל שירש אבי אמו לוי אינו גואל בית עיר חומה כסדר הזה, אומרים: \u0003ואלא כמאן\u0004 \u0005[כמי]\u0006 הוא גואל — \u0003כבן לוי; והדר תני\u0004 \u0005[ו\u0006אולם הוא \u0005חוזר ושונה]\u0006 בסיום דבריו: \u0003עד שיהא לוי וערי הלוים,\u0004 ומשמע מכך שישראל שירש את הלוי גואל כישראל!","ומשיבים, \u0003אימא\u0004 \u0005[אמור]\u0006 כך: ישראל שירש אבי אמו לוי \u0003אינו גואל אלא כסדר הזה\u0004 ששנינו בפרקנו, שיכול לגאול בתוך שנה, ולאחר מכן חלוט הבית לקונה, \u0003עד שיהא\u0004 הגואל \u0003לוי ו\u0004ב\u0003ערי הלוים,\u0004 ואז הוא גואל לעולם, ובכל מקרה חוזר אליו הבית ביובל. אלו \u0003דברי רבי.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן\u0005]\u0006 מה שצריכה הנחלה להיות מ\u0003ערי הלויים\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 שם: \u0003\"כי בתי ערי הלוים\u0004 היא אחוזתם\" (ויקרא כה, לג), \u0003אלא\u0004 שצריך שגם המוכר יהיה \u0003לוי מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"ואשר יגאל מן הלוים...\u0004 ויצא ביובל\", הרי שדין זה אמור דווקא בלוי שגואל, ולא במי שאינו לוי.","וכן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין זה: הואיל ונאמר מתחילה \"גאולת עולם תהיה ללויים\" (שם לב), מה שנאמר לאחר מכן: \u0003\"ואשר יגאל מן הלוים\u0004 ויצא ממכר בית ועיר אחוזתו ביובל\" מה בא ללמד? שאם לא כתוב זה, \u0003יכול\u0004 אתה לומר: \u0003לוי מישראל\u0004 \u0003יגאל\u0004 לעולם בית שמכר לו, \u0003ש\u0004הרי \u0003זה\u0004 הלוי \u0003יפה כחו\u0004 שגואל לעולם, \u0003וזה\u0004 הישראל \u0003הורע כחו,\u0004 שאינו גואל אלא בתוך שנה, \u0003אבל לוי מלוי\u0004 — \u0003לא\u0004 יגאל לעולם, אלא בתוך שנה, \u0003ש\u0004הרי גם \u0003זה יפה כחו ו\u0004גם \u0003זה יפה כחו\u0004 — \u0003תלמוד לומר:\u0004 \"ואשר יגאל \u0003מן הלוים\",\u0004 לומר: גם אם הלוי גואל מיד לוי — חוזר הבית ביובל.","ועוד דורשים: מה שנאמר \u0003\"מן הלוים\"\u0004 הוא לשון מיעוט — חלק מן הלויים יכולים לגאול לעולם, \u0003ולא כל הלוים\u0004 — \u0003פרט לבן לוי\u0004 שהוא \u0003ממזר\u0004 או \u0003נתין\u0004 (שאמו מן הגבעונים שנפסלו מלבוא בקהל, ראה יבמות עח,ב), ואם ירש בן כזה את אביו ומכר מנחלת הלויים — אינו גואל כלוי.","שנינו במשנתנו, \u0003וחכמים אומרים: אין דברים הללו אמורים אלא בערי הלוים.\u0004 ומסבירים: \u0003אבל עד שיהא\u0004 המוכר עצמו \u0003לוי, לא אמרינן\u0004 \u0005[לא אומרים אנו].\u0006 ולפיכך, לדעתם, גם מי שאינו לוי, אם ירש נחלה בערי הלויים — גואל כסדר גאולת הלויים.","נאמר בתורה כי יש לתת ללויים אלפיים אמה סביב עריהם, אלף למגרש (שטח פנוי) ועוד אלף אמה לשדות וכרמים. ועל כך אמרו חכמים כי \u0003אין עושין\u0004 מ\u0003שדה מגרש, ולא\u0004 מ\u0003מגרש שדה, ו\u0004כן \u0003לא\u0004 עושים מ\u0003מגרש עיר, ולא\u0004 עושים מ\u0003עיר מגרש.\u0004","\u0003אמר ר' אלעזר: במה דברים אמורים? בערי הלוים,\u0004 שכך ציותה התורה, \u0003אבל בערי ישראל עושין\u0004 מ\u0003שדה מגרש, ולא\u0004 עושים \u0003ממגרש שדה,\u0004 ועושים מ\u0003מגרש עיר, ולא\u0004 עושים את ה\u0003עיר מגרש,\u0004 כדי \u0003שלא יחריבו את ערי ישראל. הכהנים והלוים מוכרין\u0004 שדותיהם ובתיהם \u0003לעולם, וגואלין\u0004 אותם \u0003לעולם, שנאמר: \"גאלת עולם תהיה ללוים\"\u0004 (ויקרא כה, לב), כלומר, לבני שבט לוי.","שנינו במשנה, \u0003אמר ר' אלעזר: במה דברים אמורים? בערי הלוים, אבל בערי ישראל עושין\u0004 שדה מגרש ולא מגרש שדה, מגרש עיר ולא עיר מגרש, כדי שלא יחריבו את ערי ישראל. ואומרים: \u0003דכולי עלמא מיהא\u0004 \u0005[לדעת הכל על כל פנים]\u0006 \u0003בדלוים לא משנינן\u0004 \u0005[ב\u0006עיר \u0005של הלוים אין אנו משנים],\u0006 ואין עושים משדה מגרש, וכן לא עושים מן המגרש עיר. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006","\u0003אמר ר' אלעזר, דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"ושדה מגרש עריהם לא ימכר\"\u0004 (ויקרא כה, לד) ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא ימכר\"? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003לא ימכר כלל, והא מדכתיב\u0004 \u0005[והרי ממה שנאמר]\u0006 \u0003\"גאלת עולם תהיה ללוים\u0004 — \u0003מכלל דמזבני\u0004 \u0005[מכאן\u0006 יש ללמוד \u0005שהם מוכרים]!\u0006 \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא ימכר\"\u0004 — ש\u0003לא ישנה\u0004 את השדה, את המגרש ואת העיר ממה שהיו.","שנינו במשנה: \u0003הכהנים והלוים מוכרין לעולם וגואלין לעולם.\u0004 ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 מה שנאמר בתורה: \u0003\"גאלת עולם תהיה ללוים\"\u0004 (ויקרא כה, לב), \u0003מה תלמוד\u0004 (בא) \u0003לומר?\u0004 \u0003לפי שנאמר\u0004 בשדה אחוזה של ישראל: \u0003\"במספר שני תבואת ימכר לך\"\u0004 (שם טו), שאינו יכול לגואלה בפחות משנתיים לאחר שמכרה, \u0003יכול אף זה,\u0004 הלוי שמוכר שדהו, דינו \u0003כן? תלמוד לומר: \"גאלת עולם תהיה ללוים\",\u0004 ללמדנו שיכול לגואלה מיד.","ועוד, \u0003לפי שנאמר\u0004 בישראל שהקדיש שדה אחוזתו ולא גאלה: \u0003\"והיה השדה בצאתו ביבל קדש לה'...\u0004 לכהן תהיה אחוזתו\" (שם כז, כא), \u0003יכול אף זה,\u0004 לוי שהקדיש שדהו, דינו \u0003כן? תלמוד לומר: \"גאלת עולם תהיה ללוים\",\u0004 ללמדנו שאינה יוצאת לכהנים ביובל, והלוי גואלה מההקדש לעולם.","ועוד, \u0003לפי שנאמר\u0004 בישראל שמכר בית בעיר חומה: \"ואם לא יגאל עד מלאת לו שנה תמימה \u0003וקם הבית אשר בעיר אשר לו חומה לצמיתת\u0004 לקונה אותו\" (שם כה, ל), \u0003יכול אף זה,\u0004 לוי שמכר ביתו שבעיר חומה, דינו \u0003כן? תלמוד לומר: \"גאלת עולם תהיה ללוים\",\u0004 ללמדנו שיכול לגאול את ביתו גם כעבור שנה, ואין הבית חלוט לקונה.","ומקשים: \u0003בשלמא הני תרתי\u0004 \u0005[נניח שני אלה],\u0006 כלומר, שני הדינים הראשונים, העוסקים בשדות הלויים — \u0003לחיי\u0004 \u0005[בסדר,\u0006 מובן הדבר\u0005],\u0006 \u0003אלא בתי ערי חומה ללוים מי אית להו\u0004 \u0005[האם יש להם],\u0006 שהוצרכנו למעט מן הכתוב? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ערים הללו,\u0004 הניתנות ללויים, \u0003אין עושין אותן,\u0004 כלומר, אין נותנים להם \u0003לא כפרים קטנים, ולא כרכים גדולים, אלא עיירות בינוניות,\u0004 שהן ערים שאינן מוקפות חומה!","\u0003אמר רב כהנא, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן,\u0004 שלא היה ללויים עיר מוקפת חומה, מדובר במקום \u0003ש\u0004תחילה \u0003הוקף\u0004 חומה \u0003ולבסוף ישב,\u0004 \u0003כאן\u0004 בברייתא, שיש ללוי בית בעיר חומה, מדובר במקום \u0003שישב,\u0004 שקיבלו הלויים וישבו בו, \u0003ולבסוף הוקף\u0004 בחומה.","ומתקשים: \u0003וכי האי גוונא\u0004 \u0005[\u0006ב\u0005אופן זה],\u0006 שנתיישב המקום ולבסוף הוקף חומה, \u0003מי הויא\u0004 \u0005[האם היא]\u0006 נחשבת לעיר \u0003חומה\u0004 לענין הבתים שבתוכה? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 מה שנאמר בתורה: \u0003\"ואיש כי ימכר בית מושב עיר חומה\"\u0004 (שם כט), משמעו בית במקום \u0003ש\u0004תחילה \u0003הוקף\u0004 בחומה \u0003ו\u0004רק \u0003לבסוף ישב, ולא ש\u0004תחילה \u0003ישב ולבסוף הוקף\u0004 בחומה.","\u0003יכול אפילו הקיפוה ישראל\u0004 בחומה, ואחר כך בנו בתים בתוכה, תיחשב אף היא לעיר חומה? \u0003נאמר כאן:\u0004 \"ואיש כי ימכר בית מושב עיר \u0003חומה\", ונאמר להלן\u0004 בכיבוש ממלכת עוג מלך הבשן: \"כל אלה ערים בצורות \u0003חומה\u0004 גבוהה דלתים ובריח\" (דברים ג, ה), \u0003מה להלן\u0004 מדובר בעיר שהקיפוה \u0003גוים, אף כאן,\u0004 דין בית עיר חומה נאמר דווקא בעיר שהקיפוה \u0003גוים.\u0004","\u0003יכול אפילו הקיפוה גוים לאחר מכן,\u0004 כלומר, לאחר כיבוש הארץ? \u0003נאמר להלן\u0004 בערים שנכבשו בבשן: \u0003\"חומה\", ונאמר כאן\u0004 בדין הבית: \u0003\"חומה\", מה להלן\u0004 מדובר שהקיפוה \u0003גוים קודם לכן,\u0004 כלומר, קודם הכיבוש, \u0003אף כאן,\u0004 דין הבית נאמר דווקא בעיר שהקיפוה \u0003גוים קודם לכן.\u0004 ונמצא שאם לאחר שנכנסו הלויים לעיר הקיפוה חומה — אין לבתים שבה דין בית בעיר חומה, ושלא כתירוץ רב כהנא!","\u0003תרגמה\u0004 \u0005[תרגם,\u0006 הסביר \u0005אותה,\u0006 את הברייתא\u0005]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב סלא חסידא\u0004 \u0005[החסיד]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא:\u0004 מדובר בה \u0003כגון שנפלו להן\u0004 ללויים בגורל בזמן הנחלת הארץ"],["\u0003הן,\u0004 כלומר, הערים \u0003ומגרשיהן,\u0004 כשהן מוקפות חומה. ושואלים: \u0003הן ומגרש,\u0004 הרי \u0003למיסתרינהו קיימי\u0004 \u0005[לסתירה\u0006 \u0005הם עומדים]\u0006 באותה שעה, וכיצד ניתן לקרוא להן מוקפות חומה! \u0003אמר רב אשי: איצטריך\u0004 \u0005[הוצרך הדבר\u0006 להיאמר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003אדמסתתרי מסתתרי\u0004 \u0005[בעת ש\u0006החומות \u0005סתורות,\u0006 אכן דינם כ\u0005סתורות],\u0006 אבל כל זמן שלא נסתרו החומות \u0003אי מיזדבני\u0004 \u0005[אם נמכרים\u0006 בתים שבעיר\u0005]\u0006 ולא נפדים בתוך שנה — \u0003ליחלטו\u0004 \u0005[שיהיו מוחלטים]\u0006 לקונה כדין בתי ערי חומה, על כן \u0003קא משמע לן\u0004 \u0005[משמיעה לנו]\u0006 הברייתא שבתי ערי הלויים אינם נחלטים לקונה, אלא נגאלים לעולם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 מה שנאמר בתורה לגבי שדה שהוקדשה על ידי בעליה ולא נגאלה: \"והיה השדה בצאתו ביובל קדש לה' \u0003כשדה החרם לכהן תהיה אחזתו\"\u0004 (ויקרא כז, כא), \u0003מה תלמוד\u0004 (רוצה) \u0003לומר?\u0004 מה עניינה של השוואה זו לשדה חרם? שכן יש לשאול: \u0003מנין לכהן שהקדיש שדה חרמו,\u0004 כלומר, שדה שהחרים ישראל וניתנה לו, והוא מחזיק בה עדיין, והגיעה שנת היובל, מנין \u0003שלא יאמר: הואיל ו\u0004שדה שהוקדשה ולא נגאלה \u0003יוצא לכהנים\u0004 ביובל, \u0003והרי\u0004 שדה זו שהקדשתי \u0003היא תחת ידי,\u0004 לפיכך \u0003תהא שלי,\u0004 שהרי אני כהן? \u0003ו\u0004לכאורה \u0003דין,\u0004 קל וחומר \u0003הוא,\u0004 אם \u0003בשל אחרים,\u0004 כלומר, בשדה אחוזה שהקדישה ישראל ולא גאלה, \u0003אני זוכה\u0004 בהגיע היובל, \u0003בשל עצמי לא כל שכן? תלמוד לומר: \"והיה השדה בצאתו ביבל קדש לה' כשדה החרם\",\u0004 ויש לשאול:","","\u0003וכי מה למדנו משדה החרם מעתה,\u0004 והרי דין שדה החרם לא התבאר בתורה במקום אחר! אלא \u0003הרי זה בא ללמד ונמצא למד, מקיש\u0004 הכתוב \u0003שדה חרמו\u0004 שקיבל הכהן, \u0003לשדה אחוזה של ישראל,\u0004 \u0003מה שדה אחוזה של ישראל\u0004 שפדה אותה כהן מיד ההקדש, \u0003יוצא מתחת ידו\u0004 בהגיע היובל, \u0003ומתחלקת ל\u0004כל ה\u0003כהנים\u0004 (כפי ששנינו לעיל כה,א), \u0003אף שדה חרמו\u0004 שקיבל הכהן והקדישה — \u0003יוצא מתחת ידו ומתחלקת לאחיו הכהנים.\u0004","ומבררים ברייתא זו, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 ודין הוא \u0003בשל אחרים אני זוכה\u0004 בשל עצמי לא כל שכן? ותוהים: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]\u0006 שהוצרך הכתוב ללמד שאין אומרים כן? והלא \u0003התם\u0004 \u0005[שם],\u0006 בשדה אחוזה שהוקדשה ויוצאה לכהנים — \u0003זוכה בעלמא\u0004 \u0005[בלבד]\u0006 הוא, כאחד מן הכהנים, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בשדה חרם שהקדישה \u0003קא שקיל ליה\u0004 \u0005[הריהו רוצה ליטול אותו]\u0006 לעצמו, ולא הוצרך מקרא כדי לשלול דבר זה!","\u0003אמר רמי בר חמא: איצטריך\u0004 \u0005[הוצרך\u0006 הכתוב להיאמר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ואיש את קדשיו לו יהיו\"\u0004 (במדבר ה, י), ולמדים משם שכהן הבא להקריב את קרבנו — רשאי להקריבו בעצמו, ונוטל ממנו את החלקים הראויים לכהנים, ואינו חייב ליתנו לכל כהני המשמר, יש לומר כי \u0003הא נמי\u0004 \u0005[זה גם כן]\u0006 שדה חרמו שהקדיש, והיא עכשיו בידו בשנת היובל — \u0003כי קדשיו דמיא\u0004 \u0005[כמו\u0006 מקריב \u0005קדשיו היא נחשבת],\u0006 ויטול אותה לעצמו.","ומקשים: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 והרי המקריב את \u0003קדשיו לאו\u0004 \u0005[אינם]\u0006 \u0003ברשותו,\u0004 אלא לשמים הם קרבים, והוא כזוכה משולחן גבוה בשכר עבודתו, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 הוא רוצה שהשדה תישאר \u0003ברשותו,\u0004 ומדוע שנטעה לומר כך?","\u0003אלא אמר רב נחמן: איצטריך\u0004 \u0005[הוצרך\u0006 הכתוב להיאמר\u0005],\u0006 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 בשדות הלויים והכהנים: \u0003\"כי אחזת עולם הוא להם\"\u0004 (ויקרא כה, לד), ולמדים משם שאם הקדיש הכהן שדה אחוזת אבותיו יכול לגואלה לעולם, הייתי טועה לומר כי \u0003הא\u0004 \u0005[זו],\u0006 שדה חרם שקיבל, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אחזתו היא,\u0004 ואם הקדישה יכול לגואלה לעולם, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ההיקש של שדה החרם שביד הכהן לשדה אחוזה של ישראל, שאין אומרים כן, וכפי שמדוייק מהמשך הפסוק: \"לכהן תהיה \u0003אחזתו\", אחוזתו\u0004 של הכהן, שנחל מאבותיו — \u0003אין\u0004 \u0005[כן]\u0006 היא של הכהן לעולם, ואינה מתחלקת לשאר הכהנים ביובל, אבל שדה \u0003חרמו\u0004 — \u0003לא,\u0004 והיא מתחלקת לכהני המשמר שפגע בו יובל.",""]]};
